window.VQ_CURRICULUM = (window.VQ_CURRICULUM || []).concat([{"id":"a2-set-01","title":"The Gadget That Disappeared","subtitle":"A2 reading adventure 01","level":"A2","set":1,"emoji":"🌱","color":"#37BE9C","words":[{"term":"electric","meaning":"كهربائي","example":"It contained information about an electric gadget.","number":1,"id":"a2:001","level":"A2","lessonId":"a2-set-01"},{"term":"electricity","meaning":"كهرباء","example":"Inside, the inventor had trouble with his electricity.","number":2,"id":"a2:002","level":"A2","lessonId":"a2-set-01"},{"term":"software","meaning":"برمجيات","example":"His computer software refused to open the program.","number":3,"id":"a2:003","level":"A2","lessonId":"a2-set-01"},{"term":"click","meaning":"ينقر","example":"Click on this web page,' he said.","number":4,"id":"a2:004","level":"A2","lessonId":"a2-set-01"},{"term":"web page","meaning":"صفحة ويب","example":"Click on this web page,' he said.","number":5,"id":"a2:005","level":"A2","lessonId":"a2-set-01"},{"term":"printer","meaning":"طابعة","example":"They decided to include a safety warning in their report and print it on the printer.","number":6,"id":"a2:006","level":"A2","lessonId":"a2-set-01"},{"term":"technology","meaning":"تكنولوجيا","example":"Technology is useful only when it is safe,' she said.","number":7,"id":"a2:007","level":"A2","lessonId":"a2-set-01"},{"term":"program","meaning":"برنامج","example":"His computer software refused to open the program.","number":8,"id":"a2:008","level":"A2","lessonId":"a2-set-01"},{"term":"wifi","meaning":"واي فاي","example":"And his wifi stopped working.","number":9,"id":"a2:009","level":"A2","lessonId":"a2-set-01"},{"term":"information","meaning":"معلومات","example":"It contained information about an electric gadget.","number":10,"id":"a2:010","level":"A2","lessonId":"a2-set-01"},{"term":"by","meaning":"بواسطة أو بجانب","example":"The inventor was amazed by their strong teamwork.","number":11,"id":"a2:011","level":"A2","lessonId":"a2-set-01"},{"term":"file","meaning":"ملف","example":"A man with a white beard had sent them a strange file.","number":12,"id":"a2:012","level":"A2","lessonId":"a2-set-01"},{"term":"gas","meaning":"غاز","example":"They discovered a broken fan beside a gas heater.","number":13,"id":"a2:013","level":"A2","lessonId":"a2-set-01"},{"term":"post","meaning":"بريد","example":"Mina and Leo planned to meet by the post office.","number":14,"id":"a2:014","level":"A2","lessonId":"a2-set-01"},{"term":"beard","meaning":"لحية","example":"A man with a white beard had sent them a strange file.","number":15,"id":"a2:015","level":"A2","lessonId":"a2-set-01"},{"term":"difference","meaning":"اختلاف","example":"Can you spot the difference?' Mina asked.","number":16,"id":"a2:016","level":"A2","lessonId":"a2-set-01"},{"term":"each other","meaning":"بعضهم بعضا","example":"The children helped each other check the machine.","number":17,"id":"a2:017","level":"A2","lessonId":"a2-set-01"},{"term":"further","meaning":"أبعد","example":"After a further check, the gadget worked again.","number":18,"id":"a2:018","level":"A2","lessonId":"a2-set-01"},{"term":"include","meaning":"يشمل","example":"They decided to include a safety warning in their report and print it on the printer.","number":19,"id":"a2:019","level":"A2","lessonId":"a2-set-01"},{"term":"meet","meaning":"يقابل","example":"Mina and Leo planned to meet by the post office.","number":20,"id":"a2:020","level":"A2","lessonId":"a2-set-01"},{"term":"opposite","meaning":"مقابل","example":"Opposite an old inventor's house.","number":21,"id":"a2:021","level":"A2","lessonId":"a2-set-01"},{"term":"repeat","meaning":"يكرر","example":"The inventor wanted to repeat the test, but Mina suggested they wait.","number":22,"id":"a2:022","level":"A2","lessonId":"a2-set-01"},{"term":"strong","meaning":"قوي","example":"The inventor was amazed by their strong teamwork.","number":23,"id":"a2:023","level":"A2","lessonId":"a2-set-01"},{"term":"trouble","meaning":"مشكلة","example":"Inside, the inventor had trouble with his electricity.","number":24,"id":"a2:024","level":"A2","lessonId":"a2-set-01"},{"term":"without","meaning":"بدون","example":"Leo switched the gas off without touching the heater.","number":25,"id":"a2:025","level":"A2","lessonId":"a2-set-01"}],"story":{"title":"The Gadget That Disappeared","paragraphs":["Mina and Leo planned to meet by the post office, opposite an old inventor's house. A man with a white beard had sent them a strange file. It contained information about an electric gadget, but the pictures looked different from the real machine. 'Can you spot the difference?' Mina asked.","Inside, the inventor had trouble with his electricity. His computer software refused to open the program, and his wifi stopped working. 'Click on this web page,' he said. The children helped each other check the machine. They discovered a broken fan beside a gas heater. That was dangerous! Leo switched the gas off without touching the heater.","The inventor wanted to repeat the test, but Mina suggested they wait. 'Technology is useful only when it is safe,' she said. They decided to include a safety warning in their report and print it on the printer. After a further check, the gadget worked again. The inventor was amazed by their strong teamwork. 'I may be old,' he laughed, 'but I can still learn from you!'"],"questions":["Where did the children meet?","What two technical problems did the inventor have?","Why did Mina want to wait before another test?","What does the ending suggest about learning?"]}},{"id":"a2-set-02","title":"The Secret Message","subtitle":"A2 reading adventure 02","level":"A2","set":2,"emoji":"🌱","color":"#37BE9C","words":[{"term":"social media","meaning":"وسائل التواصل الاجتماعي","example":"Including through social media.","number":26,"id":"a2:026","level":"A2","lessonId":"a2-set-02"},{"term":"chat","meaning":"دردشة","example":"They opened a web page about the town museum and started a chat with its information desk.","number":27,"id":"a2:027","level":"A2","lessonId":"a2-set-02"},{"term":"text message","meaning":"رسالة نصية","example":"At four o'clock, Ben received a text message from an unknown number.","number":28,"id":"a2:028","level":"A2","lessonId":"a2-set-02"},{"term":"conversation","meaning":"محادثة","example":"His friend Aya joined the conversation.","number":29,"id":"a2:029","level":"A2","lessonId":"a2-set-02"},{"term":"send","meaning":"يرسل","example":"We cannot send private details to strangers,' Aya warned.","number":30,"id":"a2:030","level":"A2","lessonId":"a2-set-02"},{"term":"contact","meaning":"يتواصل مع","example":"He tried to contact the sender by telephone.","number":31,"id":"a2:031","level":"A2","lessonId":"a2-set-02"},{"term":"mail","meaning":"بريد","example":"The children checked their mail and found another clue.","number":32,"id":"a2:032","level":"A2","lessonId":"a2-set-02"},{"term":"web","meaning":"شبكة الإنترنت","example":"They opened a web page about the town museum and started a chat with its information desk.","number":33,"id":"a2:033","level":"A2","lessonId":"a2-set-02"},{"term":"video","meaning":"فيديو","example":"The club had posted a short video on its channel.","number":34,"id":"a2:034","level":"A2","lessonId":"a2-set-02"},{"term":"channel","meaning":"قناة","example":"The club had posted a short video on its channel.","number":35,"id":"a2:035","level":"A2","lessonId":"a2-set-02"},{"term":"document","meaning":"مستند","example":"They easily found the document there.","number":36,"id":"a2:036","level":"A2","lessonId":"a2-set-02"},{"term":"at","meaning":"عند أو في","example":"At four o'clock, Ben received a text message from an unknown number.","number":37,"id":"a2:037","level":"A2","lessonId":"a2-set-02"},{"term":"telephone","meaning":"هاتف","example":"He tried to contact the sender by telephone.","number":38,"id":"a2:038","level":"A2","lessonId":"a2-set-02"},{"term":"vocabulary","meaning":"مفردات","example":"The club wanted to teach new vocabulary as well.","number":39,"id":"a2:039","level":"A2","lessonId":"a2-set-02"},{"term":"because of","meaning":"بسبب","example":"Because of their careful questions.","number":40,"id":"a2:040","level":"A2","lessonId":"a2-set-02"},{"term":"discover","meaning":"يكتشف","example":"Look under the old round table.' 'Did you discover anything?' Ben asked.","number":41,"id":"a2:041","level":"A2","lessonId":"a2-set-02"},{"term":"easily","meaning":"بسهولة","example":"They easily found the document there.","number":42,"id":"a2:042","level":"A2","lessonId":"a2-set-02"},{"term":"future","meaning":"مستقبل","example":"It was about how people might communicate in the future.","number":43,"id":"a2:043","level":"A2","lessonId":"a2-set-02"},{"term":"including","meaning":"بما في ذلك","example":"Including through social media.","number":44,"id":"a2:044","level":"A2","lessonId":"a2-set-02"},{"term":"memory","meaning":"ذاكرة","example":"Our memory of this adventure will last,' Aya said.","number":45,"id":"a2:045","level":"A2","lessonId":"a2-set-02"},{"term":"other","meaning":"آخر","example":"They put the other stuff away and shared the wonderful news with the club.","number":46,"id":"a2:046","level":"A2","lessonId":"a2-set-02"},{"term":"round","meaning":"مستدير","example":"Look under the old round table.' 'Did you discover anything?' Ben asked.","number":47,"id":"a2:047","level":"A2","lessonId":"a2-set-02"},{"term":"stuff","meaning":"أشياء","example":"They put the other stuff away and shared the wonderful news with the club.","number":48,"id":"a2:048","level":"A2","lessonId":"a2-set-02"},{"term":"true","meaning":"صحيح","example":"That is true,' Ben agreed.","number":49,"id":"a2:049","level":"A2","lessonId":"a2-set-02"},{"term":"wonderful","meaning":"رائع","example":"They put the other stuff away and shared the wonderful news with the club.","number":50,"id":"a2:050","level":"A2","lessonId":"a2-set-02"}],"story":{"title":"The Secret Message","paragraphs":["At four o'clock, Ben received a text message from an unknown number. 'Can you help us find a lost document?' it asked. Ben thought someone might be joking, but a second message included a photograph of a blue envelope. He tried to contact the sender by telephone.","His friend Aya joined the conversation. They opened a web page about the town museum and started a chat with its information desk. 'We cannot send private details to strangers,' Aya warned. 'That is true,' Ben agreed. Because of their careful questions, they discovered that the message was really from the museum's history club.","The club had posted a short video on its channel, but the important file was missing. The children checked their mail and found another clue: 'Look under the old round table.' 'Did you discover anything?' Ben asked. They easily found the document there. It was about how people might communicate in the future, including through social media. The club wanted to teach new vocabulary as well. 'Our memory of this adventure will last,' Aya said. They put the other stuff away and shared the wonderful news with the club."],"questions":["What first made Ben suspicious?","Why did Aya warn Ben about private details?","How did the children locate the document?","Which action showed responsible online behavior?"]}},{"id":"a2-set-03","title":"The Library of Clues","subtitle":"A2 reading adventure 03","level":"A2","set":3,"emoji":"🌱","color":"#37BE9C","words":[{"term":"article","meaning":"مقال","example":"And an article about a famous writer.","number":51,"id":"a2:051","level":"A2","lessonId":"a2-set-03"},{"term":"magazine","meaning":"مجلة","example":"On a wooden desk lay a newspaper, a magazine, and an article about a famous writer.","number":52,"id":"a2:052","level":"A2","lessonId":"a2-set-03"},{"term":"newspaper","meaning":"صحيفة","example":"On a wooden desk lay a newspaper.","number":53,"id":"a2:053","level":"A2","lessonId":"a2-set-03"},{"term":"news","meaning":"أخبار","example":"It was full of news about a young author who had helped build the town.","number":54,"id":"a2:054","level":"A2","lessonId":"a2-set-03"},{"term":"bookcase","meaning":"خزانة كتب","example":"She found a sheet of paper inside the bookcase.","number":55,"id":"a2:055","level":"A2","lessonId":"a2-set-03"},{"term":"bookshelf","meaning":"رف كتب","example":"A geography map was hidden behind a bookshelf.","number":56,"id":"a2:056","level":"A2","lessonId":"a2-set-03"},{"term":"bookshop","meaning":"متجر كتب","example":"The next clue led them to a bookshop display with a comic about writing and a missing final page.","number":57,"id":"a2:057","level":"A2","lessonId":"a2-set-03"},{"term":"reading","meaning":"قراءة","example":"Look for the oldest bookcase.' Nora and Sami started reading.","number":58,"id":"a2:058","level":"A2","lessonId":"a2-set-03"},{"term":"writing","meaning":"كتابة","example":"The next clue led them to a bookshop display with a comic about writing and a missing final page.","number":59,"id":"a2:059","level":"A2","lessonId":"a2-set-03"},{"term":"writer","meaning":"كاتب","example":"And an article about a famous writer.","number":60,"id":"a2:060","level":"A2","lessonId":"a2-set-03"},{"term":"diary","meaning":"مذكرات يومية","example":"Sami remembered the correct answer from his diary.","number":61,"id":"a2:061","level":"A2","lessonId":"a2-set-03"},{"term":"note","meaning":"ملاحظة","example":"They copied the final note and gave it to the librarian.","number":62,"id":"a2:062","level":"A2","lessonId":"a2-set-03"},{"term":"blackboard","meaning":"سبورة سوداء","example":"Someone had used a blackboard to","number":63,"id":"a2:063","level":"A2","lessonId":"a2-set-03"},{"term":"geography","meaning":"جغرافيا","example":"A geography map was hidden behind a bookshelf.","number":64,"id":"a2:064","level":"A2","lessonId":"a2-set-03"},{"term":"history","meaning":"تاريخ","example":"Someone had used a blackboard to write a question about history.","number":65,"id":"a2:065","level":"A2","lessonId":"a2-set-03"},{"term":"mark","meaning":"علامة أو يصحح","example":"Nora made a mark beside the answer with a rubber stamp.","number":66,"id":"a2:066","level":"A2","lessonId":"a2-set-03"},{"term":"rubber","meaning":"ممحاة","example":"Nora made a mark beside the answer with a rubber stamp.","number":67,"id":"a2:067","level":"A2","lessonId":"a2-set-03"},{"term":"get back","meaning":"يعود","example":"We can get back to the library and finish this ourselves,' Nora said.","number":68,"id":"a2:068","level":"A2","lessonId":"a2-set-03"},{"term":"indoor","meaning":"داخلي","example":"At midday, the library opened a special indoor treasure hunt.","number":69,"id":"a2:069","level":"A2","lessonId":"a2-set-03"},{"term":"midday","meaning":"منتصف النهار","example":"At midday, the library opened a special indoor treasure hunt.","number":70,"id":"a2:070","level":"A2","lessonId":"a2-set-03"},{"term":"ourselves","meaning":"أنفسنا","example":"We can get back to the library and finish this ourselves,' Nora said.","number":71,"id":"a2:071","level":"A2","lessonId":"a2-set-03"},{"term":"scooter","meaning":"سكوتر","example":"Everyone had to leave a scooter outside and turn off their phones.","number":72,"id":"a2:072","level":"A2","lessonId":"a2-set-03"},{"term":"success","meaning":"نجاح","example":"Their success earned them a small prize: a beautiful notebook.","number":73,"id":"a2:073","level":"A2","lessonId":"a2-set-03"},{"term":"turn off","meaning":"يطفئ","example":"Everyone had to leave a scooter outside and turn off their phones.","number":74,"id":"a2:074","level":"A2","lessonId":"a2-set-03"},{"term":"wooden","meaning":"خشبي","example":"On a wooden desk lay a newspaper.","number":75,"id":"a2:075","level":"A2","lessonId":"a2-set-03"}],"story":{"title":"The Library of Clues","paragraphs":["At midday, the library opened a special indoor treasure hunt. Everyone had to leave a scooter outside and turn off their phones. On a wooden desk lay a newspaper, a magazine, and an article about a famous writer. The first note said, 'Look for the oldest bookcase.'","Nora and Sami started reading. A geography map was hidden behind a bookshelf. Above it, someone had used a blackboard to write a question about history. Sami remembered the correct answer from his diary. Nora made a mark beside the answer with a rubber stamp.","The next clue led them to a bookshop display with a comic about writing and a missing final page. 'We can get back to the library and finish this ourselves,' Nora said. She found a sheet of paper inside the bookcase. It was full of news about a young author who had helped build the town.","They copied the final note and gave it to the librarian. Their success earned them a small prize: a beautiful notebook. 'The real treasure,' said the librarian, 'is learning to ask good questions.'"],"questions":["Where was the first note placed?","What knowledge helped Sami solve a clue?","Why was teamwork useful in the hunt?","What was the librarian’s real message?"]}},{"id":"a2-set-04","title":"The New School Club","subtitle":"A2 reading adventure 04","level":"A2","set":4,"emoji":"🌱","color":"#37BE9C","words":[{"term":"class","meaning":"حصة دراسية","example":"Every pupil in the class could join.","number":76,"id":"a2:076","level":"A2","lessonId":"a2-set-04"},{"term":"classroom","meaning":"فصل دراسي","example":"She hurried indoors and reached the classroom in the middle of a quiz.","number":77,"id":"a2:077","level":"A2","lessonId":"a2-set-04"},{"term":"pupil","meaning":"تلميذ","example":"Every pupil in the class could join.","number":78,"id":"a2:078","level":"A2","lessonId":"a2-set-04"},{"term":"schoolchild","meaning":"تلميذ مدرسة","example":"The club was successful because every schoolchild helped.","number":79,"id":"a2:079","level":"A2","lessonId":"a2-set-04"},{"term":"headteacher","meaning":"مدير المدرسة","example":"The headteacher smiled.","number":80,"id":"a2:080","level":"A2","lessonId":"a2-set-04"},{"term":"textbook","meaning":"كتاب مدرسي","example":"Not just study a textbook.","number":81,"id":"a2:081","level":"A2","lessonId":"a2-set-04"},{"term":"instructions","meaning":"تعليمات","example":"The teacher gave her the instructions and a review sheet.","number":82,"id":"a2:082","level":"A2","lessonId":"a2-set-04"},{"term":"quiz","meaning":"اختبار قصير","example":"She hurried indoors and reached the classroom in the middle of a quiz.","number":83,"id":"a2:083","level":"A2","lessonId":"a2-set-04"},{"term":"review","meaning":"مراجعة","example":"The teacher gave her the instructions and a review sheet.","number":84,"id":"a2:084","level":"A2","lessonId":"a2-set-04"},{"term":"spelling","meaning":"تهجئة","example":"You must know the spelling of these words.","number":85,"id":"a2:085","level":"A2","lessonId":"a2-set-04"},{"term":"study","meaning":"يدرس","example":"Not just study a textbook.","number":86,"id":"a2:086","level":"A2","lessonId":"a2-set-04"},{"term":"studies","meaning":"دراسات","example":"'You must know the spelling of these words,' he said, 'but you also need to explain your ideas.' Maya found a mistake in her studies: she had left two words out of a sentence.","number":87,"id":"a2:087","level":"A2","lessonId":"a2-set-04"},{"term":"diploma","meaning":"شهادة دبلوم","example":"She checked her diploma project","number":88,"id":"a2:088","level":"A2","lessonId":"a2-set-04"},{"term":"beginner","meaning":"مبتدئ","example":"From a beginner to an advanced learner.","number":89,"id":"a2:089","level":"A2","lessonId":"a2-set-04"},{"term":"advanced","meaning":"متقدم","example":"From a beginner to an advanced learner.","number":90,"id":"a2:090","level":"A2","lessonId":"a2-set-04"},{"term":"term","meaning":"فصل دراسي","example":"The headteacher announced a new school club at the start of the term.","number":91,"id":"a2:091","level":"A2","lessonId":"a2-set-04"},{"term":"teach","meaning":"يدرس","example":"The club would teach children how to solve real problems.","number":92,"id":"a2:092","level":"A2","lessonId":"a2-set-04"},{"term":"get off","meaning":"ينزل من وسيلة نقل","example":"On the first day, Maya had to get off the bus early because it rained.","number":93,"id":"a2:093","level":"A2","lessonId":"a2-set-04"},{"term":"indoors","meaning":"داخل المبنى","example":"She hurried indoors and reached the classroom in the middle of a quiz.","number":94,"id":"a2:094","level":"A2","lessonId":"a2-set-04"},{"term":"middle","meaning":"وسط","example":"She hurried indoors and reached the classroom in the middle of a quiz.","number":95,"id":"a2:095","level":"A2","lessonId":"a2-set-04"},{"term":"out of","meaning":"خارج من","example":"She had left two words out of a sentence.","number":96,"id":"a2:096","level":"A2","lessonId":"a2-set-04"},{"term":"see","meaning":"يرى","example":"He asked Maya to see whether the class could work out the final puzzle together.","number":97,"id":"a2:097","level":"A2","lessonId":"a2-set-04"},{"term":"successful","meaning":"ناجح","example":"The club was successful because every schoolchild helped.","number":98,"id":"a2:098","level":"A2","lessonId":"a2-set-04"},{"term":"turn on","meaning":"يشغل","example":"Please turn on the projector,' the teacher said.","number":99,"id":"a2:099","level":"A2","lessonId":"a2-set-04"},{"term":"work out","meaning":"يتمرن","example":"He asked Maya to see whether the class could work out the final puzzle together.","number":100,"id":"a2:100","level":"A2","lessonId":"a2-set-04"}],"story":{"title":"The New School Club","paragraphs":["The headteacher announced a new school club at the start of the term. Every pupil in the class could join, from a beginner to an advanced learner. The club would teach children how to solve real problems, not just study a textbook.","On the first day, Maya had to get off the bus early because it rained. She hurried indoors and reached the classroom in the middle of a quiz. The teacher gave her the instructions and a review sheet. 'You must know the spelling of these words,' he said, 'but you also need to explain your ideas.'","Maya found a mistake in her studies: she had left two words out of a sentence. She checked her diploma project from last year, used it as a model, and wrote a better answer. 'Please turn on the projector,' the teacher said. He asked Maya to see whether the class could work out the final puzzle together.","They did. The club was successful because every schoolchild helped. The headteacher smiled. 'A clever group is not a group where nobody makes mistakes. It is one where everybody learns from them.'"],"questions":["Who could join the club?","What mistake had Maya made?","Why was the club successful?","How was this club different from ordinary lessons?"]}},{"id":"a2-set-05","title":"The Science Fair Surprise","subtitle":"A2 reading adventure 05","level":"A2","set":5,"emoji":"🌱","color":"#37BE9C","words":[{"term":"biology","meaning":"علم الأحياء","example":"Next, a teacher showed an example from biology and another from physics.","number":101,"id":"a2:101","level":"A2","lessonId":"a2-set-05"},{"term":"chemistry","meaning":"كيمياء","example":"A chemistry student showed us the equipment for a safe experiment.","number":102,"id":"a2:102","level":"A2","lessonId":"a2-set-05"},{"term":"physics","meaning":"فيزياء","example":"Next, a teacher showed an example from biology and another from physics.","number":103,"id":"a2:103","level":"A2","lessonId":"a2-set-05"},{"term":"scientist","meaning":"عالم","example":"A scientist welcomed us to an outdoor tent.","number":104,"id":"a2:104","level":"A2","lessonId":"a2-set-05"},{"term":"invent","meaning":"يخترع","example":"'You can invent something useful if you first understand the problem.' In the first room, we saw a dinosaur model and a display about why some animals are extinct.","number":105,"id":"a2:105","level":"A2","lessonId":"a2-set-05"},{"term":"invention","meaning":"اختراع","example":"She used the experiment to explain how an invention begins with a simple idea.","number":106,"id":"a2:106","level":"A2","lessonId":"a2-set-05"},{"term":"dinosaur","meaning":"ديناصور","example":"We saw a dinosaur model and a display about why some animals are extinct.","number":107,"id":"a2:107","level":"A2","lessonId":"a2-set-05"},{"term":"extinct","meaning":"منقرض","example":"We saw a dinosaur model and a display about why some animals are extinct.","number":108,"id":"a2:108","level":"A2","lessonId":"a2-set-05"},{"term":"equipment","meaning":"معدات","example":"A chemistry student showed us the equipment for a safe experiment.","number":109,"id":"a2:109","level":"A2","lessonId":"a2-set-05"},{"term":"fact","meaning":"حقيقة","example":"Today you will discover a surprising fact,' she said.","number":110,"id":"a2:110","level":"A2","lessonId":"a2-set-05"},{"term":"explain","meaning":"يشرح","example":"She used the experiment to explain how an invention begins with a simple idea.","number":111,"id":"a2:111","level":"A2","lessonId":"a2-set-05"},{"term":"example","meaning":"مثال","example":"Next, a teacher showed an example from biology and another from physics.","number":112,"id":"a2:112","level":"A2","lessonId":"a2-set-05"},{"term":"model","meaning":"نموذج","example":"We saw a dinosaur model and a display","number":113,"id":"a2:113","level":"A2","lessonId":"a2-set-05"},{"term":"design","meaning":"تصميم","example":"Even a small design can be important,' the scientist told us.","number":114,"id":"a2:114","level":"A2","lessonId":"a2-set-05"},{"term":"know","meaning":"يعرف","example":"Can you remember what you know from your course?' she asked.","number":115,"id":"a2:115","level":"A2","lessonId":"a2-set-05"},{"term":"remember","meaning":"يتذكر","example":"Can you remember what you know from your course?' she asked.","number":116,"id":"a2:116","level":"A2","lessonId":"a2-set-05"},{"term":"course","meaning":"دورة دراسية","example":"Can you remember what you know from your course?' she asked.","number":117,"id":"a2:117","level":"A2","lessonId":"a2-set-05"},{"term":"get on","meaning":"يصعد إلى وسيلة نقل","example":"So we had to get on a bus.","number":118,"id":"a2:118","level":"A2","lessonId":"a2-set-05"},{"term":"ingredient","meaning":"مكون","example":"The main ingredient was coloured water, not a dangerous chemical.","number":119,"id":"a2:119","level":"A2","lessonId":"a2-set-05"},{"term":"mile","meaning":"ميل","example":"Our school held a science fair a mile from town.","number":120,"id":"a2:120","level":"A2","lessonId":"a2-set-05"},{"term":"outdoor","meaning":"خارجي","example":"A scientist welcomed us to an outdoor tent.","number":121,"id":"a2:121","level":"A2","lessonId":"a2-set-05"},{"term":"seem","meaning":"يبدو","example":"It did not seem to work the first time.","number":122,"id":"a2:122","level":"A2","lessonId":"a2-set-05"},{"term":"such","meaning":"مثل هذا","example":"He felt such worry that he nearly gave up.","number":123,"id":"a2:123","level":"A2","lessonId":"a2-set-05"},{"term":"twice","meaning":"مرتين","example":"Then we tested it twice, changed one part, and tried again.","number":124,"id":"a2:124","level":"A2","lessonId":"a2-set-05"},{"term":"worry","meaning":"يقلق","example":"He felt such worry that he nearly gave up.","number":125,"id":"a2:125","level":"A2","lessonId":"a2-set-05"}],"story":{"title":"The Science Fair Surprise","paragraphs":["Our school held a science fair a mile from town, so we had to get on a bus. A scientist welcomed us to an outdoor tent. 'Today you will discover a surprising fact,' she said. 'You can invent something useful if you first understand the problem.'","In the first room, we saw a dinosaur model and a display about why some animals are extinct. In another room, a chemistry student showed us the equipment for a safe experiment. The main ingredient was coloured water, not a dangerous chemical. She used the experiment to explain how an invention begins with a simple idea.","Next, a teacher showed an example from biology and another from physics. 'Can you remember what you know from your course?' she asked. My friend Adam designed a machine to move seeds. It did not seem to work the first time. He felt such worry that he nearly gave up.","Then we tested it twice, changed one part, and tried again. The machine worked! 'Even a small design can be important,' the scientist told us. I learned that an experiment is not a failure when it teaches us something new."],"questions":["Why did the class travel by bus?","What safe ingredient did the chemistry student use?","What changed Adam’s result?","What lesson did the narrator learn about experiments?"]}},{"id":"a2-set-06","title":"The Costume Mix-Up","subtitle":"A2 reading adventure 06","level":"A2","set":6,"emoji":"🌱","color":"#37BE9C","words":[{"term":"costume","meaning":"زي تنكري","example":"Her costume included a bright blouse, a long jumper, and purple tights.","number":126,"id":"a2:126","level":"A2","lessonId":"a2-set-06"},{"term":"clothes","meaning":"ملابس","example":"These clothes are not mine!' she cried.","number":127,"id":"a2:127","level":"A2","lessonId":"a2-set-06"},{"term":"glasses","meaning":"نظارة","example":"She wanted to wear sunglasses as well, but her friend Max said, 'You cannot see the stage clearly in those!' In her bag, Zoe found a glove, a silver chain, a small ring, and a pair of glasses.","number":128,"id":"a2:128","level":"A2","lessonId":"a2-set-06"},{"term":"glove","meaning":"قفاز","example":"She wanted to wear sunglasses as well, but her friend Max said, 'You cannot see the stage clearly in those!' In her bag, Zoe found a glove, a silver chain, a small ring, and a pair of glasses.","number":129,"id":"a2:129","level":"A2","lessonId":"a2-set-06"},{"term":"handbag","meaning":"حقيبة يد","example":"Someone had put a handbag and a hoodie in the wrong box.","number":130,"id":"a2:130","level":"A2","lessonId":"a2-set-06"},{"term":"hoodie","meaning":"سترة بغطاء رأس","example":"Someone had put a handbag and a hoodie in the wrong box.","number":131,"id":"a2:131","level":"A2","lessonId":"a2-set-06"},{"term":"jumper","meaning":"كنزة","example":"Her costume included a bright blouse, a long jumper, and purple tights.","number":132,"id":"a2:132","level":"A2","lessonId":"a2-set-06"},{"term":"blouse","meaning":"بلوزة","example":"Her costume included a bright blouse, a long jumper, and purple tights.","number":133,"id":"a2:133","level":"A2","lessonId":"a2-set-06"},{"term":"sunglasses","meaning":"نظارة شمسية","example":"She wanted to wear sunglasses as well.","number":134,"id":"a2:134","level":"A2","lessonId":"a2-set-06"},{"term":"tights","meaning":"جوارب طويلة","example":"Her costume included a bright blouse, a long jumper, and purple tights.","number":135,"id":"a2:135","level":"A2","lessonId":"a2-set-06"},{"term":"wear","meaning":"يرتدي","example":"She wanted to wear sunglasses as well.","number":136,"id":"a2:136","level":"A2","lessonId":"a2-set-06"},{"term":"put on","meaning":"يرتدي","example":"So she asked him to put on the correct jacket.","number":137,"id":"a2:137","level":"A2","lessonId":"a2-set-06"},{"term":"get dressed","meaning":"يرتدي ملابسه","example":"Zoe had to get dressed for the","number":138,"id":"a2:138","level":"A2","lessonId":"a2-set-06"},{"term":"bag","meaning":"حقيبة","example":"You cannot see the stage clearly in those!' In her bag.","number":139,"id":"a2:139","level":"A2","lessonId":"a2-set-06"},{"term":"chain","meaning":"سلسلة","example":"She wanted to wear sunglasses as well, but her friend Max said, 'You cannot see the stage clearly in those!' In her bag, Zoe found a glove, a silver chain, a small ring, and a pair of glasses.","number":140,"id":"a2:140","level":"A2","lessonId":"a2-set-06"},{"term":"dressed","meaning":"مرتد ملابسه","example":"Zoe had to get dressed for the school fashion show.","number":141,"id":"a2:141","level":"A2","lessonId":"a2-set-06"},{"term":"fashion","meaning":"موضة","example":"Zoe had to get dressed for the school fashion show.","number":142,"id":"a2:142","level":"A2","lessonId":"a2-set-06"},{"term":"get","meaning":"يحصل على","example":"Zoe had to get dressed for the school fashion show.","number":143,"id":"a2:143","level":"A2","lessonId":"a2-set-06"},{"term":"ring","meaning":"خاتم أو يرن","example":"She wanted to wear sunglasses as well, but her friend Max said, 'You cannot see the stage clearly in those!' In her bag, Zoe found a glove, a silver chain, a small ring, and a pair of glasses.","number":144,"id":"a2:144","level":"A2","lessonId":"a2-set-06"},{"term":"million","meaning":"مليون","example":"'That was a million times funnier than our rehearsals!' Zoe helped Max get up.","number":145,"id":"a2:145","level":"A2","lessonId":"a2-set-06"},{"term":"outdoors","meaning":"في الهواء الطلق","example":"Get ready!' Suddenly a child ran outdoors to take a selfie.","number":146,"id":"a2:146","level":"A2","lessonId":"a2-set-06"},{"term":"selfie","meaning":"صورة ذاتية","example":"Get ready!' Suddenly a child ran outdoors to take a selfie.","number":147,"id":"a2:147","level":"A2","lessonId":"a2-set-06"},{"term":"suddenly","meaning":"فجأة","example":"Get ready!' Suddenly a child ran outdoors to take a selfie.","number":148,"id":"a2:148","level":"A2","lessonId":"a2-set-06"},{"term":"try","meaning":"يحاول","example":"The show was about to begin, so Zoe decided to try the clothes on anyway.","number":149,"id":"a2:149","level":"A2","lessonId":"a2-set-06"},{"term":"wow","meaning":"واو","example":"Wow!' laughed the audience.","number":150,"id":"a2:150","level":"A2","lessonId":"a2-set-06"}],"story":{"title":"The Costume Mix-Up","paragraphs":["Zoe had to get dressed for the school fashion show. Her costume included a bright blouse, a long jumper, and purple tights. She wanted to wear sunglasses as well, but her friend Max said, 'You cannot see the stage clearly in those!'","In her bag, Zoe found a glove, a silver chain, a small ring, and a pair of glasses. Someone had put a handbag and a hoodie in the wrong box. 'These clothes are not mine!' she cried. The show was about to begin, so Zoe decided to try the clothes on anyway. She was dressed like a detective instead of a princess.","The fashion teacher shouted, 'Get ready!' Suddenly a child ran outdoors to take a selfie, and a strong wind blew the costume sign away. Max chased it, slipped, and landed inside a pile of clothes. 'Wow!' laughed the audience. 'That was a million times funnier than our rehearsals!'","Zoe helped Max get up. She did not want to miss the show, so she asked him to put on the correct jacket. They laughed about the missing accessories and finished together. The teacher said their happy mistake had made the performance unforgettable."],"questions":["Why was Zoe dressed like a detective?","What caused the sign to blow away?","Why did the audience laugh?","What does the story teach about small mistakes?"]}},{"id":"a2-set-07","title":"The Market Challenge","subtitle":"A2 reading adventure 07","level":"A2","set":7,"emoji":"🌱","color":"#37BE9C","words":[{"term":"shopper","meaning":"متسوق","example":"The first shopper they met showed them beautiful jewellery.","number":151,"id":"a2:151","level":"A2","lessonId":"a2-set-07"},{"term":"shopping","meaning":"تسوق","example":"Their shopping trip taught them that a thoughtful gift can serve a family better than an expensive one.","number":152,"id":"a2:152","level":"A2","lessonId":"a2-set-07"},{"term":"sale","meaning":"تخفيضات","example":"But not everything was for sale at a fair price.","number":153,"id":"a2:153","level":"A2","lessonId":"a2-set-07"},{"term":"for sale","meaning":"للبيع","example":"But not everything was for sale at a fair price.","number":154,"id":"a2:154","level":"A2","lessonId":"a2-set-07"},{"term":"bracelet","meaning":"سوار","example":"Their challenge was to buy a bracelet for Grandma.","number":155,"id":"a2:155","level":"A2","lessonId":"a2-set-07"},{"term":"jewellery","meaning":"مجوهرات","example":"The first shopper they met showed them beautiful jewellery.","number":156,"id":"a2:156","level":"A2","lessonId":"a2-set-07"},{"term":"necklace","meaning":"قلادة","example":"You can try on the necklace,' she said.","number":157,"id":"a2:157","level":"A2","lessonId":"a2-set-07"},{"term":"earring","meaning":"قرط","example":"The owner offered an earring, a ring, and a bottle of perfume.","number":158,"id":"a2:158","level":"A2","lessonId":"a2-set-07"},{"term":"perfume","meaning":"عطر","example":"The owner offered an earring, a ring, and a bottle of perfume.","number":159,"id":"a2:159","level":"A2","lessonId":"a2-set-07"},{"term":"purse","meaning":"محفظة صغيرة","example":"Lara opened her purse and checked the money.","number":160,"id":"a2:160","level":"A2","lessonId":"a2-set-07"},{"term":"cheque","meaning":"شيك","example":"They asked whether the shop would accept a cheque or a euro.","number":161,"id":"a2:161","level":"A2","lessonId":"a2-set-07"},{"term":"cent","meaning":"سنت","example":"Lara and Ben entered the town market with only one ten-dollar note and a few cent coins.","number":162,"id":"a2:162","level":"A2","lessonId":"a2-set-07"},{"term":"dollar","meaning":"دولار","example":"Lara and Ben entered the town market with only one ten-dollar note and a few cent coins.","number":163,"id":"a2:163","level":"A2","lessonId":"a2-set-07"},{"term":"euro","meaning":"يورو","example":"They asked whether the shop would accept a cheque or a euro.","number":164,"id":"a2:164","level":"A2","lessonId":"a2-set-07"},{"term":"rent","meaning":"يستأجر","example":"The shop sold its own handmade gifts and did not have to rent an expensive counter.","number":165,"id":"a2:165","level":"A2","lessonId":"a2-set-07"},{"term":"close","meaning":"يغلق","example":"The next store was about to close.","number":166,"id":"a2:166","level":"A2","lessonId":"a2-set-07"},{"term":"closed","meaning":"مغلق","example":"Its doors were almost closed.","number":167,"id":"a2:167","level":"A2","lessonId":"a2-set-07"},{"term":"open","meaning":"يفتح","example":"But a friendly assistant said it was still open.","number":168,"id":"a2:168","level":"A2","lessonId":"a2-set-07"},{"term":"tie","meaning":"ربطة عنق","example":"Their challenge was to buy a bracelet for Grandma, a necklace for Mum, and a tie for Dad.","number":169,"id":"a2:169","level":"A2","lessonId":"a2-set-07"},{"term":"mind","meaning":"عقل","example":"My mind tells me we cannot afford all this,' she whispered.","number":170,"id":"a2:170","level":"A2","lessonId":"a2-set-07"},{"term":"own","meaning":"يملك أو خاص","example":"The shop sold its own handmade gifts and did not have to rent an expensive counter.","number":171,"id":"a2:171","level":"A2","lessonId":"a2-set-07"},{"term":"serve","meaning":"يقدم الطعام","example":"Their shopping trip taught them that a thoughtful gift can serve a family better than an expensive one.","number":172,"id":"a2:172","level":"A2","lessonId":"a2-set-07"},{"term":"suggest","meaning":"يقترح","example":"I suggest we choose one present instead of three,' he said.","number":173,"id":"a2:173","level":"A2","lessonId":"a2-set-07"},{"term":"try on","meaning":"يجرب الملابس","example":"You can try on the necklace,' she said.","number":174,"id":"a2:174","level":"A2","lessonId":"a2-set-07"},{"term":"write down","meaning":"يدون","example":"They bought a lovely bracelet and decided to write down a kind message for everyone else.","number":175,"id":"a2:175","level":"A2","lessonId":"a2-set-07"}],"story":{"title":"The Market Challenge","paragraphs":["Lara and Ben entered the town market with only one ten-dollar note and a few cent coins. Their challenge was to buy a bracelet for Grandma, a necklace for Mum, and a tie for Dad. A large sign said 'SALE', but not everything was for sale at a fair price.","The first shopper they met showed them beautiful jewellery. The owner offered an earring, a ring, and a bottle of perfume. 'You can try on the necklace,' she said. Lara opened her purse and checked the money. 'My mind tells me we cannot afford all this,' she whispered. They asked whether the shop would accept a cheque or a euro, but the owner said no.","The next store was about to close. Its doors were almost closed, but a friendly assistant said it was still open. The shop sold its own handmade gifts and did not have to rent an expensive counter. Ben paused to think. 'I suggest we choose one present instead of three,' he said.","They bought a lovely bracelet and decided to write down a kind message for everyone else. Their shopping trip taught them that a thoughtful gift can serve a family better than an expensive one."],"questions":["How much money did the children start with?","Why could they not buy everything?","Why might the second shop have lower prices?","What choice showed the children were thoughtful?"]}},{"id":"a2-set-08","title":"The Chef Who Lost a Recipe","subtitle":"A2 reading adventure 08","level":"A2","set":8,"emoji":"🌱","color":"#37BE9C","words":[{"term":"chef","meaning":"طاه","example":"At last the chef found the missing page inside a cookbook.","number":176,"id":"a2:176","level":"A2","lessonId":"a2-set-08"},{"term":"boiled","meaning":"مسلوق","example":"They had boiled pasta, fried chips, grilled sausage, and baked pizza ready for the guests.","number":177,"id":"a2:177","level":"A2","lessonId":"a2-set-08"},{"term":"grilled","meaning":"مشوي","example":"They had boiled pasta, fried chips, grilled sausage, and baked pizza ready for the guests.","number":178,"id":"a2:178","level":"A2","lessonId":"a2-set-08"},{"term":"fried","meaning":"مقلي","example":"They had boiled pasta, fried chips, grilled sausage, and baked pizza ready for the guests.","number":179,"id":"a2:179","level":"A2","lessonId":"a2-set-08"},{"term":"cooking","meaning":"طبخ","example":"Chef Oliver was preparing supper for a cooking contest when his recipe disappeared.","number":180,"id":"a2:180","level":"A2","lessonId":"a2-set-08"},{"term":"cooker","meaning":"موقد","example":"After that, he carefully put the steak on the cooker.","number":181,"id":"a2:181","level":"A2","lessonId":"a2-set-08"},{"term":"garlic","meaning":"ثوم","example":"Oliver chopped the garlic while his assistant prepared the sauce.","number":182,"id":"a2:182","level":"A2","lessonId":"a2-set-08"},{"term":"chilli","meaning":"فلفل حار","example":"He had a cooker, fresh garlic, red chilli, and a big piece of steak, but no instructions.","number":183,"id":"a2:183","level":"A2","lessonId":"a2-set-08"},{"term":"curry","meaning":"طبق كاري","example":"They decided to cook a curry with vegetables and make a simple salad.","number":184,"id":"a2:184","level":"A2","lessonId":"a2-set-08"},{"term":"pizza","meaning":"بيتزا","example":"And baked pizza ready for the guests.","number":185,"id":"a2:185","level":"A2","lessonId":"a2-set-08"},{"term":"food","meaning":"طعام","example":"If we use too much salt, the food will not be tasty,' she warned.","number":186,"id":"a2:186","level":"A2","lessonId":"a2-set-08"},{"term":"pasta","meaning":"معكرونة","example":"They had boiled pasta, fried chips, grilled sausage, and baked pizza ready for the guests.","number":187,"id":"a2:187","level":"A2","lessonId":"a2-set-08"},{"term":"salad","meaning":"سلطة","example":"They decided to cook a curry with vegetables and make a simple salad.","number":188,"id":"a2:188","level":"A2","lessonId":"a2-set-08"},{"term":"sauce","meaning":"صلصة","example":"Oliver chopped the garlic while his assistant prepared the sauce.","number":189,"id":"a2:189","level":"A2","lessonId":"a2-set-08"},{"term":"sausage","meaning":"نقانق","example":"They had boiled pasta, fried chips, grilled sausage, and baked pizza ready for the guests.","number":190,"id":"a2:190","level":"A2","lessonId":"a2-set-08"},{"term":"steak","meaning":"شريحة لحم","example":"After that, he carefully put the steak on the cooker.","number":191,"id":"a2:191","level":"A2","lessonId":"a2-set-08"},{"term":"tasty","meaning":"لذيذ","example":"If we use too much salt, the food will not be tasty,' she warned.","number":192,"id":"a2:192","level":"A2","lessonId":"a2-set-08"},{"term":"piece","meaning":"قطعة","example":"He had a cooker, fresh garlic, red chilli, and a big piece of steak, but no instructions.","number":193,"id":"a2:193","level":"A2","lessonId":"a2-set-08"},{"term":"wash up","meaning":"يغسل الصحون","example":"Please wash up the pans before the judges arrive,' he said.","number":194,"id":"a2:194","level":"A2","lessonId":"a2-set-08"},{"term":"minus","meaning":"ناقص","example":"Two cups of cream minus one cup would leave just enough for the soup.","number":195,"id":"a2:195","level":"A2","lessonId":"a2-set-08"},{"term":"pair","meaning":"زوج من الأشياء","example":"His assistant brought a pair of bowls and a set of knives.","number":196,"id":"a2:196","level":"A2","lessonId":"a2-set-08"},{"term":"set","meaning":"مجموعة","example":"His assistant brought a pair of bowls and a set of knives.","number":197,"id":"a2:197","level":"A2","lessonId":"a2-set-08"},{"term":"supper","meaning":"وجبة عشاء خفيفة","example":"Chef Oliver was preparing supper for a cooking contest when his recipe disappeared.","number":198,"id":"a2:198","level":"A2","lessonId":"a2-set-08"},{"term":"type","meaning":"نوع أو يكتب","example":"This is the wrong type of dish!' he cried when he tasted his first sauce.","number":199,"id":"a2:199","level":"A2","lessonId":"a2-set-08"},{"term":"wrong","meaning":"خاطئ","example":"This is the wrong type of dish!' he cried when he tasted his first sauce.","number":200,"id":"a2:200","level":"A2","lessonId":"a2-set-08"}],"story":{"title":"The Chef Who Lost a Recipe","paragraphs":["Chef Oliver was preparing supper for a cooking contest when his recipe disappeared. He had a cooker, fresh garlic, red chilli, and a big piece of steak, but no instructions. 'This is the wrong type of dish!' he cried when he tasted his first sauce.","His assistant brought a pair of bowls and a set of knives. They had boiled pasta, fried chips, grilled sausage, and baked pizza ready for the guests. 'If we use too much salt, the food will not be tasty,' she warned. Oliver was trying to calculate the ingredients: two cups of cream minus one cup would leave just enough for the soup.","They decided to cook a curry with vegetables and make a simple salad. Oliver chopped the garlic while his assistant prepared the sauce. After that, he carefully put the steak on the cooker. The smell made everyone hungry.","'Please wash up the pans before the judges arrive,' he said. At last the chef found the missing page inside a cookbook. He laughed. The recipe was for exactly the meal they had just invented! Their tasty experiment won the contest because it was both delicious and creative."],"questions":["What problem did Chef Oliver have?","Why did his assistant warn him about salt?","How did they manage without the recipe?","What probably helped them win the contest?"]}},{"id":"a2-set-09","title":"The Picnic Puzzle","subtitle":"A2 reading adventure 09","level":"A2","set":9,"emoji":"🌱","color":"#37BE9C","words":[{"term":"picnic","meaning":"نزهة","example":"Our class planned a picnic instead of eating fast food in the school cafeteria.","number":201,"id":"a2:201","level":"A2","lessonId":"a2-set-09"},{"term":"burger","meaning":"شطيرة برغر","example":"Adam brought a burger and some chips.","number":202,"id":"a2:202","level":"A2","lessonId":"a2-set-09"},{"term":"cream","meaning":"قشدة","example":"I packed fruit, toast, an omelette, and a cup of sweet cream for dessert.","number":203,"id":"a2:203","level":"A2","lessonId":"a2-set-09"},{"term":"meal","meaning":"وجبة","example":"At noon, our teacher said one meal was missing.","number":204,"id":"a2:204","level":"A2","lessonId":"a2-set-09"},{"term":"snack","meaning":"وجبة خفيفة","example":"If you want the most delicious snack.","number":205,"id":"a2:205","level":"A2","lessonId":"a2-set-09"},{"term":"toast","meaning":"خبز محمص","example":"I packed fruit, toast, an omelette, and a cup of sweet cream for dessert.","number":206,"id":"a2:206","level":"A2","lessonId":"a2-set-09"},{"term":"omelette","meaning":"عجة بيض","example":"I packed fruit, toast, an omelette, and a cup of sweet cream for dessert.","number":207,"id":"a2:207","level":"A2","lessonId":"a2-set-09"},{"term":"fruit","meaning":"فاكهة","example":"I packed fruit, toast, an omelette, and a cup of sweet cream for dessert.","number":208,"id":"a2:208","level":"A2","lessonId":"a2-set-09"},{"term":"vegetable","meaning":"خضار","example":"Sara made a fresh vegetable salad with a little salt.","number":209,"id":"a2:209","level":"A2","lessonId":"a2-set-09"},{"term":"fresh","meaning":"طازج","example":"Sara made a fresh vegetable salad with a little salt.","number":210,"id":"a2:210","level":"A2","lessonId":"a2-set-09"},{"term":"sweet","meaning":"حلو المذاق","example":"I packed fruit, toast, an omelette, and a cup of sweet cream for dessert.","number":211,"id":"a2:211","level":"A2","lessonId":"a2-set-09"},{"term":"delicious","meaning":"لذيذ","example":"If you want the most delicious snack.","number":212,"id":"a2:212","level":"A2","lessonId":"a2-set-09"},{"term":"fast food","meaning":"وجبات سريعة","example":"Our class planned a picnic instead of eating fast food in the school cafeteria.","number":213,"id":"a2:213","level":"A2","lessonId":"a2-set-09"},{"term":"chips","meaning":"بطاطس مقلية","example":"Adam brought a burger and some chips.","number":214,"id":"a2:214","level":"A2","lessonId":"a2-set-09"},{"term":"cup","meaning":"كوب","example":"I packed fruit, toast, an omelette, and a cup of sweet cream for dessert.","number":215,"id":"a2:215","level":"A2","lessonId":"a2-set-09"},{"term":"dish","meaning":"طبق","example":"Everyone had to bring a dish.","number":216,"id":"a2:216","level":"A2","lessonId":"a2-set-09"},{"term":"main course","meaning":"الطبق الرئيسي","example":"Where is the main course?' she asked.","number":217,"id":"a2:217","level":"A2","lessonId":"a2-set-09"},{"term":"salt","meaning":"ملح","example":"Sara made a fresh vegetable salad with a little salt.","number":218,"id":"a2:218","level":"A2","lessonId":"a2-set-09"},{"term":"instead of","meaning":"بدلا من","example":"Our class planned a picnic instead of eating fast food in the school cafeteria.","number":219,"id":"a2:219","level":"A2","lessonId":"a2-set-09"},{"term":"missing","meaning":"مفقود","example":"At noon, our teacher said one meal was missing.","number":220,"id":"a2:220","level":"A2","lessonId":"a2-set-09"},{"term":"pale","meaning":"شاحب","example":"We found a pale note under the picnic basket.","number":221,"id":"a2:221","level":"A2","lessonId":"a2-set-09"},{"term":"shame","meaning":"خجل","example":"Solve my puzzle first.' What a shame that lunch was delayed.","number":222,"id":"a2:222","level":"A2","lessonId":"a2-set-09"},{"term":"suppose","meaning":"يفترض","example":"The second asked us to suppose that two friends shared one big meal.","number":223,"id":"a2:223","level":"A2","lessonId":"a2-set-09"},{"term":"understand","meaning":"يفهم","example":"We did not understand at first.","number":224,"id":"a2:224","level":"A2","lessonId":"a2-set-09"},{"term":"yes","meaning":"نعم","example":"Then Sara said, 'Perhaps the answer is in the recipe book.' Yes!","number":225,"id":"a2:225","level":"A2","lessonId":"a2-set-09"}],"story":{"title":"The Picnic Puzzle","paragraphs":["Our class planned a picnic instead of eating fast food in the school cafeteria. Everyone had to bring a dish. Sara made a fresh vegetable salad with a little salt. Adam brought a burger and some chips. I packed fruit, toast, an omelette, and a cup of sweet cream for dessert.","At noon, our teacher said one meal was missing. 'Where is the main course?' she asked. We found a pale note under the picnic basket: 'If you want the most delicious snack, solve my puzzle first.' What a shame that lunch was delayed! We had forgotten to check the basket.","The first clue showed a picture of pizza. The second asked us to suppose that two friends shared one big meal. We did not understand at first. Then Sara said, 'Perhaps the answer is in the recipe book.' Yes! On page twelve was a picture of a tasty pasta dish.","Behind the book we found the missing food and a tiny prize. The teacher laughed. 'The surprise was not the food,' she said. 'It was learning to work together.'"],"questions":["What did the pupils plan instead of fast food?","What was missing from the basket?","What helped them solve the puzzle?","What was the teacher trying to teach?"]}},{"id":"a2-set-10","title":"The New Neighbour","subtitle":"A2 reading adventure 10","level":"A2","set":10,"emoji":"🌱","color":"#37BE9C","words":[{"term":"daughter","meaning":"ابنة","example":"Who was unpacking boxes with their young son and daughter.","number":226,"id":"a2:226","level":"A2","lessonId":"a2-set-10"},{"term":"son","meaning":"ابن","example":"Who was unpacking boxes with their young son and daughter.","number":227,"id":"a2:227","level":"A2","lessonId":"a2-set-10"},{"term":"husband","meaning":"زوج","example":"Her husband was still outside with the furniture.","number":228,"id":"a2:228","level":"A2","lessonId":"a2-set-10"},{"term":"wife","meaning":"زوجة","example":"Mr Green called his wife, who was unpacking boxes with their young son and daughter.","number":229,"id":"a2:229","level":"A2","lessonId":"a2-set-10"},{"term":"parent","meaning":"أحد الوالدين","example":"And a parent from each side often visited.","number":230,"id":"a2:230","level":"A2","lessonId":"a2-set-10"},{"term":"grandchild","meaning":"حفيد","example":"Their family was large: one grandparent, a grandchild, and a parent from each side often visited.","number":231,"id":"a2:231","level":"A2","lessonId":"a2-set-10"},{"term":"grandparent","meaning":"جد أو جدة","example":"Their family was large: one grandparent, a grandchild, and a parent from each side often visited.","number":232,"id":"a2:232","level":"A2","lessonId":"a2-set-10"},{"term":"neighbour","meaning":"جار","example":"A new neighbour moved into the bright yellow house.","number":233,"id":"a2:233","level":"A2","lessonId":"a2-set-10"},{"term":"boyfriend","meaning":"صديق مقرب","example":"His sister's boyfriend had brought a cake.","number":234,"id":"a2:234","level":"A2","lessonId":"a2-set-10"},{"term":"girlfriend","meaning":"صديقة","example":"And their son was excited to introduce his girlfriend.","number":235,"id":"a2:235","level":"A2","lessonId":"a2-set-10"},{"term":"love","meaning":"يحب","example":"'But love and kindness help us feel at home.' Lily was sure they would be friends.","number":236,"id":"a2:236","level":"A2","lessonId":"a2-set-10"},{"term":"married","meaning":"متزوج","example":"Their older daughter was married.","number":237,"id":"a2:237","level":"A2","lessonId":"a2-set-10"},{"term":"home","meaning":"بيت","example":"They live in the home beside mine.'","number":238,"id":"a2:238","level":"A2","lessonId":"a2-set-10"},{"term":"advice","meaning":"نصيحة","example":"Lily offered some advice about the town and showed everyone the safest route to the park.","number":239,"id":"a2:239","level":"A2","lessonId":"a2-set-10"},{"term":"become","meaning":"يصبح","example":"It is not always easy to become part of a new community,' Mrs Green said.","number":240,"id":"a2:240","level":"A2","lessonId":"a2-set-10"},{"term":"bright","meaning":"ساطع","example":"A new neighbour moved into the bright yellow house.","number":241,"id":"a2:241","level":"A2","lessonId":"a2-set-10"},{"term":"easy","meaning":"سهل","example":"It is not always easy to become part of a new community,' Mrs Green said.","number":242,"id":"a2:242","level":"A2","lessonId":"a2-set-10"},{"term":"get up","meaning":"ينهض","example":"You need to get up one more step,' he said with a smile.","number":243,"id":"a2:243","level":"A2","lessonId":"a2-set-10"},{"term":"into","meaning":"إلى داخل","example":"A new neighbour moved into the bright yellow house.","number":244,"id":"a2:244","level":"A2","lessonId":"a2-set-10"},{"term":"mistake","meaning":"خطأ","example":"Unfortunately, she made a mistake and knocked on the wrong door.","number":245,"id":"a2:245","level":"A2","lessonId":"a2-set-10"},{"term":"part","meaning":"جزء","example":"It is not always easy to become part of a new community,' Mrs Green said.","number":246,"id":"a2:246","level":"A2","lessonId":"a2-set-10"},{"term":"shampoo","meaning":"شامبو","example":"A man opened it while putting shampoo back into a bag.","number":247,"id":"a2:247","level":"A2","lessonId":"a2-set-10"},{"term":"sure","meaning":"متأكد","example":"'But love and kindness help us feel at home.' Lily was sure they would be friends.","number":248,"id":"a2:248","level":"A2","lessonId":"a2-set-10"},{"term":"unfortunately","meaning":"لسوء الحظ","example":"Unfortunately, she made a mistake and knocked on the wrong door.","number":249,"id":"a2:249","level":"A2","lessonId":"a2-set-10"},{"term":"young","meaning":"صغير السن","example":"Who was unpacking boxes with their young son and daughter.","number":250,"id":"a2:250","level":"A2","lessonId":"a2-set-10"}],"story":{"title":"The New Neighbour","paragraphs":["A new neighbour moved into the bright yellow house. Mr Green called his wife, who was unpacking boxes with their young son and daughter. Their family was large: one grandparent, a grandchild, and a parent from each side often visited. Her husband was still outside with the furniture.","On Saturday, Lily went next door to welcome them. Unfortunately, she made a mistake and knocked on the wrong door. A man opened it while putting shampoo back into a bag. 'You need to get up one more step,' he said with a smile. 'They live in the home beside mine.'","Lily met the new family. Their older daughter was married, and their son was excited to introduce his girlfriend. His sister's boyfriend had brought a cake. Lily offered some advice about the town and showed everyone the safest route to the park.","'It is not always easy to become part of a new community,' Mrs Green said. 'But love and kindness help us feel at home.' Lily was sure they would be friends. Before leaving, she invited the family into her garden for tea. That evening, the two families laughed about the silly first meeting."],"questions":["Where did Lily first go by mistake?","How did Lily help her new neighbours?","Why did Mrs Green appreciate Lily’s visit?","What does the story suggest about friendship?"]}},{"id":"a2-set-11","title":"The Birthday Secret","subtitle":"A2 reading adventure 11","level":"A2","set":11,"emoji":"🌱","color":"#37BE9C","words":[{"term":"grandma","meaning":"جدة","example":"Grandma arrived just as the party began.","number":251,"id":"a2:251","level":"A2","lessonId":"a2-set-11"},{"term":"party","meaning":"حفلة","example":"Grandma arrived just as the party began.","number":252,"id":"a2:252","level":"A2","lessonId":"a2-set-11"},{"term":"gift","meaning":"هدية","example":"I sent an invitation to each family member and asked everyone to bring a small gift.","number":253,"id":"a2:253","level":"A2","lessonId":"a2-set-11"},{"term":"present","meaning":"هدية أو حاضر","example":"My partner, Sam, helped me carry the present and hide it behind the sofa.","number":254,"id":"a2:254","level":"A2","lessonId":"a2-set-11"},{"term":"balloon","meaning":"بالون","example":"One balloon fell down, and I had to give back a borrowed chair.","number":255,"id":"a2:255","level":"A2","lessonId":"a2-set-11"},{"term":"surprise","meaning":"مفاجأة","example":"So I planned a surprise party for Saturday.","number":256,"id":"a2:256","level":"A2","lessonId":"a2-set-11"},{"term":"midnight","meaning":"منتصف الليل","example":"The cake must belong to the birthday girl!' At midnight.","number":257,"id":"a2:257","level":"A2","lessonId":"a2-set-11"},{"term":"event","meaning":"حدث","example":"We had to prepare for the event without Grandma knowing.","number":258,"id":"a2:258","level":"A2","lessonId":"a2-set-11"},{"term":"invitation","meaning":"دعوة","example":"I sent an invitation to each family member and asked everyone to bring a small gift.","number":259,"id":"a2:259","level":"A2","lessonId":"a2-set-11"},{"term":"weekday","meaning":"يوم عمل","example":"Grandma's birthday fell on a weekday.","number":260,"id":"a2:260","level":"A2","lessonId":"a2-set-11"},{"term":"miss","meaning":"يفتقد","example":"Do not miss the most important part,' he said.","number":261,"id":"a2:261","level":"A2","lessonId":"a2-set-11"},{"term":"to","meaning":"إلى","example":"We had to prepare for the event without Grandma knowing.","number":262,"id":"a2:262","level":"A2","lessonId":"a2-set-11"},{"term":"activity","meaning":"نشاط","example":"I made a colourful sheet with a list of every activity.","number":263,"id":"a2:263","level":"A2","lessonId":"a2-set-11"},{"term":"afterwards","meaning":"بعد ذلك","example":"Afterwards I began to worry that something else would go wrong.","number":264,"id":"a2:264","level":"A2","lessonId":"a2-set-11"},{"term":"belong","meaning":"ينتمي","example":"The cake must belong to the birthday girl!' At midnight.","number":265,"id":"a2:265","level":"A2","lessonId":"a2-set-11"},{"term":"bring","meaning":"يحضر","example":"Then I remembered Grandma's favourite song and asked Sam to bring the music.","number":266,"id":"a2:266","level":"A2","lessonId":"a2-set-11"},{"term":"else","meaning":"غير ذلك","example":"Afterwards I began to worry that something else would go wrong.","number":267,"id":"a2:267","level":"A2","lessonId":"a2-set-11"},{"term":"give back","meaning":"يعيد شيئا","example":"One balloon fell down, and I had to give back a borrowed chair.","number":268,"id":"a2:268","level":"A2","lessonId":"a2-set-11"},{"term":"itself","meaning":"نفسه لغير العاقل","example":"The party itself was more surprising than she expected.","number":269,"id":"a2:269","level":"A2","lessonId":"a2-set-11"},{"term":"more","meaning":"أكثر","example":"The party itself was more surprising than she expected.","number":270,"id":"a2:270","level":"A2","lessonId":"a2-set-11"},{"term":"partner","meaning":"شريك","example":"My partner, Sam, helped me carry the present and hide it behind the sofa.","number":271,"id":"a2:271","level":"A2","lessonId":"a2-set-11"},{"term":"sheet","meaning":"ملاءة أو ورقة","example":"I made a colourful sheet with a list of every activity.","number":272,"id":"a2:272","level":"A2","lessonId":"a2-set-11"},{"term":"surprising","meaning":"مدهش","example":"The party itself was more surprising than she expected.","number":273,"id":"a2:273","level":"A2","lessonId":"a2-set-11"},{"term":"unusual","meaning":"غير معتاد","example":"And made an unusual memory that would last for years.","number":274,"id":"a2:274","level":"A2","lessonId":"a2-set-11"},{"term":"yourself","meaning":"نفسك","example":"You made this for me, all by yourself?' she asked.","number":275,"id":"a2:275","level":"A2","lessonId":"a2-set-11"}],"story":{"title":"The Birthday Secret","paragraphs":["Grandma's birthday fell on a weekday, so I planned a surprise party for Saturday. I sent an invitation to each family member and asked everyone to bring a small gift. My little brother wanted to use a balloon as big as himself, but I told him it might burst.","We had to prepare for the event without Grandma knowing. I made a colourful sheet with a list of every activity. My partner, Sam, helped me carry the present and hide it behind the sofa. 'Do not miss the most important part,' he said. 'The cake must belong to the birthday girl!'","At midnight, I checked the decorations again. One balloon fell down, and I had to give back a borrowed chair. Afterwards I began to worry that something else would go wrong. Then I remembered Grandma's favourite song and asked Sam to bring the music.","Grandma arrived just as the party began. The party itself was more surprising than she expected. 'You made this for me, all by yourself?' she asked. I smiled. 'Not by myself—everyone helped!' We danced, shared the cake, and made an unusual memory that would last for years."],"questions":["Why was the celebration on Saturday?","What jobs did Sam help with?","Why did the narrator worry before the party?","What did Grandma learn about the surprise?"]}},{"id":"a2-set-12","title":"The Map with No Street Names","subtitle":"A2 reading adventure 12","level":"A2","set":12,"emoji":"🌱","color":"#37BE9C","words":[{"term":"area","meaning":"منطقة","example":"They stood at the corner of a busy area near the car park and tried to follow its directions.","number":276,"id":"a2:276","level":"A2","lessonId":"a2-set-12"},{"term":"corner","meaning":"زاوية","example":"They stood at the corner of a busy area near the car park and tried to follow its directions.","number":277,"id":"a2:277","level":"A2","lessonId":"a2-set-12"},{"term":"car park","meaning":"موقف سيارات","example":"They stood at the corner of a busy area near the car park and tried to follow its directions.","number":278,"id":"a2:278","level":"A2","lessonId":"a2-set-12"},{"term":"bus station","meaning":"محطة حافلات","example":"While another pointed across the road towards a bus station.","number":279,"id":"a2:279","level":"A2","lessonId":"a2-set-12"},{"term":"roundabout","meaning":"دوار مروري","example":"The first sign showed a roundabout.","number":280,"id":"a2:280","level":"A2","lessonId":"a2-set-12"},{"term":"directions","meaning":"اتجاهات","example":"They stood at the corner of a busy area near the car park and tried to follow its directions.","number":281,"id":"a2:281","level":"A2","lessonId":"a2-set-12"},{"term":"crossing","meaning":"معبر","example":"At the next crossing, a man walked against the crowd and dropped a shoe.","number":282,"id":"a2:282","level":"A2","lessonId":"a2-set-12"},{"term":"sign","meaning":"لافتة","example":"The first sign showed a roundabout.","number":283,"id":"a2:283","level":"A2","lessonId":"a2-set-12"},{"term":"playground","meaning":"ملعب أطفال","example":"'About half a mile,' said Mia, 'and then we turn at the playground.' She noticed a strange number below the arrow: zero.","number":284,"id":"a2:284","level":"A2","lessonId":"a2-set-12"},{"term":"a few","meaning":"بضعة","example":"A few friends found a map with no street names.","number":285,"id":"a2:285","level":"A2","lessonId":"a2-set-12"},{"term":"about","meaning":"عن أو حوالي","example":"'About half a mile,' said Mia, 'and then we turn at the playground.' She noticed a strange number below the arrow: zero.","number":286,"id":"a2:286","level":"A2","lessonId":"a2-set-12"},{"term":"across","meaning":"عبر","example":"While another pointed across the road towards a bus station.","number":287,"id":"a2:287","level":"A2","lessonId":"a2-set-12"},{"term":"actually","meaning":"في الحقيقة","example":"Are we actually going the right","number":288,"id":"a2:288","level":"A2","lessonId":"a2-set-12"},{"term":"against","meaning":"ضد","example":"At the next crossing, a man walked against the crowd and dropped a shoe.","number":289,"id":"a2:289","level":"A2","lessonId":"a2-set-12"},{"term":"below","meaning":"أسفل","example":"'About half a mile,' said Mia, 'and then we turn at the playground.' She noticed a strange number below the arrow: zero.","number":290,"id":"a2:290","level":"A2","lessonId":"a2-set-12"},{"term":"bring back","meaning":"يعيد","example":"Just bring back the key when you reach the end,' he said.","number":291,"id":"a2:291","level":"A2","lessonId":"a2-set-12"},{"term":"end","meaning":"نهاية","example":"Just bring back the key when you reach the end,' he said.","number":292,"id":"a2:292","level":"A2","lessonId":"a2-set-12"},{"term":"glad","meaning":"مسرور","example":"They were glad to have help.","number":293,"id":"a2:293","level":"A2","lessonId":"a2-set-12"},{"term":"just","meaning":"فقط","example":"Just bring back the key when you reach the end,' he said.","number":294,"id":"a2:294","level":"A2","lessonId":"a2-set-12"},{"term":"most","meaning":"معظم","example":"Most visitors never noticed it because the entrance was hidden behind a wall.","number":295,"id":"a2:295","level":"A2","lessonId":"a2-set-12"},{"term":"pass","meaning":"يمر أو ينجح","example":"The children helped him and asked if they could pass through the gate.","number":296,"id":"a2:296","level":"A2","lessonId":"a2-set-12"},{"term":"shoe","meaning":"حذاء","example":"At the next crossing, a man walked against the crowd and dropped a shoe.","number":297,"id":"a2:297","level":"A2","lessonId":"a2-set-12"},{"term":"take","meaning":"يأخذ","example":"Will this map take us anywhere?' Owen joked.","number":298,"id":"a2:298","level":"A2","lessonId":"a2-set-12"},{"term":"us","meaning":"نحن في حالة المفعول","example":"Will this map take us anywhere?' Owen joked.","number":299,"id":"a2:299","level":"A2","lessonId":"a2-set-12"},{"term":"zero","meaning":"صفر","example":"'About half a mile,' said Mia, 'and then we turn at the playground.' She noticed a strange number below the arrow: zero.","number":300,"id":"a2:300","level":"A2","lessonId":"a2-set-12"}],"story":{"title":"The Map with No Street Names","paragraphs":["A few friends found a map with no street names. They stood at the corner of a busy area near the car park and tried to follow its directions. The first sign showed a roundabout, while another pointed across the road towards a bus station.","'Are we actually going the right way?' asked Owen. 'About half a mile,' said Mia, 'and then we turn at the playground.' She noticed a strange number below the arrow: zero. 'Will this map take us anywhere?' Owen joked. They laughed, but the clue was not that simple.","At the next crossing, a man walked against the crowd and dropped a shoe. The children helped him and asked if they could pass through the gate. 'Just bring back the key when you reach the end,' he said. They were glad to have help.","The final clue took them to a tiny garden. Most visitors never noticed it because the entrance was hidden behind a wall. At last they found a painted box. Inside was a message: 'A town is more interesting when you slow down and look around.' They agreed and took the long way home."],"questions":["What was unusual about the map?","What did the number zero make Owen think?","Why was the garden difficult to find?","What was the message at the end of the hunt?"]}},{"id":"a2-set-13","title":"The Castle on the Hill","subtitle":"A2 reading adventure 13","level":"A2","set":13,"emoji":"🌱","color":"#37BE9C","words":[{"term":"castle","meaning":"قلعة","example":"Our university art club decided to visit a castle above the town.","number":301,"id":"a2:301","level":"A2","lessonId":"a2-set-13"},{"term":"building","meaning":"مبنى","example":"We took a bus ride past an apartment building.","number":302,"id":"a2:302","level":"A2","lessonId":"a2-set-13"},{"term":"block","meaning":"مربع سكني","example":"At the next block, our teacher asked us to find a seat and enjoy the view.","number":303,"id":"a2:303","level":"A2","lessonId":"a2-set-13"},{"term":"department store","meaning":"متجر أقسام","example":"We took a bus ride past an apartment building, a department store, and a grocery store.","number":304,"id":"a2:304","level":"A2","lessonId":"a2-set-13"},{"term":"grocery store","meaning":"متجر بقالة","example":"We took a bus ride past an apartment building, a department store, and a grocery store.","number":305,"id":"a2:305","level":"A2","lessonId":"a2-set-13"},{"term":"college","meaning":"كلية","example":"A small college once stood near the castle wall.","number":306,"id":"a2:306","level":"A2","lessonId":"a2-set-13"},{"term":"cafeteria","meaning":"كافتيريا","example":"We found a cafeteria and bought a hot drink in a large mug.","number":307,"id":"a2:307","level":"A2","lessonId":"a2-set-13"},{"term":"apartment building","meaning":"مبنى شقق","example":"We took a bus ride past an apartment building.","number":308,"id":"a2:308","level":"A2","lessonId":"a2-set-13"},{"term":"seat","meaning":"مقعد","example":"Our teacher asked us to find a seat and enjoy the view.","number":309,"id":"a2:309","level":"A2","lessonId":"a2-set-13"},{"term":"visit","meaning":"يزور","example":"Our university art club decided to visit a castle above the town.","number":310,"id":"a2:310","level":"A2","lessonId":"a2-set-13"},{"term":"department","meaning":"قسم","example":"We took a bus ride past an apartment building, a department store, and a grocery store.","number":311,"id":"a2:311","level":"A2","lessonId":"a2-set-13"},{"term":"ride","meaning":"يركب","example":"We took a bus ride past an apartment building.","number":312,"id":"a2:312","level":"A2","lessonId":"a2-set-13"},{"term":"store","meaning":"متجر","example":"We took a bus ride past an apartment building, a department store, and a grocery store.","number":313,"id":"a2:313","level":"A2","lessonId":"a2-set-13"},{"term":"university","meaning":"جامعة","example":"Our university art club decided to visit a castle above the town.","number":314,"id":"a2:314","level":"A2","lessonId":"a2-set-13"},{"term":"birth","meaning":"ولادة","example":"This was the birth of the old city,' she said.","number":315,"id":"a2:315","level":"A2","lessonId":"a2-set-13"},{"term":"build","meaning":"يبني","example":"At the castle, a guide explained how people had begun to build the great building centuries ago.","number":316,"id":"a2:316","level":"A2","lessonId":"a2-set-13"},{"term":"enjoy","meaning":"يستمتع","example":"Our teacher asked us to find a seat and enjoy the view.","number":317,"id":"a2:317","level":"A2","lessonId":"a2-set-13"},{"term":"gold","meaning":"ذهب","example":"Why is there gold on it?' he wondered.","number":318,"id":"a2:318","level":"A2","lessonId":"a2-set-13"},{"term":"keep","meaning":"يحتفظ أو يواصل","example":"A tiny sign said 'KEEP SHUT'.","number":319,"id":"a2:319","level":"A2","lessonId":"a2-set-13"},{"term":"mug","meaning":"كوب كبير","example":"We found a cafeteria and bought a hot drink in a large mug.","number":320,"id":"a2:320","level":"A2","lessonId":"a2-set-13"},{"term":"pencil case","meaning":"مقلمة","example":"However, my friend Finn spotted a golden key in his pencil case.","number":321,"id":"a2:321","level":"A2","lessonId":"a2-set-13"},{"term":"shut","meaning":"يغلق","example":"A tiny sign said 'KEEP SHUT'.","number":322,"id":"a2:322","level":"A2","lessonId":"a2-set-13"},{"term":"take part","meaning":"يشارك","example":"You may take part if you wish.' We followed her instructions to a hidden store of old maps.","number":323,"id":"a2:323","level":"A2","lessonId":"a2-set-13"},{"term":"use","meaning":"يستخدم","example":"Each visitor could use a map to solve a puzzle.","number":324,"id":"a2:324","level":"A2","lessonId":"a2-set-13"},{"term":"usual","meaning":"معتاد","example":"The usual tour ended at a heavy door.","number":325,"id":"a2:325","level":"A2","lessonId":"a2-set-13"}],"story":{"title":"The Castle on the Hill","paragraphs":["Our university art club decided to visit a castle above the town. We took a bus ride past an apartment building, a department store, and a grocery store. At the next block, our teacher asked us to find a seat and enjoy the view.","At the castle, a guide explained how people had begun to build the great building centuries ago. 'This was the birth of the old city,' she said. A small college once stood near the castle wall, but now the education department uses that space for exhibitions. We found a cafeteria and bought a hot drink in a large mug.","The usual tour ended at a heavy door. A tiny sign said 'KEEP SHUT'. However, my friend Finn spotted a golden key in his pencil case. 'Why is there gold on it?' he wondered. We asked the guide before touching anything.","She smiled. 'That key is part of a history game. You may take part if you wish.' We followed her instructions to a hidden store of old maps. Each visitor could use a map to solve a puzzle. We learned that asking permission is more useful than opening a mystery door without thinking."],"questions":["What places did the class pass on the bus ride?","What was unusual about Finn’s key?","Why did the pupils ask the guide before opening the door?","What lesson does the ending teach?"]}},{"id":"a2-set-14","title":"The Missing Suitcase","subtitle":"A2 reading adventure 14","level":"A2","set":14,"emoji":"🌱","color":"#37BE9C","words":[{"term":"flight","meaning":"رحلة طيران","example":"But the flight was delayed.","number":326,"id":"a2:326","level":"A2","lessonId":"a2-set-14"},{"term":"delayed","meaning":"متأخر","example":"But the flight was delayed.","number":327,"id":"a2:327","level":"A2","lessonId":"a2-set-14"},{"term":"delay","meaning":"تأخير","example":"Perhaps the delay would last several hours.","number":328,"id":"a2:328","level":"A2","lessonId":"a2-set-14"},{"term":"fly","meaning":"يطير","example":"Lena was about to fly to a seaside town for her first explorer tour.","number":329,"id":"a2:329","level":"A2","lessonId":"a2-set-14"},{"term":"take off","meaning":"تقلع الطائرة أو يخلع","example":"And her case disappeared before the plane could take off.","number":330,"id":"a2:330","level":"A2","lessonId":"a2-set-14"},{"term":"case","meaning":"حالة أو حقيبة","example":"Lena discovered her case in the corner.","number":331,"id":"a2:331","level":"A2","lessonId":"a2-set-14"},{"term":"pack","meaning":"يحزم","example":"She had made a list of everything to pack.","number":332,"id":"a2:332","level":"A2","lessonId":"a2-set-14"},{"term":"tour","meaning":"جولة سياحية","example":"Lena was about to fly to a seaside town for her first explorer tour.","number":333,"id":"a2:333","level":"A2","lessonId":"a2-set-14"},{"term":"travel","meaning":"يسافر","example":"A guide suggested they check the travel desk and ask about accommodation for the night.","number":334,"id":"a2:334","level":"A2","lessonId":"a2-set-14"},{"term":"accommodation","meaning":"مكان إقامة","example":"A guide suggested they check the travel desk and ask about accommodation for the night.","number":335,"id":"a2:335","level":"A2","lessonId":"a2-set-14"},{"term":"oil","meaning":"زيت","example":"By accident, Lena gave a small bottle of oil a kick beside a trolley.","number":336,"id":"a2:336","level":"A2","lessonId":"a2-set-14"},{"term":"explorer","meaning":"مستكشف","example":"Lena was about to fly to a seaside town for her first explorer tour.","number":337,"id":"a2:337","level":"A2","lessonId":"a2-set-14"},{"term":"list","meaning":"قائمة","example":"The staff apologised and helped her recheck the list.","number":338,"id":"a2:338","level":"A2","lessonId":"a2-set-14"},{"term":"for","meaning":"من أجل","example":"Lena was about to fly to a seaside town for her first explorer tour.","number":339,"id":"a2:339","level":"A2","lessonId":"a2-set-14"},{"term":"bit","meaning":"قليل","example":"Someone had confused it with another bag that looked a bit like hers.","number":340,"id":"a2:340","level":"A2","lessonId":"a2-set-14"},{"term":"by accident","meaning":"عن طريق الخطأ","example":"By accident, Lena gave a small bottle of oil a kick beside a trolley.","number":341,"id":"a2:341","level":"A2","lessonId":"a2-set-14"},{"term":"especially","meaning":"خصوصا","example":"Especially a golden notebook.","number":342,"id":"a2:342","level":"A2","lessonId":"a2-set-14"},{"term":"golden","meaning":"ذهبي","example":"Especially a golden notebook.","number":343,"id":"a2:343","level":"A2","lessonId":"a2-set-14"},{"term":"kick","meaning":"يركل","example":"By accident, Lena gave a small bottle of oil a kick beside a trolley.","number":344,"id":"a2:344","level":"A2","lessonId":"a2-set-14"},{"term":"myself","meaning":"نفسي","example":"I found it myself!' she cried.","number":345,"id":"a2:345","level":"A2","lessonId":"a2-set-14"},{"term":"people","meaning":"ناس","example":"A worker followed the label to a room where people had left several similar bags.","number":346,"id":"a2:346","level":"A2","lessonId":"a2-set-14"},{"term":"perhaps","meaning":"ربما","example":"Perhaps the delay would last several hours.","number":347,"id":"a2:347","level":"A2","lessonId":"a2-set-14"},{"term":"terrible","meaning":"فظيع","example":"This is terrible!' Lena said.","number":348,"id":"a2:348","level":"A2","lessonId":"a2-set-14"},{"term":"useful","meaning":"مفيد","example":"I put all my useful things in that bag.' Her father tried to help her.","number":349,"id":"a2:349","level":"A2","lessonId":"a2-set-14"},{"term":"variety","meaning":"تنوع","example":"There was still a variety of things to do at the airport.","number":350,"id":"a2:350","level":"A2","lessonId":"a2-set-14"}],"story":{"title":"The Missing Suitcase","paragraphs":["Lena was about to fly to a seaside town for her first explorer tour. She had made a list of everything to pack, especially a golden notebook, a warm jacket and a camera. But the flight was delayed, and her case disappeared before the plane could take off.","'This is terrible!' Lena said. 'I put all my useful things in that bag.' Her father tried to help her, but airport staff could not find it. A guide suggested they check the travel desk and ask about accommodation for the night. Perhaps the delay would last several hours.","By accident, Lena gave a small bottle of oil a kick beside a trolley. It rolled under a chair. She bent down and saw a label from her suitcase. 'I found it myself!' she cried. A worker followed the label to a room where people had left several similar bags.","Lena discovered her case in the corner. Someone had confused it with another bag that looked a bit like hers. The staff apologised and helped her recheck the list. There was still a variety of things to do at the airport, so she spent the extra time drawing a map of her future journey."],"questions":["Why could Lena not leave on time?","What clue did she notice under a chair?","What had caused the bag problem?","How did Lena make use of the delay?"]}},{"id":"a2-set-15","title":"The Longest Bus Ride","subtitle":"A2 reading adventure 15","level":"A2","set":15,"emoji":"🌱","color":"#37BE9C","words":[{"term":"motorway","meaning":"طريق سريع","example":"At a red traffic light near the motorway, the engine made a noise.","number":351,"id":"a2:351","level":"A2","lessonId":"a2-set-15"},{"term":"traffic","meaning":"حركة المرور","example":"The bus left the station, but traffic was heavy.","number":352,"id":"a2:352","level":"A2","lessonId":"a2-set-15"},{"term":"traffic light","meaning":"إشارة مرور","example":"At a red traffic light near the motorway, the engine made a noise.","number":353,"id":"a2:353","level":"A2","lessonId":"a2-set-15"},{"term":"tyre","meaning":"إطار عجلة","example":"A mechanic checked the wheel and found a damaged tyre.","number":354,"id":"a2:354","level":"A2","lessonId":"a2-set-15"},{"term":"engine","meaning":"محرك","example":"At last the engine worked again.","number":355,"id":"a2:355","level":"A2","lessonId":"a2-set-15"},{"term":"wheel","meaning":"عجلة","example":"A mechanic checked the wheel and found a damaged tyre.","number":356,"id":"a2:356","level":"A2","lessonId":"a2-set-15"},{"term":"mechanic","meaning":"ميكانيكي","example":"A mechanic checked the wheel and found a damaged tyre.","number":357,"id":"a2:357","level":"A2","lessonId":"a2-set-15"},{"term":"drive","meaning":"يقود","example":"We cannot drive like this,' he said.","number":358,"id":"a2:358","level":"A2","lessonId":"a2-set-15"},{"term":"motorbike","meaning":"دراجة نارية","example":"Leo knew that a motorbike could be faster than a bus.","number":359,"id":"a2:359","level":"A2","lessonId":"a2-set-15"},{"term":"petrol","meaning":"بنزين","example":"He also noticed that the petrol level was nearly empty.","number":360,"id":"a2:360","level":"A2","lessonId":"a2-set-15"},{"term":"platform","meaning":"رصيف محطة","example":"His mother gave him a kiss goodbye before he went to the platform.","number":361,"id":"a2:361","level":"A2","lessonId":"a2-set-15"},{"term":"tram","meaning":"ترام","example":"One person suggested a tram, while another preferred the underground.","number":362,"id":"a2:362","level":"A2","lessonId":"a2-set-15"},{"term":"underground","meaning":"مترو الأنفاق","example":"One person suggested a tram, while another preferred the underground.","number":363,"id":"a2:363","level":"A2","lessonId":"a2-set-15"},{"term":"transport","meaning":"مواصلات","example":"The passengers began to ask whether another kind of transport would be quicker.","number":364,"id":"a2:364","level":"A2","lessonId":"a2-set-15"},{"term":"born","meaning":"مولود","example":"'I was born in this town,' Mr Grey said, 'and I know a shorter way.' The bus arrived only ten minutes late.","number":365,"id":"a2:365","level":"A2","lessonId":"a2-set-15"},{"term":"cabinet","meaning":"خزانة","example":"Climbed aboard and found a seat beside a cabinet full of travel maps.","number":366,"id":"a2:366","level":"A2","lessonId":"a2-set-15"},{"term":"ever","meaning":"في أي وقت","example":"It was the longest ride Leo had ever taken.","number":367,"id":"a2:367","level":"A2","lessonId":"a2-set-15"},{"term":"grey","meaning":"رمادي","example":"He is Mr Grey.' Leo thanked her.","number":368,"id":"a2:368","level":"A2","lessonId":"a2-set-15"},{"term":"kiss","meaning":"قبلة","example":"His mother gave him a kiss goodbye before he went to the platform.","number":369,"id":"a2:369","level":"A2","lessonId":"a2-set-15"},{"term":"name","meaning":"اسم","example":"Remember the driver's name,' she said.","number":370,"id":"a2:370","level":"A2","lessonId":"a2-set-15"},{"term":"nearly","meaning":"تقريبا","example":"He also noticed that the petrol level was nearly empty.","number":371,"id":"a2:371","level":"A2","lessonId":"a2-set-15"},{"term":"person","meaning":"شخص","example":"One person suggested a tram, while another preferred the underground.","number":372,"id":"a2:372","level":"A2","lessonId":"a2-set-15"},{"term":"than","meaning":"من للمقارنة","example":"His first long ride had taught him more than any map.","number":373,"id":"a2:373","level":"A2","lessonId":"a2-set-15"},{"term":"thank you","meaning":"شكرا لك","example":"Thank you for staying calm,' Leo said.","number":374,"id":"a2:374","level":"A2","lessonId":"a2-set-15"},{"term":"various","meaning":"متنوع","example":"The driver explained the various choices clearly.","number":375,"id":"a2:375","level":"A2","lessonId":"a2-set-15"}],"story":{"title":"The Longest Bus Ride","paragraphs":["It was the longest ride Leo had ever taken. His mother gave him a kiss goodbye before he went to the platform. 'Remember the driver's name,' she said. 'He is Mr Grey.' Leo thanked her, climbed aboard and found a seat beside a cabinet full of travel maps.","The bus left the station, but traffic was heavy. At a red traffic light near the motorway, the engine made a noise. A mechanic checked the wheel and found a damaged tyre. He also noticed that the petrol level was nearly empty. 'We cannot drive like this,' he said.","The passengers began to ask whether another kind of transport would be quicker. One person suggested a tram, while another preferred the underground. Leo knew that a motorbike could be faster than a bus, but it could not carry everyone. The driver explained the various choices clearly.","At last the engine worked again. 'I was born in this town,' Mr Grey said, 'and I know a shorter way.' The bus arrived only ten minutes late. 'Thank you for staying calm,' Leo said. His first long ride had taught him more than any map."],"questions":["What two problems did the mechanic find?","Why was a motorbike not a good solution?","How did Mr Grey help at the end?","Which qualities helped the journey end well?"]}},{"id":"a2-set-16","title":"The Storm at the Campsite","subtitle":"A2 reading adventure 16","level":"A2","set":16,"emoji":"🌱","color":"#37BE9C","words":[{"term":"camp","meaning":"يخيم","example":"We heard a frightened pet barking from a nearby camp.","number":376,"id":"a2:376","level":"A2","lessonId":"a2-set-16"},{"term":"camping","meaning":"تخييم","example":"Every summer, our club goes camping beside a large lake.","number":377,"id":"a2:377","level":"A2","lessonId":"a2-set-16"},{"term":"campsite","meaning":"موقع تخييم","example":"Soon the campsite became foggy.","number":378,"id":"a2:378","level":"A2","lessonId":"a2-set-16"},{"term":"tent","meaning":"خيمة","example":"This year, we put up a tent at a new campsite.","number":379,"id":"a2:379","level":"A2","lessonId":"a2-set-16"},{"term":"raincoat","meaning":"معطف مطر","example":"I wore a raincoat and carried an umbrella because the forecast mentioned a thunderstorm.","number":380,"id":"a2:380","level":"A2","lessonId":"a2-set-16"},{"term":"fog","meaning":"ضباب","example":"Our guide said the fog might grow thicker after dark.","number":381,"id":"a2:381","level":"A2","lessonId":"a2-set-16"},{"term":"foggy","meaning":"ضبابي","example":"Soon the campsite became foggy.","number":382,"id":"a2:382","level":"A2","lessonId":"a2-set-16"},{"term":"cloudy","meaning":"غائم","example":"The morning weather was sunny, but the afternoon became cloudy and windy.","number":383,"id":"a2:383","level":"A2","lessonId":"a2-set-16"},{"term":"thunderstorm","meaning":"عاصفة رعدية","example":"I wore a raincoat and carried an umbrella because the forecast mentioned a thunderstorm.","number":384,"id":"a2:384","level":"A2","lessonId":"a2-set-16"},{"term":"sunny","meaning":"مشمس","example":"The morning weather was sunny, but the afternoon became cloudy and windy.","number":385,"id":"a2:385","level":"A2","lessonId":"a2-set-16"},{"term":"windy","meaning":"عاصف","example":"The morning weather was sunny, but the afternoon became cloudy and windy.","number":386,"id":"a2:386","level":"A2","lessonId":"a2-set-16"},{"term":"weather","meaning":"طقس","example":"The morning weather was sunny, but the afternoon became cloudy and windy.","number":387,"id":"a2:387","level":"A2","lessonId":"a2-set-16"},{"term":"umbrella","meaning":"مظلة","example":"I wore a raincoat and carried an umbrella because the forecast mentioned a thunderstorm.","number":388,"id":"a2:388","level":"A2","lessonId":"a2-set-16"},{"term":"dark","meaning":"مظلم","example":"Our guide said the fog might grow thicker after dark.","number":389,"id":"a2:389","level":"A2","lessonId":"a2-set-16"},{"term":"safe","meaning":"آمن","example":"That is not safe,' I told him.","number":390,"id":"a2:390","level":"A2","lessonId":"a2-set-16"},{"term":"danger","meaning":"خطر","example":"'There is danger near the water when the fog is heavy.' At first Sam thought I was being too careful.","number":391,"id":"a2:391","level":"A2","lessonId":"a2-set-16"},{"term":"every","meaning":"كل","example":"Every summer, our club goes camping beside a large lake.","number":392,"id":"a2:392","level":"A2","lessonId":"a2-set-16"},{"term":"grow up","meaning":"يكبر","example":"I will grow up to be an adventurer.","number":393,"id":"a2:393","level":"A2","lessonId":"a2-set-16"},{"term":"large","meaning":"كبير","example":"Every summer, our club goes camping beside a large lake.","number":394,"id":"a2:394","level":"A2","lessonId":"a2-set-16"},{"term":"least","meaning":"الأقل","example":"At least two adults were already looking for it.","number":395,"id":"a2:395","level":"A2","lessonId":"a2-set-16"},{"term":"need","meaning":"يحتاج","example":"'We need a simple plan,' said the guide, so we used a whistle and called out from the dry ground rather than running into the storm.","number":396,"id":"a2:396","level":"A2","lessonId":"a2-set-16"},{"term":"pet","meaning":"حيوان أليف","example":"We heard a frightened pet barking from a nearby camp.","number":397,"id":"a2:397","level":"A2","lessonId":"a2-set-16"},{"term":"simple","meaning":"بسيط","example":"'We need a simple plan,' said the guide, so we used a whistle and called out from the dry ground rather than running into the storm.","number":398,"id":"a2:398","level":"A2","lessonId":"a2-set-16"},{"term":"that","meaning":"ذلك","example":"That is not safe,' I told him.","number":399,"id":"a2:399","level":"A2","lessonId":"a2-set-16"},{"term":"very","meaning":"جدا","example":"Very clever!' said the guide.","number":400,"id":"a2:400","level":"A2","lessonId":"a2-set-16"}],"story":{"title":"The Storm at the Campsite","paragraphs":["Every summer, our club goes camping beside a large lake. This year, we put up a tent at a new campsite. The morning weather was sunny, but the afternoon became cloudy and windy. Our guide said the fog might grow thicker after dark.","I wore a raincoat and carried an umbrella because the forecast mentioned a thunderstorm. My friend Sam wanted to explore the path alone. 'That is not safe,' I told him. 'There is danger near the water when the fog is heavy.' At first Sam thought I was being too careful.","Soon the campsite became foggy. We heard a frightened pet barking from a nearby camp. At least two adults were already looking for it. 'We need a simple plan,' said the guide, so we used a whistle and called out from the dry ground rather than running into the storm.","The dog came towards us and sat beside the tent. 'Very clever!' said the guide. We kept it warm until its owner arrived. The sky cleared later, and we watched the stars. Sam smiled. 'I will grow up to be an adventurer,' he said, 'but I must learn how to be a careful one.'"],"questions":["How did the weather change during the day?","Why did the narrator warn Sam about the lake?","How did the group help the lost dog safely?","What did Sam learn about adventure?"]}},{"id":"a2-set-17","title":"The Rainforest Path","subtitle":"A2 reading adventure 17","level":"A2","set":17,"emoji":"🌱","color":"#37BE9C","words":[{"term":"rainforest","meaning":"غابة مطيرة","example":"Our class visited a rainforest education centre.","number":401,"id":"a2:401","level":"A2","lessonId":"a2-set-17"},{"term":"grow","meaning":"ينمو","example":"The guide showed us how plants grow from the ground and how animals need clean air and enough space to live.","number":402,"id":"a2:402","level":"A2","lessonId":"a2-set-17"},{"term":"farm","meaning":"مزرعة","example":"It was close to a small farm.","number":403,"id":"a2:403","level":"A2","lessonId":"a2-set-17"},{"term":"ground","meaning":"أرض","example":"The guide showed us how plants grow from the ground and how animals need clean air and enough space to live.","number":404,"id":"a2:404","level":"A2","lessonId":"a2-set-17"},{"term":"spring","meaning":"فصل الربيع","example":"Four pictures showed spring.","number":405,"id":"a2:405","level":"A2","lessonId":"a2-set-17"},{"term":"summer","meaning":"الصيف","example":"In the first room, four pictures showed spring, summer, autumn and winter.","number":406,"id":"a2:406","level":"A2","lessonId":"a2-set-17"},{"term":"autumn","meaning":"الخريف","example":"In the first room, four pictures showed spring, summer, autumn and winter.","number":407,"id":"a2:407","level":"A2","lessonId":"a2-set-17"},{"term":"winter","meaning":"شتاء","example":"In the first room, four pictures showed spring, summer, autumn and winter.","number":408,"id":"a2:408","level":"A2","lessonId":"a2-set-17"},{"term":"air","meaning":"هواء","example":"The guide showed us how plants grow from the ground and how animals need clean air and enough space to live.","number":409,"id":"a2:409","level":"A2","lessonId":"a2-set-17"},{"term":"space","meaning":"فضاء أو مساحة","example":"Give them space,' said a sign beside the display.","number":410,"id":"a2:410","level":"A2","lessonId":"a2-set-17"},{"term":"wildlife","meaning":"حياة برية","example":"Do not bother the wildlife.","number":411,"id":"a2:411","level":"A2","lessonId":"a2-set-17"},{"term":"creature","meaning":"مخلوق","example":"'A rainforest has seasons too,' the guide explained, 'although they may look different.' We saw a model of a strange creature that lived in the forest.","number":412,"id":"a2:412","level":"A2","lessonId":"a2-set-17"},{"term":"fire","meaning":"حريق","example":"It was part of a fire-safety","number":413,"id":"a2:413","level":"A2","lessonId":"a2-set-17"},{"term":"alarm clock","meaning":"ساعة منبه","example":"At the end of the path, we heard an alarm clock ringing.","number":414,"id":"a2:414","level":"A2","lessonId":"a2-set-17"},{"term":"bother","meaning":"يزعج","example":"Do not bother the wildlife.","number":415,"id":"a2:415","level":"A2","lessonId":"a2-set-17"},{"term":"carefully","meaning":"بحذر","example":"We followed the instructions carefully and found the nearest exit.","number":416,"id":"a2:416","level":"A2","lessonId":"a2-set-17"},{"term":"everybody","meaning":"الجميع","example":"Our guide said that a fire could spread quickly if everybody ignored the warning.","number":417,"id":"a2:417","level":"A2","lessonId":"a2-set-17"},{"term":"guess","meaning":"يخمن","example":"Nobody could guess its name.","number":418,"id":"a2:418","level":"A2","lessonId":"a2-set-17"},{"term":"last","meaning":"الأخير","example":"The last activity was to pick up rubbish near the trail.","number":419,"id":"a2:419","level":"A2","lessonId":"a2-set-17"},{"term":"less","meaning":"أقل","example":"We collected one single bag, which was less than we had expected.","number":420,"id":"a2:420","level":"A2","lessonId":"a2-set-17"},{"term":"new","meaning":"جديد","example":"On the way home, we each wrote one new fact we wanted to remember.","number":421,"id":"a2:421","level":"A2","lessonId":"a2-set-17"},{"term":"pick up","meaning":"يلتقط","example":"The last activity was to pick up rubbish near the trail.","number":422,"id":"a2:422","level":"A2","lessonId":"a2-set-17"},{"term":"single","meaning":"مفرد أو أعزب","example":"We collected one single bag, which was less than we had expected.","number":423,"id":"a2:423","level":"A2","lessonId":"a2-set-17"},{"term":"them","meaning":"هم في حالة المفعول","example":"Give them space,' said a sign beside the display.","number":424,"id":"a2:424","level":"A2","lessonId":"a2-set-17"},{"term":"view","meaning":"منظر أو رأي","example":"The guide thanked us and showed us the wonderful view from the top of a wooden tower.","number":425,"id":"a2:425","level":"A2","lessonId":"a2-set-17"}],"story":{"title":"The Rainforest Path","paragraphs":["Our class visited a rainforest education centre. It was close to a small farm, but the trees made it feel like another world. The guide showed us how plants grow from the ground and how animals need clean air and enough space to live.","In the first room, four pictures showed spring, summer, autumn and winter. 'A rainforest has seasons too,' the guide explained, 'although they may look different.' We saw a model of a strange creature that lived in the forest. Nobody could guess its name. 'Do not bother the wildlife. Give them space,' said a sign beside the display.","At the end of the path, we heard an alarm clock ringing. It was part of a fire-safety demonstration. Our guide said that a fire could spread quickly if everybody ignored the warning. We followed the instructions carefully and found the nearest exit.","The last activity was to pick up rubbish near the trail. We collected one single bag, which was less than we had expected. The guide thanked us and showed us the wonderful view from the top of a wooden tower. On the way home, we each wrote one new fact we wanted to remember."],"questions":["What did the guide explain about plants and animals?","Why did an alarm clock ring?","What practical action did the pupils take?","Why was the final activity useful?"]}},{"id":"a2-set-18","title":"The Lighthouse Rescue","subtitle":"A2 reading adventure 18","level":"A2","set":18,"emoji":"🌱","color":"#37BE9C","words":[{"term":"sea","meaning":"بحر","example":"The sun was bright when our class reached the sea.","number":426,"id":"a2:426","level":"A2","lessonId":"a2-set-18"},{"term":"coast","meaning":"ساحل","example":"But everyone wanted to look at the coast first.","number":427,"id":"a2:427","level":"A2","lessonId":"a2-set-18"},{"term":"harbour","meaning":"ميناء","example":"At the harbour, a guidebook showed a path to an old lighthouse near the port.","number":428,"id":"a2:428","level":"A2","lessonId":"a2-set-18"},{"term":"port","meaning":"ميناء","example":"A guidebook showed a path to an old lighthouse near the port.","number":429,"id":"a2:429","level":"A2","lessonId":"a2-set-18"},{"term":"sail","meaning":"يبحر","example":"On the beach, some people were learning to sail.","number":430,"id":"a2:430","level":"A2","lessonId":"a2-set-18"},{"term":"sailing","meaning":"إبحار","example":"Others were practising sailing in a small boat.","number":431,"id":"a2:431","level":"A2","lessonId":"a2-set-18"},{"term":"dive","meaning":"يغوص","example":"His friend wanted to dive in after him, but the lifeguard stopped him.","number":432,"id":"a2:432","level":"A2","lessonId":"a2-set-18"},{"term":"diving","meaning":"غوص","example":"Do not try diving into rough water,' she warned.","number":433,"id":"a2:433","level":"A2","lessonId":"a2-set-18"},{"term":"surf","meaning":"يركب الأمواج","example":"A coach showed children how to surf with a surfboard.","number":434,"id":"a2:434","level":"A2","lessonId":"a2-set-18"},{"term":"surfing","meaning":"ركوب الأمواج","example":"I would love to try surfing.","number":435,"id":"a2:435","level":"A2","lessonId":"a2-set-18"},{"term":"surfboard","meaning":"لوح ركوب الأمواج","example":"A coach showed children how to surf with a surfboard.","number":436,"id":"a2:436","level":"A2","lessonId":"a2-set-18"},{"term":"windsurfing","meaning":"التزلج الشراعي","example":"While a different group tried windsurfing and surfboarding.","number":437,"id":"a2:437","level":"A2","lessonId":"a2-set-18"},{"term":"surfboarding","meaning":"ركوب الأمواج بلوح","example":"A coach showed children how to surf with a surfboard, while a different group tried windsurfing and surfboarding.","number":438,"id":"a2:438","level":"A2","lessonId":"a2-set-18"},{"term":"swim","meaning":"يسبح","example":"A boy who had gone for a swim was struggling to return.","number":439,"id":"a2:439","level":"A2","lessonId":"a2-set-18"},{"term":"swimming","meaning":"سباحة","example":"We ended the day with a lesson about swimming safely and listening to trained adults.","number":440,"id":"a2:440","level":"A2","lessonId":"a2-set-18"},{"term":"certainly","meaning":"بالتأكيد","example":"'Certainly,' replied the teacher, 'but we should be thankful that everyone is safe.' The two boys warmed themselves in the shelter.","number":441,"id":"a2:441","level":"A2","lessonId":"a2-set-18"},{"term":"everyone","meaning":"كل شخص","example":"But everyone wanted to look at the coast first.","number":442,"id":"a2:442","level":"A2","lessonId":"a2-set-18"},{"term":"guidebook","meaning":"دليل سياحي","example":"A guidebook showed a path to an old lighthouse near the port.","number":443,"id":"a2:443","level":"A2","lessonId":"a2-set-18"},{"term":"later","meaning":"لاحقا","example":"But we must be careful.' Later.","number":444,"id":"a2:444","level":"A2","lessonId":"a2-set-18"},{"term":"let","meaning":"يسمح لـ","example":"'Let us help.' The lifeguard used a rescue board and helped the boy to safety.","number":445,"id":"a2:445","level":"A2","lessonId":"a2-set-18"},{"term":"next","meaning":"التالي","example":"Our teacher said we could sit down and wait for the next boat.","number":446,"id":"a2:446","level":"A2","lessonId":"a2-set-18"},{"term":"pity","meaning":"شفقة","example":"What a pity the weather changed!' said Mia.","number":447,"id":"a2:447","level":"A2","lessonId":"a2-set-18"},{"term":"sit down","meaning":"يجلس","example":"Our teacher said we could sit down and wait for the next boat.","number":448,"id":"a2:448","level":"A2","lessonId":"a2-set-18"},{"term":"themselves","meaning":"أنفسهم","example":"'Certainly,' replied the teacher, 'but we should be thankful that everyone is safe.' The two boys warmed themselves in the shelter.","number":449,"id":"a2:449","level":"A2","lessonId":"a2-set-18"},{"term":"wait","meaning":"ينتظر","example":"Our teacher said we could sit down and wait for the next boat.","number":450,"id":"a2:450","level":"A2","lessonId":"a2-set-18"}],"story":{"title":"The Lighthouse Rescue","paragraphs":["The sun was bright when our class reached the sea. At the harbour, a guidebook showed a path to an old lighthouse near the port. Our teacher said we could sit down and wait for the next boat, but everyone wanted to look at the coast first.","On the beach, some people were learning to sail. Others were practising sailing in a small boat. A coach showed children how to surf with a surfboard, while a different group tried windsurfing and surfboarding. 'I would love to try surfing,' said Mia, 'but we must be careful.'","Later, a strong wind arrived. A boy who had gone for a swim was struggling to return. His friend wanted to dive in after him, but the lifeguard stopped him. 'Do not try diving into rough water,' she warned. 'Let us help.' The lifeguard used a rescue board and helped the boy to safety.","'What a pity the weather changed!' said Mia. 'Certainly,' replied the teacher, 'but we should be thankful that everyone is safe.' The two boys warmed themselves in the shelter. We ended the day with a lesson about swimming safely and listening to trained adults."],"questions":["What activities did the children see at the beach?","Why did the lifeguard stop the boy’s friend?","How was the struggling swimmer rescued?","What was the most important lesson of the trip?"]}},{"id":"a2-set-19","title":"The Animal Detective","subtitle":"A2 reading adventure 19","level":"A2","set":19,"emoji":"🌱","color":"#37BE9C","words":[{"term":"animal","meaning":"حيوان","example":"She had learned that even a small animal can change someone's life.","number":451,"id":"a2:451","level":"A2","lessonId":"a2-set-19"},{"term":"bee","meaning":"نحلة","example":"One photograph showed a tiny bee beside a beetle.","number":452,"id":"a2:452","level":"A2","lessonId":"a2-set-19"},{"term":"beetle","meaning":"خنفساء","example":"One photograph showed a tiny bee beside a beetle.","number":453,"id":"a2:453","level":"A2","lessonId":"a2-set-19"},{"term":"insect","meaning":"حشرة","example":"Another had an insect sitting near a spider.","number":454,"id":"a2:454","level":"A2","lessonId":"a2-set-19"},{"term":"eagle","meaning":"نسر","example":"There was also an eagle high above its nest.","number":455,"id":"a2:455","level":"A2","lessonId":"a2-set-19"},{"term":"jellyfish","meaning":"قنديل البحر","example":"A jellyfish and an octopus.","number":456,"id":"a2:456","level":"A2","lessonId":"a2-set-19"},{"term":"octopus","meaning":"أخطبوط","example":"A jellyfish and an octopus.","number":457,"id":"a2:457","level":"A2","lessonId":"a2-set-19"},{"term":"panda","meaning":"باندا","example":"Then came photographs of a panda, a polar bear and a beautiful swan.","number":458,"id":"a2:458","level":"A2","lessonId":"a2-set-19"},{"term":"polar bear","meaning":"دب قطبي","example":"Then came photographs of a panda, a polar bear and a beautiful swan.","number":459,"id":"a2:459","level":"A2","lessonId":"a2-set-19"},{"term":"puppy","meaning":"جرو","example":"The puppy ran straight towards them.","number":460,"id":"a2:460","level":"A2","lessonId":"a2-set-19"},{"term":"butterfly","meaning":"فراشة","example":"There was also an eagle high above its nest, a slow snail, a bright butterfly, a green lizard and a shy tortoise.","number":461,"id":"a2:461","level":"A2","lessonId":"a2-set-19"},{"term":"lizard","meaning":"سحلية","example":"A green lizard and a shy tortoise.","number":462,"id":"a2:462","level":"A2","lessonId":"a2-set-19"},{"term":"snail","meaning":"حلزون","example":"There was also an eagle high above its nest, a slow snail, a bright butterfly, a green lizard and a shy tortoise.","number":463,"id":"a2:463","level":"A2","lessonId":"a2-set-19"},{"term":"spider","meaning":"عنكبوت","example":"Another had an insect sitting near a spider.","number":464,"id":"a2:464","level":"A2","lessonId":"a2-set-19"},{"term":"swan","meaning":"بجعة","example":"Then came photographs of a panda, a polar bear and a beautiful swan.","number":465,"id":"a2:465","level":"A2","lessonId":"a2-set-19"},{"term":"tortoise","meaning":"سلحفاة برية","example":"A green lizard and a shy tortoise.","number":466,"id":"a2:466","level":"A2","lessonId":"a2-set-19"},{"term":"nest","meaning":"عش","example":"There was also an eagle high above its nest.","number":467,"id":"a2:467","level":"A2","lessonId":"a2-set-19"},{"term":"fur","meaning":"فراء","example":"It had a fluffy tail and soft fur.","number":468,"id":"a2:468","level":"A2","lessonId":"a2-set-19"},{"term":"tail","meaning":"ذيل","example":"It had a fluffy tail and soft fur.","number":469,"id":"a2:469","level":"A2","lessonId":"a2-set-19"},{"term":"life","meaning":"حياة","example":"She had learned that even a small animal can change someone's life.","number":470,"id":"a2:470","level":"A2","lessonId":"a2-set-19"},{"term":"perfect","meaning":"مثالي","example":"This is the perfect place to search for its owner,' Mia said.","number":471,"id":"a2:471","level":"A2","lessonId":"a2-set-19"},{"term":"place","meaning":"مكان","example":"This is the perfect place to search for its owner,' Mia said.","number":472,"id":"a2:472","level":"A2","lessonId":"a2-set-19"},{"term":"site","meaning":"موقع","example":"'We have pictures of every animal at the centre.' She checked the nature site on her tablet.","number":473,"id":"a2:473","level":"A2","lessonId":"a2-set-19"},{"term":"then","meaning":"ثم","example":"Then came photographs of a panda, a polar bear and a beautiful swan.","number":474,"id":"a2:474","level":"A2","lessonId":"a2-set-19"},{"term":"wake up","meaning":"يستيقظ","example":"And it kept trying to wake up the sleepy keeper.","number":475,"id":"a2:475","level":"A2","lessonId":"a2-set-19"}],"story":{"title":"The Animal Detective","paragraphs":["At the wildlife centre, Mia was helping to look after a lost puppy. It had a fluffy tail and soft fur, and it kept trying to wake up the sleepy keeper. 'This is the perfect place to search for its owner,' Mia said. 'We have pictures of every animal at the centre.'","She checked the nature site on her tablet. One photograph showed a tiny bee beside a beetle. Another had an insect sitting near a spider. There was also an eagle high above its nest, a slow snail, a bright butterfly, a green lizard and a shy tortoise. The puppy looked at each picture but did not react.","In the next room were displays of sea animals: a jellyfish and an octopus. Then came photographs of a panda, a polar bear and a beautiful swan. 'What an unusual collection!' Mia laughed. But the little dog still seemed unhappy.","Finally, she saw a family standing near the entrance with a photograph of their missing pet. The puppy ran straight towards them. 'A happy ending!' said Mia. The keeper thanked her for helping another creature get back to its family. She had learned that even a small animal can change someone's life."],"questions":["Which animal was actually lost?","Where did Mia search for clues?","How did Mia know she had found the owners?","Why does the title call Mia a detective?"]}},{"id":"a2-set-20","title":"The Sports Day Surprise","subtitle":"A2 reading adventure 20","level":"A2","set":20,"emoji":"🌱","color":"#37BE9C","words":[{"term":"olympic","meaning":"أولمبي","example":"Our school held a special olympic sports day at the stadium.","number":476,"id":"a2:476","level":"A2","lessonId":"a2-set-20"},{"term":"cricket","meaning":"الكريكيت","example":"Everything was ready: a cricket match, a rugby game, a tennis player giving a demonstration and a running race.","number":477,"id":"a2:477","level":"A2","lessonId":"a2-set-20"},{"term":"rugby","meaning":"رياضة الرغبي","example":"Everything was ready: a cricket match, a rugby game, a tennis player giving a demonstration and a running race.","number":478,"id":"a2:478","level":"A2","lessonId":"a2-set-20"},{"term":"sport","meaning":"رياضة","example":"'I want to win the first prize,' he said, 'but what if something goes wrong?' I told him that sport was about trying your best, not only becoming the winner.","number":479,"id":"a2:479","level":"A2","lessonId":"a2-set-20"},{"term":"stadium","meaning":"ملعب كبير","example":"Our school held a special olympic sports day at the stadium.","number":480,"id":"a2:480","level":"A2","lessonId":"a2-set-20"},{"term":"prize","meaning":"جائزة","example":"Still, his team gave him a small prize for kindness.","number":481,"id":"a2:481","level":"A2","lessonId":"a2-set-20"},{"term":"winner","meaning":"فائز","example":"Not only becoming the winner.","number":482,"id":"a2:482","level":"A2","lessonId":"a2-set-20"},{"term":"game","meaning":"لعبة","example":"Everything was ready: a cricket match, a rugby game, a tennis player giving a demonstration and a running race.","number":483,"id":"a2:483","level":"A2","lessonId":"a2-set-20"},{"term":"match","meaning":"مباراة أو يطابق","example":"Everything was ready: a cricket match, a rugby game, a tennis player giving a demonstration and a running race.","number":484,"id":"a2:484","level":"A2","lessonId":"a2-set-20"},{"term":"player","meaning":"لاعب","example":"He had learned what it meant to be a good player.","number":485,"id":"a2:485","level":"A2","lessonId":"a2-set-20"},{"term":"tennis player","meaning":"لاعب تنس","example":"A tennis player giving a demonstration and a running race.","number":486,"id":"a2:486","level":"A2","lessonId":"a2-set-20"},{"term":"runner","meaning":"عداء","example":"My brother was a runner, but he did not like being watched by a large crowd.","number":487,"id":"a2:487","level":"A2","lessonId":"a2-set-20"},{"term":"running","meaning":"جري","example":"Everything was ready: a cricket match, a rugby game, a tennis player giving a demonstration and a running race.","number":488,"id":"a2:488","level":"A2","lessonId":"a2-set-20"},{"term":"watch","meaning":"يشاهد","example":"We stood on one side of the track to watch the race.","number":489,"id":"a2:489","level":"A2","lessonId":"a2-set-20"},{"term":"bottom","meaning":"أسفل الشيء","example":"A skateboard rolled out and stopped at the bottom of the steps.","number":490,"id":"a2:490","level":"A2","lessonId":"a2-set-20"},{"term":"clearly","meaning":"بوضوح","example":"Clearly more worried about the boy than the result.","number":491,"id":"a2:491","level":"A2","lessonId":"a2-set-20"},{"term":"everything","meaning":"كل شيء","example":"Everything was ready: a cricket match, a rugby game, a tennis player giving a demonstration and a running race.","number":492,"id":"a2:492","level":"A2","lessonId":"a2-set-20"},{"term":"happen","meaning":"يحدث","example":"How did that happen?' asked a teacher.","number":493,"id":"a2:493","level":"A2","lessonId":"a2-set-20"},{"term":"help","meaning":"يساعد","example":"My brother ran to help, clearly more worried about the boy than the result.","number":494,"id":"a2:494","level":"A2","lessonId":"a2-set-20"},{"term":"like","meaning":"يحب","example":"But he did not like being watched by a large crowd.","number":495,"id":"a2:495","level":"A2","lessonId":"a2-set-20"},{"term":"no","meaning":"لا","example":"No one is hurt,\" he said.","number":496,"id":"a2:496","level":"A2","lessonId":"a2-set-20"},{"term":"side","meaning":"جانب","example":"We stood on one side of the track to watch the race.","number":497,"id":"a2:497","level":"A2","lessonId":"a2-set-20"},{"term":"skateboarding","meaning":"التزلج بلوح","example":"A boy who loved skateboarding dropped his bag.","number":498,"id":"a2:498","level":"A2","lessonId":"a2-set-20"},{"term":"these","meaning":"هؤلاء","example":"These moments are more important than medals,' said the teacher.","number":499,"id":"a2:499","level":"A2","lessonId":"a2-set-20"},{"term":"walking","meaning":"مشي","example":"As the players began walking towards the line.","number":500,"id":"a2:500","level":"A2","lessonId":"a2-set-20"}],"story":{"title":"The Sports Day Surprise","paragraphs":["Our school held a special olympic sports day at the stadium. Everything was ready: a cricket match, a rugby game, a tennis player giving a demonstration and a running race. My brother was a runner, but he did not like being watched by a large crowd.","'I want to win the first prize,' he said, 'but what if something goes wrong?' I told him that sport was about trying your best, not only becoming the winner. We stood on one side of the track to watch the race.","As the players began walking towards the line, a boy who loved skateboarding dropped his bag. A skateboard rolled out and stopped at the bottom of the steps. Everyone looked shocked. 'How did that happen?' asked a teacher. My brother ran to help, clearly more worried about the boy than the result. \"No one is hurt,\" he said.","The race started late, but the crowd cheered when the boys returned. My brother did not win; he finished second. Still, his team gave him a small prize for kindness. 'These moments are more important than medals,' said the teacher. My brother smiled. He had learned what it meant to be a good player."],"questions":["Which sporting events were planned?","What interrupted the race?","Why did the brother receive a prize even though he did not win?","What message does the story give about sport?"]}},{"id":"a2-set-21","title":"The Winter Games","subtitle":"A2 reading adventure 21","level":"A2","set":21,"emoji":"🌱","color":"#37BE9C","words":[{"term":"ice","meaning":"جليد","example":"There was ice everywhere, so we moved carefully.","number":501,"id":"a2:501","level":"A2","lessonId":"a2-set-21"},{"term":"ice skating","meaning":"التزلج على الجليد","example":"We could go ice skating in the morning.","number":502,"id":"a2:502","level":"A2","lessonId":"a2-set-21"},{"term":"skating","meaning":"تزلج","example":"When we returned, the children were still skating.","number":503,"id":"a2:503","level":"A2","lessonId":"a2-set-21"},{"term":"ski","meaning":"يتزلج على الثلج","example":"Ski later and finish with snowboarding.","number":504,"id":"a2:504","level":"A2","lessonId":"a2-set-21"},{"term":"skate","meaning":"يتزلج","example":"And another teacher helped us skate safely.","number":505,"id":"a2:505","level":"A2","lessonId":"a2-set-21"},{"term":"snowboarding","meaning":"التزلج بلوح الثلج","example":"Ski later and finish with snowboarding.","number":506,"id":"a2:506","level":"A2","lessonId":"a2-set-21"},{"term":"snowboard","meaning":"لوح تزلج ثلجي","example":"A trainer showed us how to use a snowboard.","number":507,"id":"a2:507","level":"A2","lessonId":"a2-set-21"},{"term":"swimming pool","meaning":"مسبح","example":"We also saw a swimming pool indoors.","number":508,"id":"a2:508","level":"A2","lessonId":"a2-set-21"},{"term":"swimsuit","meaning":"ملابس سباحة","example":"Who would bring a swimsuit to a snowy mountain?' Omar laughed.","number":509,"id":"a2:509","level":"A2","lessonId":"a2-set-21"},{"term":"bike","meaning":"دراجة","example":"A family had brought a bike and a photo album too.","number":510,"id":"a2:510","level":"A2","lessonId":"a2-set-21"},{"term":"kit","meaning":"عدة أدوات","example":"We found an extra kit in the store.","number":511,"id":"a2:511","level":"A2","lessonId":"a2-set-21"},{"term":"play","meaning":"يلعب","example":"He wanted to play outside anyway.","number":512,"id":"a2:512","level":"A2","lessonId":"a2-set-21"},{"term":"pool","meaning":"مسبح","example":"We also saw a swimming pool","number":513,"id":"a2:513","level":"A2","lessonId":"a2-set-21"},{"term":"album","meaning":"ألبوم","example":"A family had brought a bike and a photo album too.","number":514,"id":"a2:514","level":"A2","lessonId":"a2-set-21"},{"term":"break down","meaning":"يتعطل","example":"Suddenly their car began to break down near the centre.","number":515,"id":"a2:515","level":"A2","lessonId":"a2-set-21"},{"term":"climbing","meaning":"تسلق","example":"Later we went climbing up a gentle hill.","number":516,"id":"a2:516","level":"A2","lessonId":"a2-set-21"},{"term":"everywhere","meaning":"في كل مكان","example":"There was ice everywhere, so we moved carefully.","number":517,"id":"a2:517","level":"A2","lessonId":"a2-set-21"},{"term":"have to","meaning":"يجب أن","example":"You have to look after yourself,' I said.","number":518,"id":"a2:518","level":"A2","lessonId":"a2-set-21"},{"term":"helpful","meaning":"مفيد","example":"No one was hurt, but they needed helpful advice.","number":519,"id":"a2:519","level":"A2","lessonId":"a2-set-21"},{"term":"look after","meaning":"يعتني بـ","example":"You have to look after yourself,' I said.","number":520,"id":"a2:520","level":"A2","lessonId":"a2-set-21"},{"term":"no one","meaning":"لا أحد","example":"No one was hurt, but they needed helpful advice.","number":521,"id":"a2:521","level":"A2","lessonId":"a2-set-21"},{"term":"pleased","meaning":"مسرور","example":"Omar was pleased when he could borrow a warm jacket.","number":522,"id":"a2:522","level":"A2","lessonId":"a2-set-21"},{"term":"slim","meaning":"نحيف","example":"My friend Omar was tall and slim, but his coat was too thin for the cold.","number":523,"id":"a2:523","level":"A2","lessonId":"a2-set-21"},{"term":"thin","meaning":"نحيف أو رقيق","example":"My friend Omar was tall and slim, but his coat was too thin for the cold.","number":524,"id":"a2:524","level":"A2","lessonId":"a2-set-21"},{"term":"want","meaning":"يريد","example":"Omar said he did not want to miss the next adventure.","number":525,"id":"a2:525","level":"A2","lessonId":"a2-set-21"}],"story":{"title":"The Winter Games","paragraphs":["The mountain sports centre had an unusual winter games program. We could go ice skating in the morning, ski later and finish with snowboarding. A trainer showed us how to use a snowboard, and another teacher helped us skate safely.","My friend Omar was tall and slim, but his coat was too thin for the cold. He wanted to play outside anyway. 'You have to look after yourself,' I said. We found an extra kit in the store. Omar was pleased when he could borrow a warm jacket.","We also saw a swimming pool indoors. 'Who would bring a swimsuit to a snowy mountain?' Omar laughed. A family had brought a bike and a photo album too. Suddenly their car began to break down near the centre. No one was hurt, but they needed helpful advice. We called the staff, who fixed the problem.","Later we went climbing up a gentle hill. There was ice everywhere, so we moved carefully. Omar said he did not want to miss the next adventure. When we returned, the children were still skating. I wrote a note in our album: 'The best winter day is a safe one.'"],"questions":["What winter activities did the centre offer?","Why did Omar need a different jacket?","What unexpected problem did a family have?","How did the group show good judgment during the day?"]}},{"id":"a2-set-22","title":"The Painting That Moved","subtitle":"A2 reading adventure 22","level":"A2","set":22,"emoji":"🌱","color":"#37BE9C","words":[{"term":"art","meaning":"فن","example":"Art is not just about what you see.","number":526,"id":"a2:526","level":"A2","lessonId":"a2-set-22"},{"term":"gallery","meaning":"معرض فني","example":"An art gallery opened a new show on Saturday.","number":527,"id":"a2:527","level":"A2","lessonId":"a2-set-22"},{"term":"painter","meaning":"رسام","example":"The painter wore headphones and asked us to act as art detectives.","number":528,"id":"a2:528","level":"A2","lessonId":"a2-set-22"},{"term":"picture","meaning":"صورة","example":"That piece is hers,' he said, pointing to a woman in the picture.","number":529,"id":"a2:529","level":"A2","lessonId":"a2-set-22"},{"term":"colour","meaning":"لون","example":"A bright poster on the door said, 'Come back and look for the painter's secret.' Inside, an attractive picture seemed to change colour whenever anyone moved past it.","number":530,"id":"a2:530","level":"A2","lessonId":"a2-set-22"},{"term":"poster","meaning":"ملصق","example":"A bright poster on the door said.","number":531,"id":"a2:531","level":"A2","lessonId":"a2-set-22"},{"term":"cover","meaning":"غطاء أو يغطي","example":"After a while, a guide told us to cover one eye.","number":532,"id":"a2:532","level":"A2","lessonId":"a2-set-22"},{"term":"attractive","meaning":"جذاب","example":"A bright poster on the door said, 'Come back and look for the painter's secret.' Inside, an attractive picture seemed to change colour whenever anyone moved past it.","number":533,"id":"a2:533","level":"A2","lessonId":"a2-set-22"},{"term":"beautiful","meaning":"جميل","example":"My sister Anna thought it was beautiful.","number":534,"id":"a2:534","level":"A2","lessonId":"a2-set-22"},{"term":"brilliant","meaning":"ممتاز","example":"'The light makes the picture look different from different places.' I thought the idea was brilliant.","number":535,"id":"a2:535","level":"A2","lessonId":"a2-set-22"},{"term":"act","meaning":"يتصرف أو يمثل","example":"The painter wore headphones and asked us to act as art detectives.","number":536,"id":"a2:536","level":"A2","lessonId":"a2-set-22"},{"term":"chess","meaning":"شطرنج","example":"On the wall was a chess board with one missing piece.","number":537,"id":"a2:537","level":"A2","lessonId":"a2-set-22"},{"term":"look","meaning":"ينظر","example":"'The light makes the picture look different from different places.' I thought the idea was brilliant.","number":538,"id":"a2:538","level":"A2","lessonId":"a2-set-22"},{"term":"show","meaning":"يعرض","example":"An art gallery opened a new show on Saturday.","number":539,"id":"a2:539","level":"A2","lessonId":"a2-set-22"},{"term":"anyone","meaning":"أي أحد","example":"A bright poster on the door said, 'Come back and look for the painter's secret.' Inside, an attractive picture seemed to change colour whenever anyone moved past it.","number":540,"id":"a2:540","level":"A2","lessonId":"a2-set-22"},{"term":"come back","meaning":"يعود","example":"Come back and look for the painter's secret.' Inside.","number":541,"id":"a2:541","level":"A2","lessonId":"a2-set-22"},{"term":"exactly","meaning":"بالضبط","example":"Exactly!' she said.","number":542,"id":"a2:542","level":"A2","lessonId":"a2-set-22"},{"term":"headphones","meaning":"سماعات رأس","example":"The painter wore headphones and asked us to act as art detectives.","number":543,"id":"a2:543","level":"A2","lessonId":"a2-set-22"},{"term":"hers","meaning":"ملكها","example":"That piece is hers,' he said, pointing to a woman in the picture.","number":544,"id":"a2:544","level":"A2","lessonId":"a2-set-22"},{"term":"look for","meaning":"يبحث عن","example":"Come back and look for the painter's secret.' Inside.","number":545,"id":"a2:545","level":"A2","lessonId":"a2-set-22"},{"term":"nobody","meaning":"لا أحد","example":"We looked carefully, but nobody could find it.","number":546,"id":"a2:546","level":"A2","lessonId":"a2-set-22"},{"term":"plus","meaning":"زائد","example":"Plus a tiny thing the artist had drawn.","number":547,"id":"a2:547","level":"A2","lessonId":"a2-set-22"},{"term":"thank","meaning":"يشكر","example":"Thank you for visiting,' she said.","number":548,"id":"a2:548","level":"A2","lessonId":"a2-set-22"},{"term":"thing","meaning":"شيء","example":"Plus a tiny thing the artist had drawn.","number":549,"id":"a2:549","level":"A2","lessonId":"a2-set-22"},{"term":"washing-up","meaning":"غسل الصحون","example":"At the small gallery café, a worker was doing the washing-up.","number":550,"id":"a2:550","level":"A2","lessonId":"a2-set-22"}],"story":{"title":"The Painting That Moved","paragraphs":["An art gallery opened a new show on Saturday. A bright poster on the door said, 'Come back and look for the painter's secret.' Inside, an attractive picture seemed to change colour whenever anyone moved past it.","My sister Anna thought it was beautiful, but I wanted to know how it worked. The painter wore headphones and asked us to act as art detectives. On the wall was a chess board with one missing piece. 'That piece is hers,' he said, pointing to a woman in the picture. We looked carefully, but nobody could find it.","After a while, a guide told us to cover one eye. Suddenly the missing piece appeared! 'Exactly!' she said. 'The light makes the picture look different from different places.' I thought the idea was brilliant.","At the small gallery café, a worker was doing the washing-up. She overheard our conversation and showed us another picture, plus a tiny thing the artist had drawn. 'Thank you for visiting,' she said. 'Art is not just about what you see. It is also about what you think you see.' We left with a new reason to ask questions."],"questions":["What seemed unusual about the picture?","What helped the children see the missing chess piece?","Why did the painter ask them to act as detectives?","What does the guide’s final idea mean?"]}},{"id":"a2-set-23","title":"The Music Contest","subtitle":"A2 reading adventure 23","level":"A2","set":23,"emoji":"🌱","color":"#37BE9C","words":[{"term":"jazz","meaning":"موسيقى الجاز","example":"One band played jazz, another performed rap, and a third group sang pop.","number":551,"id":"a2:551","level":"A2","lessonId":"a2-set-23"},{"term":"rap","meaning":"موسيقى الراب","example":"One band played jazz, another performed rap, and a third group sang pop.","number":552,"id":"a2:552","level":"A2","lessonId":"a2-set-23"},{"term":"pop","meaning":"موسيقى البوب","example":"One band played jazz, another performed rap, and a third group sang pop.","number":553,"id":"a2:553","level":"A2","lessonId":"a2-set-23"},{"term":"opera","meaning":"أوبرا","example":"There was even an opera singer and a student preparing a musical.","number":554,"id":"a2:554","level":"A2","lessonId":"a2-set-23"},{"term":"musical","meaning":"مسرحية موسيقية","example":"There was even an opera singer and a student preparing a musical.","number":555,"id":"a2:555","level":"A2","lessonId":"a2-set-23"},{"term":"musician","meaning":"موسيقي","example":"The town music contest invited every kind of musician.","number":556,"id":"a2:556","level":"A2","lessonId":"a2-set-23"},{"term":"violin","meaning":"كمان","example":"My sister Nora was a dancer, but she also played the violin.","number":557,"id":"a2:557","level":"A2","lessonId":"a2-set-23"},{"term":"band","meaning":"فرقة موسيقية","example":"One band played jazz, another performed rap, and a third group sang pop.","number":558,"id":"a2:558","level":"A2","lessonId":"a2-set-23"},{"term":"microphone","meaning":"ميكروفون","example":"'I think so,' she said, 'except that the microphone makes my voice sound strange.' The speaker made a loud noise during the first test.","number":559,"id":"a2:559","level":"A2","lessonId":"a2-set-23"},{"term":"speaker","meaning":"مكبر صوت","example":"'I think so,' she said, 'except that the microphone makes my voice sound strange.' The speaker made a loud noise during the first test.","number":560,"id":"a2:560","level":"A2","lessonId":"a2-set-23"},{"term":"singing","meaning":"غناء","example":"Are you comfortable singing alone?' I asked.","number":561,"id":"a2:561","level":"A2","lessonId":"a2-set-23"},{"term":"dancer","meaning":"راقص","example":"My sister Nora was a dancer, but she also played the violin.","number":562,"id":"a2:562","level":"A2","lessonId":"a2-set-23"},{"term":"dancing","meaning":"رقص","example":"After her performance, a small child asked if he could try dancing too.","number":563,"id":"a2:563","level":"A2","lessonId":"a2-set-23"},{"term":"song","meaning":"أغنية","example":"She wanted to perform a song herself, without anyone helping.","number":564,"id":"a2:564","level":"A2","lessonId":"a2-set-23"},{"term":"anything","meaning":"أي شيء","example":"I cannot think of anything better,' Nora laughed.","number":565,"id":"a2:565","level":"A2","lessonId":"a2-set-23"},{"term":"comfortable","meaning":"مريح","example":"Are you comfortable singing alone?' I asked.","number":566,"id":"a2:566","level":"A2","lessonId":"a2-set-23"},{"term":"except","meaning":"باستثناء","example":"'I think so,' she said, 'except that the microphone makes my voice sound strange.' The speaker made a loud noise during the first test.","number":567,"id":"a2:567","level":"A2","lessonId":"a2-set-23"},{"term":"hello","meaning":"مرحبا","example":"The audience said hello as each performer came on stage.","number":568,"id":"a2:568","level":"A2","lessonId":"a2-set-23"},{"term":"herself","meaning":"هي نفسها","example":"She wanted to perform a song herself, without anyone helping.","number":569,"id":"a2:569","level":"A2","lessonId":"a2-set-23"},{"term":"look out","meaning":"ينتبه","example":"Look out!' shouted the teacher.","number":570,"id":"a2:570","level":"A2","lessonId":"a2-set-23"},{"term":"noise","meaning":"ضوضاء","example":"'I think so,' she said, 'except that the microphone makes my voice sound strange.' The speaker made a loud noise during the first test.","number":571,"id":"a2:571","level":"A2","lessonId":"a2-set-23"},{"term":"point","meaning":"نقطة","example":"The point of music is to share it,' she said.","number":572,"id":"a2:572","level":"A2","lessonId":"a2-set-23"},{"term":"slowly","meaning":"ببطء","example":"This time she began slowly and listened carefully.","number":573,"id":"a2:573","level":"A2","lessonId":"a2-set-23"},{"term":"think","meaning":"يفكر","example":"I cannot think of anything better,' Nora laughed.","number":574,"id":"a2:574","level":"A2","lessonId":"a2-set-23"},{"term":"well known","meaning":"معروف جيدا","example":"A well known musician in the audience gave her an encouraging smile.","number":575,"id":"a2:575","level":"A2","lessonId":"a2-set-23"}],"story":{"title":"The Music Contest","paragraphs":["The town music contest invited every kind of musician. One band played jazz, another performed rap, and a third group sang pop. There was even an opera singer and a student preparing a musical. The audience said hello as each performer came on stage.","My sister Nora was a dancer, but she also played the violin. She wanted to perform a song herself, without anyone helping. 'Are you comfortable singing alone?' I asked. 'I think so,' she said, 'except that the microphone makes my voice sound strange.'","The speaker made a loud noise during the first test. 'Look out!' shouted the teacher. Nora stopped, checked the cable and tried again. This time she began slowly and listened carefully. A well known musician in the audience gave her an encouraging smile.","After her performance, a small child asked if he could try dancing too. Nora invited him onto the stage. 'The point of music is to share it,' she said. The judges agreed and awarded her the teamwork prize. 'I cannot think of anything better,' Nora laughed. She had found the courage to share her talent."],"questions":["What kinds of music were performed?","What went wrong during Nora’s sound test?","Why did Nora invite a child onto the stage?","What does her prize suggest the judges valued?"]}},{"id":"a2-set-24","title":"The Film Studio Mystery","subtitle":"A2 reading adventure 24","level":"A2","set":24,"emoji":"🌱","color":"#37BE9C","words":[{"term":"film","meaning":"فيلم","example":"A famous movie star invited our class to visit a film studio.","number":576,"id":"a2:576","level":"A2","lessonId":"a2-set-24"},{"term":"cartoon","meaning":"رسم متحرك","example":"We saw a cartoon poster, an ad for a horror film, and a photographer taking pictures of a celebrity.","number":577,"id":"a2:577","level":"A2","lessonId":"a2-set-24"},{"term":"comedy","meaning":"كوميديا","example":"The latest advertisement promised an exciting comedy about a lost treasure.","number":578,"id":"a2:578","level":"A2","lessonId":"a2-set-24"},{"term":"movie star","meaning":"نجم سينمائي","example":"This was not a normal visit,' the movie star laughed.","number":579,"id":"a2:579","level":"A2","lessonId":"a2-set-24"},{"term":"celebrity","meaning":"شخص مشهور","example":"And a photographer taking pictures of a celebrity.","number":580,"id":"a2:580","level":"A2","lessonId":"a2-set-24"},{"term":"blog","meaning":"مدونة","example":"On a studio blog, someone had posted a short review of the film.","number":581,"id":"a2:581","level":"A2","lessonId":"a2-set-24"},{"term":"ad","meaning":"إعلان","example":"We saw a cartoon poster, an ad for a horror film, and a photographer taking pictures of a celebrity.","number":582,"id":"a2:582","level":"A2","lessonId":"a2-set-24"},{"term":"advertisement","meaning":"إعلان","example":"The latest advertisement promised an exciting comedy about a lost treasure.","number":583,"id":"a2:583","level":"A2","lessonId":"a2-set-24"},{"term":"horror","meaning":"رعب","example":"We saw a cartoon poster, an ad for a horror film, and a photographer taking pictures of a celebrity.","number":584,"id":"a2:584","level":"A2","lessonId":"a2-set-24"},{"term":"scary","meaning":"مخيف","example":"That is scary,' whispered my friend, although he knew it was only a game.","number":585,"id":"a2:585","level":"A2","lessonId":"a2-set-24"},{"term":"make-up","meaning":"مستحضرات تجميل","example":"Somebody took it out of the box,' said the make-up artist.","number":586,"id":"a2:586","level":"A2","lessonId":"a2-set-24"},{"term":"photographer","meaning":"مصور فوتوغرافي","example":"And a photographer taking pictures of a celebrity.","number":587,"id":"a2:587","level":"A2","lessonId":"a2-set-24"},{"term":"look at","meaning":"ينظر إلى","example":"The director asked us to look at a","number":588,"id":"a2:588","level":"A2","lessonId":"a2-set-24"},{"term":"out","meaning":"خارج","example":"Somebody took it out of the box,' said the make-up artist.","number":589,"id":"a2:589","level":"A2","lessonId":"a2-set-24"},{"term":"anyway","meaning":"على أي حال","example":"We began to search anyway.","number":590,"id":"a2:590","level":"A2","lessonId":"a2-set-24"},{"term":"complete","meaning":"يكمل","example":"The shelf was empty, but a small note told us to complete a puzzle.","number":591,"id":"a2:591","level":"A2","lessonId":"a2-set-24"},{"term":"exciting","meaning":"مثير","example":"The latest advertisement promised an exciting comedy about a lost treasure.","number":592,"id":"a2:592","level":"A2","lessonId":"a2-set-24"},{"term":"fill","meaning":"يملأ","example":"We used a pen to fill the missing letters in a word and found a final clue.","number":593,"id":"a2:593","level":"A2","lessonId":"a2-set-24"},{"term":"latest","meaning":"الأحدث","example":"The latest advertisement promised an exciting comedy about a lost treasure.","number":594,"id":"a2:594","level":"A2","lessonId":"a2-set-24"},{"term":"lost","meaning":"ضائع","example":"The latest advertisement promised an exciting comedy about a lost treasure.","number":595,"id":"a2:595","level":"A2","lessonId":"a2-set-24"},{"term":"normal","meaning":"طبيعي","example":"This was not a normal visit,' the movie star laughed.","number":596,"id":"a2:596","level":"A2","lessonId":"a2-set-24"},{"term":"possibly","meaning":"من المحتمل","example":"The director said it was possibly a good idea, so we checked.","number":597,"id":"a2:597","level":"A2","lessonId":"a2-set-24"},{"term":"somebody","meaning":"شخص ما","example":"Somebody took it out of the box,' said the make-up artist.","number":598,"id":"a2:598","level":"A2","lessonId":"a2-set-24"},{"term":"this","meaning":"هذا","example":"This was not a normal visit,' the movie star laughed.","number":599,"id":"a2:599","level":"A2","lessonId":"a2-set-24"},{"term":"what","meaning":"ماذا","example":"What if the costume is there?' I asked.","number":600,"id":"a2:600","level":"A2","lessonId":"a2-set-24"}],"story":{"title":"The Film Studio Mystery","paragraphs":["A famous movie star invited our class to visit a film studio. The latest advertisement promised an exciting comedy about a lost treasure. We saw a cartoon poster, an ad for a horror film, and a photographer taking pictures of a celebrity.","The director asked us to look at a special costume. 'This is the most important thing in the film,' he explained. But the costume was missing! 'Somebody took it out of the box,' said the make-up artist. 'That is scary,' whispered my friend, although he knew it was only a game.","We began to search anyway. On a studio blog, someone had posted a short review of the film. It mentioned a secret shelf behind the door. 'What if the costume is there?' I asked. The director said it was possibly a good idea, so we checked.","The shelf was empty, but a small note told us to complete a puzzle. We used a pen to fill the missing letters in a word and found a final clue. Then we opened a curtain and discovered the costume. 'This was not a normal visit,' the movie star laughed. 'You have just helped us finish the story!'"],"questions":["Why did the class visit the studio?","What important object was missing?","How did the blog help their search?","What did the pupils learn about creating a film?"]}},{"id":"a2-set-25","title":"The Town Festival","subtitle":"A2 reading adventure 25","level":"A2","set":25,"emoji":"🌱","color":"#37BE9C","words":[{"term":"circus","meaning":"سيرك","example":"At the entrance, a clown from the circus welcomed us.","number":601,"id":"a2:601","level":"A2","lessonId":"a2-set-25"},{"term":"clown","meaning":"مهرج","example":"The clown smiled at himself in a mirror.","number":602,"id":"a2:602","level":"A2","lessonId":"a2-set-25"},{"term":"festival","meaning":"مهرجان","example":"Our town planned a festival to celebrate the opening of a new club.","number":603,"id":"a2:603","level":"A2","lessonId":"a2-set-25"},{"term":"club","meaning":"نادي","example":"Our town planned a festival to celebrate the opening of a new club.","number":604,"id":"a2:604","level":"A2","lessonId":"a2-set-25"},{"term":"fun","meaning":"متعة","example":"Is this going to be fun?' asked Leo.","number":605,"id":"a2:605","level":"A2","lessonId":"a2-set-25"},{"term":"crowd","meaning":"حشد","example":"A crowd of children followed him, and the square soon became crowded.","number":606,"id":"a2:606","level":"A2","lessonId":"a2-set-25"},{"term":"crowded","meaning":"مزدحم","example":"A crowd of children followed him, and the square soon became crowded.","number":607,"id":"a2:607","level":"A2","lessonId":"a2-set-25"},{"term":"celebrate","meaning":"يحتفل","example":"Our town planned a festival to celebrate the opening of a new club.","number":608,"id":"a2:608","level":"A2","lessonId":"a2-set-25"},{"term":"hobby","meaning":"هواية","example":"I wanted to join because my hobby was to collect unusual tickets.","number":609,"id":"a2:609","level":"A2","lessonId":"a2-set-25"},{"term":"collect","meaning":"يجمع","example":"I wanted to join because my hobby was to collect unusual tickets.","number":610,"id":"a2:610","level":"A2","lessonId":"a2-set-25"},{"term":"join","meaning":"ينضم","example":"I wanted to join because my hobby was to collect unusual tickets.","number":611,"id":"a2:611","level":"A2","lessonId":"a2-set-25"},{"term":"video game","meaning":"لعبة إلكترونية","example":"Another asked us to fill in a form about our favourite video game.","number":612,"id":"a2:612","level":"A2","lessonId":"a2-set-25"},{"term":"go out","meaning":"يخرج","example":"A volunteer explained that we could go out to explore the stalls, but no one could enter the stage without permission.","number":613,"id":"a2:613","level":"A2","lessonId":"a2-set-25"},{"term":"allow","meaning":"يسمح","example":"We do not allow people to climb up there,' she warned in a loud voice.","number":614,"id":"a2:614","level":"A2","lessonId":"a2-set-25"},{"term":"anywhere","meaning":"في أي مكان","example":"My brother wanted to go sightseeing anywhere he liked.","number":615,"id":"a2:615","level":"A2","lessonId":"a2-set-25"},{"term":"copy","meaning":"ينسخ","example":"One stall invited us to copy an old advert onto a card.","number":616,"id":"a2:616","level":"A2","lessonId":"a2-set-25"},{"term":"experience","meaning":"تجربة","example":"'The best experience is the surprise you share with friends.' We agreed that the day had been special.","number":617,"id":"a2:617","level":"A2","lessonId":"a2-set-25"},{"term":"fill in","meaning":"يملأ استمارة","example":"Another asked us to fill in a form about our favourite video game.","number":618,"id":"a2:618","level":"A2","lessonId":"a2-set-25"},{"term":"himself","meaning":"هو نفسه","example":"The clown smiled at himself in a mirror.","number":619,"id":"a2:619","level":"A2","lessonId":"a2-set-25"},{"term":"loud","meaning":"عال الصوت","example":"We do not allow people to climb up there,' she warned in a loud voice.","number":620,"id":"a2:620","level":"A2","lessonId":"a2-set-25"},{"term":"not","meaning":"ليس","example":"We do not allow people to climb up there,' she warned in a loud voice.","number":621,"id":"a2:621","level":"A2","lessonId":"a2-set-25"},{"term":"sightseeing","meaning":"زيارة المعالم","example":"My brother wanted to go sightseeing anywhere he liked.","number":622,"id":"a2:622","level":"A2","lessonId":"a2-set-25"},{"term":"someone","meaning":"شخص ما","example":"But I reminded him that someone had to stay with our group.","number":623,"id":"a2:623","level":"A2","lessonId":"a2-set-25"},{"term":"those","meaning":"أولئك","example":"The clown asked us to watch those coloured boxes.","number":624,"id":"a2:624","level":"A2","lessonId":"a2-set-25"},{"term":"when","meaning":"متى","example":"When did you take them?' I laughed.","number":625,"id":"a2:625","level":"A2","lessonId":"a2-set-25"}],"story":{"title":"The Town Festival","paragraphs":["Our town planned a festival to celebrate the opening of a new club. I wanted to join because my hobby was to collect unusual tickets. At the entrance, a clown from the circus welcomed us. A crowd of children followed him, and the square soon became crowded.","'Is this going to be fun?' asked Leo. 'Of course!' I said. A volunteer explained that we could go out to explore the stalls, but no one could enter the stage without permission. 'We do not allow people to climb up there,' she warned in a loud voice.","One stall invited us to copy an old advert onto a card. Another asked us to fill in a form about our favourite video game. My brother wanted to go sightseeing anywhere he liked, but I reminded him that someone had to stay with our group. We went together instead.","When the magician appeared, the clown asked us to watch those coloured boxes. One box was empty; the other contained our missing tickets! 'When did you take them?' I laughed. The clown smiled at himself in a mirror. 'The best experience is the surprise you share with friends.' We agreed that the day had been special."],"questions":["Why did the narrator want to attend the festival?","What did the volunteer forbid?","Why did the narrator stop the brother from exploring alone?","What made the festival memorable?"]}},{"id":"a2-set-26","title":"The Helpful Hospital Visitor","subtitle":"A2 reading adventure 26","level":"A2","set":26,"emoji":"🌱","color":"#37BE9C","words":[{"term":"accident","meaning":"حادث","example":"We saw an accident near a chemist and a drugstore.","number":626,"id":"a2:626","level":"A2","lessonId":"a2-set-26"},{"term":"ambulance","meaning":"سيارة إسعاف","example":"Someone called an ambulance.","number":627,"id":"a2:627","level":"A2","lessonId":"a2-set-26"},{"term":"chemist","meaning":"صيدلي","example":"We saw an accident near a chemist and a drugstore.","number":628,"id":"a2:628","level":"A2","lessonId":"a2-set-26"},{"term":"drugstore","meaning":"صيدلية","example":"We saw an accident near a chemist and a drugstore.","number":629,"id":"a2:629","level":"A2","lessonId":"a2-set-26"},{"term":"health","meaning":"صحة","example":"Your health matters too,' I said.","number":630,"id":"a2:630","level":"A2","lessonId":"a2-set-26"},{"term":"hurt","meaning":"يؤلم","example":"A cyclist had fallen and hurt his arm.","number":631,"id":"a2:631","level":"A2","lessonId":"a2-set-26"},{"term":"stomach ache","meaning":"ألم المعدة","example":"But she had a stomach ache and a toothache herself.","number":632,"id":"a2:632","level":"A2","lessonId":"a2-set-26"},{"term":"toothache","meaning":"ألم الأسنان","example":"But she had a stomach ache and a toothache herself.","number":633,"id":"a2:633","level":"A2","lessonId":"a2-set-26"},{"term":"lie down","meaning":"يستلقي","example":"Please lie down and stay still,' a nurse advised him.","number":634,"id":"a2:634","level":"A2","lessonId":"a2-set-26"},{"term":"dangerous","meaning":"خطير","example":"Moving a broken arm can be dangerous.' My friend Jo wanted to help.","number":635,"id":"a2:635","level":"A2","lessonId":"a2-set-26"},{"term":"broken","meaning":"مكسور","example":"Moving a broken arm can be dangerous.' My friend Jo wanted to help.","number":636,"id":"a2:636","level":"A2","lessonId":"a2-set-26"},{"term":"cut","meaning":"يقطع","example":"A child had a small cut on his finger.","number":637,"id":"a2:637","level":"A2","lessonId":"a2-set-26"},{"term":"hear","meaning":"يسمع","example":"We could hear laughter from inside.","number":638,"id":"a2:638","level":"A2","lessonId":"a2-set-26"},{"term":"soap","meaning":"صابون","example":"So the nurse washed it gently with water and soap.","number":639,"id":"a2:639","level":"A2","lessonId":"a2-set-26"},{"term":"well","meaning":"بصورة جيدة","example":"We found a place to sit and checked that the cyclist was well.","number":640,"id":"a2:640","level":"A2","lessonId":"a2-set-26"},{"term":"correct","meaning":"صحيح","example":"We needed the correct details before we could go through the door.","number":641,"id":"a2:641","level":"A2","lessonId":"a2-set-26"},{"term":"explore","meaning":"يستكشف","example":"The nurse invited us to explore a children's art room.","number":642,"id":"a2:642","level":"A2","lessonId":"a2-set-26"},{"term":"final","meaning":"نهائي","example":"When the final check was complete.","number":643,"id":"a2:643","level":"A2","lessonId":"a2-set-26"},{"term":"hit","meaning":"يضرب","example":"A ball rolled across the floor and hit my shoe.","number":644,"id":"a2:644","level":"A2","lessonId":"a2-set-26"},{"term":"nationality","meaning":"جنسية","example":"It included nationality, our reason for visiting and where we were going.","number":645,"id":"a2:645","level":"A2","lessonId":"a2-set-26"},{"term":"nothing","meaning":"لا شيء","example":"Nothing is more important than safety,' said the volunteer.","number":646,"id":"a2:646","level":"A2","lessonId":"a2-set-26"},{"term":"print","meaning":"يطبع","example":"At the hospital, a volunteer asked us to print a visitor form.","number":647,"id":"a2:647","level":"A2","lessonId":"a2-set-26"},{"term":"something","meaning":"شيء ما","example":"Something good can happen even after a difficult morning,' Jo said.","number":648,"id":"a2:648","level":"A2","lessonId":"a2-set-26"},{"term":"through","meaning":"من خلال","example":"We needed the correct details before we could go through the door.","number":649,"id":"a2:649","level":"A2","lessonId":"a2-set-26"},{"term":"where","meaning":"أين","example":"It included nationality, our reason for visiting and where we were going.","number":650,"id":"a2:650","level":"A2","lessonId":"a2-set-26"}],"story":{"title":"The Helpful Hospital Visitor","paragraphs":["On our way to a museum, we saw an accident near a chemist and a drugstore. A cyclist had fallen and hurt his arm. Someone called an ambulance. 'Please lie down and stay still,' a nurse advised him. 'Moving a broken arm can be dangerous.'","My friend Jo wanted to help, but she had a stomach ache and a toothache herself. 'Your health matters too,' I said. We found a place to sit and checked that the cyclist was well. A child had a small cut on his finger, so the nurse washed it gently with water and soap.","At the hospital, a volunteer asked us to print a visitor form. It included nationality, our reason for visiting and where we were going. We needed the correct details before we could go through the door. 'Nothing is more important than safety,' said the volunteer.","When the final check was complete, the nurse invited us to explore a children's art room. A ball rolled across the floor and hit my shoe. We could hear laughter from inside. 'Something good can happen even after a difficult morning,' Jo said. We went home thankful for the people who had helped."],"questions":["What happened near the shops?","Why did the nurse ask him not to move?","What details did the hospital visitor form request?","Why does Jo feel positive at the end?"]}},{"id":"a2-set-27","title":"The Fitness Experiment","subtitle":"A2 reading adventure 27","level":"A2","set":27,"emoji":"🌱","color":"#37BE9C","words":[{"term":"body","meaning":"جسم","example":"A healthy body needs movement, sleep and good food,' she said.","number":651,"id":"a2:651","level":"A2","lessonId":"a2-set-27"},{"term":"fit","meaning":"لائق بدنيا","example":"Our class decided to test how to get fit in four weeks.","number":652,"id":"a2:652","level":"A2","lessonId":"a2-set-27"},{"term":"get fit","meaning":"يصبح لائقا","example":"Our class decided to test how to get fit in four weeks.","number":653,"id":"a2:653","level":"A2","lessonId":"a2-set-27"},{"term":"gym","meaning":"صالة رياضية","example":"A coach at the gym asked us to check our habits.","number":654,"id":"a2:654","level":"A2","lessonId":"a2-set-27"},{"term":"fall over","meaning":"يقع","example":"Began to fall over and nearly hit the ground.","number":655,"id":"a2:655","level":"A2","lessonId":"a2-set-27"},{"term":"smoking","meaning":"تدخين","example":"'Smoking is harmful, and even smoke from other people can cause a problem.' My friend Ben wanted to run around the park every day.","number":656,"id":"a2:656","level":"A2","lessonId":"a2-set-27"},{"term":"smoke","meaning":"دخان","example":"'Smoking is harmful, and even smoke from other people can cause a problem.' My friend Ben wanted to run around the park every day.","number":657,"id":"a2:657","level":"A2","lessonId":"a2-set-27"},{"term":"check","meaning":"يتحقق","example":"A coach at the gym asked us to check our habits.","number":658,"id":"a2:658","level":"A2","lessonId":"a2-set-27"},{"term":"dead","meaning":"ميت","example":"The experiment is not dead,' Ben joked.","number":659,"id":"a2:659","level":"A2","lessonId":"a2-set-27"},{"term":"die","meaning":"يموت","example":"The coach explained that a dangerous accident can make someone seriously ill or even die, so we must be careful.","number":660,"id":"a2:660","level":"A2","lessonId":"a2-set-27"},{"term":"fall","meaning":"يسقط","example":"Began to fall over and nearly hit the ground.","number":661,"id":"a2:661","level":"A2","lessonId":"a2-set-27"},{"term":"feel","meaning":"يشعر","example":"We also agreed to notice how we feel, not just the number on a scale.","number":662,"id":"a2:662","level":"A2","lessonId":"a2-set-27"},{"term":"problem","meaning":"مشكلة","example":"'Smoking is harmful, and even smoke from other people can cause a problem.' My friend Ben wanted to run around the park every day.","number":663,"id":"a2:663","level":"A2","lessonId":"a2-set-27"},{"term":"toothbrush","meaning":"فرشاة أسنان","example":"Brush our teeth with a toothbrush.","number":664,"id":"a2:664","level":"A2","lessonId":"a2-set-27"},{"term":"around","meaning":"حول","example":"'Smoking is harmful, and even smoke from other people can cause a problem.' My friend Ben wanted to run around the park every day.","number":665,"id":"a2:665","level":"A2","lessonId":"a2-set-27"},{"term":"could","meaning":"يمكنه أو استطاع","example":"I could have hurt myself,' he admitted.","number":666,"id":"a2:666","level":"A2","lessonId":"a2-set-27"},{"term":"extra","meaning":"إضافي","example":"We made a list: find a safe path, carry extra water, brush our teeth with a toothbrush, and tidy up our equipment afterwards.","number":667,"id":"a2:667","level":"A2","lessonId":"a2-set-27"},{"term":"find","meaning":"يجد","example":"We made a list: find a safe path, carry extra water, brush our teeth with a toothbrush, and tidy up our equipment afterwards.","number":668,"id":"a2:668","level":"A2","lessonId":"a2-set-27"},{"term":"hold","meaning":"يمسك","example":"Hold the rail!' I called.","number":669,"id":"a2:669","level":"A2","lessonId":"a2-set-27"},{"term":"low","meaning":"منخفض","example":"But he rushed down a low step.","number":670,"id":"a2:670","level":"A2","lessonId":"a2-set-27"},{"term":"notice","meaning":"يلاحظ","example":"We also agreed to notice how we feel, not just the number on a scale.","number":671,"id":"a2:671","level":"A2","lessonId":"a2-set-27"},{"term":"probably","meaning":"على الأرجح","example":"After a month, we were probably stronger.","number":672,"id":"a2:672","level":"A2","lessonId":"a2-set-27"},{"term":"somewhere","meaning":"مكان ما","example":"Although there was still somewhere to improve.","number":673,"id":"a2:673","level":"A2","lessonId":"a2-set-27"},{"term":"tidy up","meaning":"يرتب","example":"And tidy up our equipment afterwards.","number":674,"id":"a2:674","level":"A2","lessonId":"a2-set-27"},{"term":"which","meaning":"أي","example":"The coach asked which activity we liked best.","number":675,"id":"a2:675","level":"A2","lessonId":"a2-set-27"}],"story":{"title":"The Fitness Experiment","paragraphs":["Our class decided to test how to get fit in four weeks. A coach at the gym asked us to check our habits. 'A healthy body needs movement, sleep and good food,' she said. 'Smoking is harmful, and even smoke from other people can cause a problem.'","My friend Ben wanted to run around the park every day. But he rushed down a low step, began to fall over and nearly hit the ground. 'Hold the rail!' I called. Luckily he caught it. 'I could have hurt myself,' he admitted. The coach explained that a dangerous accident can make someone seriously ill or even die, so we must be careful.","We made a list: find a safe path, carry extra water, brush our teeth with a toothbrush, and tidy up our equipment afterwards. The coach asked which activity we liked best. Ben chose swimming; I chose walking. We also agreed to notice how we feel, not just the number on a scale.","After a month, we were probably stronger. We could walk farther without stopping, although there was still somewhere to improve. 'The experiment is not dead,' Ben joked. 'It has only just begun!'"],"questions":["What did the class want to test?","What nearly happened to Ben?","Why did the coach ask pupils to notice their feelings?","What does Ben mean by saying the experiment has just begun?"]}},{"id":"a2-set-28","title":"The New Apartment","subtitle":"A2 reading adventure 28","level":"A2","set":28,"emoji":"🌱","color":"#37BE9C","words":[{"term":"armchair","meaning":"كرسي بذراعين","example":"My aunt smiled as she sat in the armchair.","number":676,"id":"a2:676","level":"A2","lessonId":"a2-set-28"},{"term":"bin","meaning":"سلة مهملات","example":"A ball rolled across the floor and knocked over the bin.","number":677,"id":"a2:677","level":"A2","lessonId":"a2-set-28"},{"term":"chair","meaning":"كرسي","example":"One spare chair and a box full of books.","number":678,"id":"a2:678","level":"A2","lessonId":"a2-set-28"},{"term":"dining room","meaning":"غرفة طعام","example":"There was a small dining room.","number":679,"id":"a2:679","level":"A2","lessonId":"a2-set-28"},{"term":"drawer","meaning":"درج","example":"I looked in a drawer for the repair number while Dad checked the water.","number":680,"id":"a2:680","level":"A2","lessonId":"a2-set-28"},{"term":"hall","meaning":"قاعة","example":"A bright hall and a bedroom with a tall wardrobe.","number":681,"id":"a2:681","level":"A2","lessonId":"a2-set-28"},{"term":"live","meaning":"يعيش","example":"We can live here happily,' she said.","number":682,"id":"a2:682","level":"A2","lessonId":"a2-set-28"},{"term":"sink","meaning":"حوض","example":"The kitchen had a sink, but the bathroom toilet was not working.","number":683,"id":"a2:683","level":"A2","lessonId":"a2-set-28"},{"term":"toilet","meaning":"مرحاض","example":"The kitchen had a sink, but the bathroom toilet was not working.","number":684,"id":"a2:684","level":"A2","lessonId":"a2-set-28"},{"term":"wardrobe","meaning":"خزانة ملابس","example":"A bright hall and a bedroom with a tall wardrobe.","number":685,"id":"a2:685","level":"A2","lessonId":"a2-set-28"},{"term":"closet","meaning":"خزانة ملابس","example":"She also had a wooden closet.","number":686,"id":"a2:686","level":"A2","lessonId":"a2-set-28"},{"term":"flat","meaning":"شقة","example":"My aunt moved into a new apartment, or flat, and invited us to help.","number":687,"id":"a2:687","level":"A2","lessonId":"a2-set-28"},{"term":"box","meaning":"صندوق","example":"As we moved the last box, a ball rolled across the floor and knocked over the bin.","number":688,"id":"a2:688","level":"A2","lessonId":"a2-set-28"},{"term":"almost","meaning":"تقريبا","example":"He said the problem was almost certainly a loose pipe.","number":689,"id":"a2:689","level":"A2","lessonId":"a2-set-28"},{"term":"as","meaning":"مثل أو بينما","example":"My aunt smiled as she sat in the armchair.","number":690,"id":"a2:690","level":"A2","lessonId":"a2-set-28"},{"term":"cry","meaning":"يبكي","example":"My little cousin began to cry.","number":691,"id":"a2:691","level":"A2","lessonId":"a2-set-28"},{"term":"fail","meaning":"يفشل","example":"If we fail to finish today, that is fine.","number":692,"id":"a2:692","level":"A2","lessonId":"a2-set-28"},{"term":"find out","meaning":"يكتشف","example":"Who can find out what is wrong?' she asked.","number":693,"id":"a2:693","level":"A2","lessonId":"a2-set-28"},{"term":"hope","meaning":"أمل أو يأمل","example":"I hope everything will fit,' she said.","number":694,"id":"a2:694","level":"A2","lessonId":"a2-set-28"},{"term":"luckily","meaning":"لحسن الحظ","example":"Luckily nothing broke.","number":695,"id":"a2:695","level":"A2","lessonId":"a2-set-28"},{"term":"now","meaning":"الآن","example":"Now the apartment was tidy.","number":696,"id":"a2:696","level":"A2","lessonId":"a2-set-28"},{"term":"put","meaning":"يضع","example":"Put the towels in the cupboard and sort the toys,' Auntie told us.","number":697,"id":"a2:697","level":"A2","lessonId":"a2-set-28"},{"term":"sort","meaning":"نوع أو يفرز","example":"Put the towels in the cupboard and sort the toys,' Auntie told us.","number":698,"id":"a2:698","level":"A2","lessonId":"a2-set-28"},{"term":"till","meaning":"حتى","example":"We worked till lunchtime.","number":699,"id":"a2:699","level":"A2","lessonId":"a2-set-28"},{"term":"who","meaning":"من","example":"Who can find out what is wrong?' she asked.","number":700,"id":"a2:700","level":"A2","lessonId":"a2-set-28"}],"story":{"title":"The New Apartment","paragraphs":["My aunt moved into a new apartment, or flat, and invited us to help. 'I hope everything will fit,' she said. There was a small dining room, a bright hall and a bedroom with a tall wardrobe. She also had a wooden closet, an armchair, one spare chair and a box full of books.","The kitchen had a sink, but the bathroom toilet was not working. My little cousin began to cry. 'Who can find out what is wrong?' she asked. I looked in a drawer for the repair number while Dad checked the water. He said the problem was almost certainly a loose pipe.","'If we fail to finish today, that is fine. Put the towels in the cupboard and sort the toys,' Auntie told us. We worked till lunchtime. As we moved the last box, a ball rolled across the floor and knocked over the bin. 'Oh no!' I shouted. Luckily nothing broke.","Now the apartment was tidy. My aunt smiled as she sat in the armchair. 'We can live here happily,' she said. 'A home is not just furniture; it is the people who care for one another.'"],"questions":["What problem did the family find in the bathroom?","How did the narrator help investigate it?","What small accident happened while moving boxes?","What is Auntie’s main idea about a home?"]}},{"id":"a2-set-29","title":"The Power-Cut Detective","subtitle":"A2 reading adventure 29","level":"A2","set":29,"emoji":"🌱","color":"#37BE9C","words":[{"term":"bath","meaning":"حمام للاستحمام","example":"The cold air must stay inside.' I was in the bath when the power failed.","number":701,"id":"a2:701","level":"A2","lessonId":"a2-set-29"},{"term":"cupboard","meaning":"خزانة","example":"Dad checked the cupboard downstairs, where the spare torch was kept.","number":702,"id":"a2:702","level":"A2","lessonId":"a2-set-29"},{"term":"downstairs","meaning":"في الطابق السفلي","example":"Dad checked the cupboard downstairs, where the spare torch was kept.","number":703,"id":"a2:703","level":"A2","lessonId":"a2-set-29"},{"term":"furniture","meaning":"أثاث","example":"As well as checking the furniture for a safe path.","number":704,"id":"a2:704","level":"A2","lessonId":"a2-set-29"},{"term":"refrigerator","meaning":"ثلاجة","example":"Do not open the refrigerator again,' she said.","number":705,"id":"a2:705","level":"A2","lessonId":"a2-set-29"},{"term":"shower","meaning":"دش","example":"My sister had just finished a shower.","number":706,"id":"a2:706","level":"A2","lessonId":"a2-set-29"},{"term":"towel","meaning":"منشفة","example":"Took out a towel and dried the wet floor near the sink.","number":707,"id":"a2:707","level":"A2","lessonId":"a2-set-29"},{"term":"washing machine","meaning":"غسالة ملابس","example":"Then the refrigerator and washing machine went silent.","number":708,"id":"a2:708","level":"A2","lessonId":"a2-set-29"},{"term":"heating","meaning":"تدفئة","example":"First, the heating stopped; then the refrigerator and washing machine went silent.","number":709,"id":"a2:709","level":"A2","lessonId":"a2-set-29"},{"term":"oven","meaning":"فرن","example":"The oven had stopped too, so we could not cook.","number":710,"id":"a2:710","level":"A2","lessonId":"a2-set-29"},{"term":"fridge","meaning":"ثلاجة","example":"Mum opened the fridge, took out a towel and dried the wet floor near the sink.","number":711,"id":"a2:711","level":"A2","lessonId":"a2-set-29"},{"term":"stay","meaning":"يبقى","example":"The cold air must stay inside.' I was in the bath when the power failed.","number":712,"id":"a2:712","level":"A2","lessonId":"a2-set-29"},{"term":"of","meaning":"من","example":"Of course we did not touch it.","number":713,"id":"a2:713","level":"A2","lessonId":"a2-set-29"},{"term":"along","meaning":"على طول","example":"And we were meant to cycle along the river after lunch.","number":714,"id":"a2:714","level":"A2","lessonId":"a2-set-29"},{"term":"as well","meaning":"أيضا","example":"As well as checking the furniture for a safe path.","number":715,"id":"a2:715","level":"A2","lessonId":"a2-set-29"},{"term":"cycle","meaning":"يركب الدراجة","example":"And we were meant to cycle along the river after lunch.","number":716,"id":"a2:716","level":"A2","lessonId":"a2-set-29"},{"term":"fan","meaning":"مروحة أو معجب","example":"The whole house was dark, but a little fan still worked on batteries.","number":717,"id":"a2:717","level":"A2","lessonId":"a2-set-29"},{"term":"first","meaning":"أول","example":"First, the heating stopped; then the refrigerator and washing machine went silent.","number":718,"id":"a2:718","level":"A2","lessonId":"a2-set-29"},{"term":"horrible","meaning":"فظيع","example":"What a horrible day!' my brother said.","number":719,"id":"a2:719","level":"A2","lessonId":"a2-set-29"},{"term":"lunchtime","meaning":"وقت الغداء","example":"At lunchtime, all the lights in our house went off.","number":720,"id":"a2:720","level":"A2","lessonId":"a2-set-29"},{"term":"number","meaning":"رقم","example":"We counted the number of rooms without light.","number":721,"id":"a2:721","level":"A2","lessonId":"a2-set-29"},{"term":"quickly","meaning":"بسرعة","example":"The worker arrived quickly and found a damaged wire outside.","number":722,"id":"a2:722","level":"A2","lessonId":"a2-set-29"},{"term":"spare","meaning":"احتياطي","example":"Dad checked the cupboard downstairs, where the spare torch was kept.","number":723,"id":"a2:723","level":"A2","lessonId":"a2-set-29"},{"term":"timetable","meaning":"جدول مواعيد","example":"Once the power returned, we changed the timetable and went cycling later.","number":724,"id":"a2:724","level":"A2","lessonId":"a2-set-29"},{"term":"whole","meaning":"كامل","example":"The whole house was dark, but a little fan still worked on batteries.","number":725,"id":"a2:725","level":"A2","lessonId":"a2-set-29"}],"story":{"title":"The Power-Cut Detective","paragraphs":["At lunchtime, all the lights in our house went off. First, the heating stopped; then the refrigerator and washing machine went silent. 'What a horrible day!' my brother said. Our timetable was full, and we were meant to cycle along the river after lunch.","Dad checked the cupboard downstairs, where the spare torch was kept. Mum opened the fridge, took out a towel and dried the wet floor near the sink. The oven had stopped too, so we could not cook. 'Do not open the refrigerator again,' she said. 'The cold air must stay inside.'","I was in the bath when the power failed, so I put on a robe and came downstairs. My sister had just finished a shower. We counted the number of rooms without light. The whole house was dark, but a little fan still worked on batteries.","As well as checking the furniture for a safe path, Dad called an electrician. The worker arrived quickly and found a damaged wire outside. Of course we did not touch it. Once the power returned, we changed the timetable and went cycling later. We had solved a problem by staying calm."],"questions":["Which household machines stopped working?","Why did Mum ask people not to open the fridge?","What caused the power cut?","What helped the family handle the situation?"]}},{"id":"a2-set-30","title":"The Jobs Fair","subtitle":"A2 reading adventure 30","level":"A2","set":30,"emoji":"🌱","color":"#37BE9C","words":[{"term":"business","meaning":"عمل تجاري","example":"There were pictures of a factory, a business office and a busy hotel.","number":726,"id":"a2:726","level":"A2","lessonId":"a2-set-30"},{"term":"career","meaning":"مسار مهني","example":"At our school jobs fair, every adult told us about a different career.","number":727,"id":"a2:727","level":"A2","lessonId":"a2-set-30"},{"term":"earn","meaning":"يكسب","example":"A scientist showed how to earn money by solving a problem.","number":728,"id":"a2:728","level":"A2","lessonId":"a2-set-30"},{"term":"journalist","meaning":"صحفي","example":"A journalist wrote a report about the event.","number":729,"id":"a2:729","level":"A2","lessonId":"a2-set-30"},{"term":"occupation","meaning":"مهنة","example":"Any occupation can be interesting,' our teacher said.","number":730,"id":"a2:730","level":"A2","lessonId":"a2-set-30"},{"term":"queen","meaning":"ملكة","example":"An actor wore a silver crown and pretended to be a queen.","number":731,"id":"a2:731","level":"A2","lessonId":"a2-set-30"},{"term":"secretary","meaning":"سكرتير","example":"While a secretary and an assistant answered questions.","number":732,"id":"a2:732","level":"A2","lessonId":"a2-set-30"},{"term":"assistant","meaning":"مساعد","example":"While a secretary and an assistant answered questions.","number":733,"id":"a2:733","level":"A2","lessonId":"a2-set-30"},{"term":"factory","meaning":"مصنع","example":"There were pictures of a factory, a business office and a busy hotel.","number":734,"id":"a2:734","level":"A2","lessonId":"a2-set-30"},{"term":"cleaner","meaning":"عامل نظافة","example":"The hotel cleaner explained how the staff work together.","number":735,"id":"a2:735","level":"A2","lessonId":"a2-set-30"},{"term":"staff","meaning":"طاقم العمل","example":"The hotel cleaner explained how the staff work together.","number":736,"id":"a2:736","level":"A2","lessonId":"a2-set-30"},{"term":"break","meaning":"يكسر أو استراحة","example":"I gave mine and took a short break.","number":737,"id":"a2:737","level":"A2","lessonId":"a2-set-30"},{"term":"adult","meaning":"شخص بالغ","example":"At our school jobs fair, every adult","number":738,"id":"a2:738","level":"A2","lessonId":"a2-set-30"},{"term":"among","meaning":"بين مجموعة","example":"But kindness matters among colleagues too.' At the next table.","number":739,"id":"a2:739","level":"A2","lessonId":"a2-set-30"},{"term":"at all","meaning":"على الإطلاق","example":"Don't be mad at yourself if you cannot decide at all today,' I told him.","number":740,"id":"a2:740","level":"A2","lessonId":"a2-set-30"},{"term":"dear","meaning":"عزيز","example":"Dear visitors, I rule this classroom!' she announced.","number":741,"id":"a2:741","level":"A2","lessonId":"a2-set-30"},{"term":"fantastic","meaning":"رائع","example":"The actor showed us a fantastic costume and asked for our first name.","number":742,"id":"a2:742","level":"A2","lessonId":"a2-set-30"},{"term":"first name","meaning":"الاسم الأول","example":"The actor showed us a fantastic costume and asked for our first name.","number":743,"id":"a2:743","level":"A2","lessonId":"a2-set-30"},{"term":"how","meaning":"كيف","example":"How do you choose a job?' I asked.","number":744,"id":"a2:744","level":"A2","lessonId":"a2-set-30"},{"term":"mad","meaning":"غاضب جدا","example":"Don't be mad at yourself if you cannot decide at all today,' I told him.","number":745,"id":"a2:745","level":"A2","lessonId":"a2-set-30"},{"term":"of course","meaning":"بالطبع","example":"'Of course we have years to learn.' We left with a list of jobs whose skills we wanted to explore together.","number":746,"id":"a2:746","level":"A2","lessonId":"a2-set-30"},{"term":"silver","meaning":"فضة","example":"An actor wore a silver crown and pretended to be a queen.","number":747,"id":"a2:747","level":"A2","lessonId":"a2-set-30"},{"term":"special","meaning":"خاص","example":"A special talent is helpful.","number":748,"id":"a2:748","level":"A2","lessonId":"a2-set-30"},{"term":"together","meaning":"معا","example":"The hotel cleaner explained how the staff work together.","number":749,"id":"a2:749","level":"A2","lessonId":"a2-set-30"},{"term":"whose","meaning":"لمن","example":"'Of course we have years to learn.' We left with a list of jobs whose skills we wanted to explore together.","number":750,"id":"a2:750","level":"A2","lessonId":"a2-set-30"}],"story":{"title":"The Jobs Fair","paragraphs":["At our school jobs fair, every adult told us about a different career. A journalist wrote a report about the event, while a secretary and an assistant answered questions. There were pictures of a factory, a business office and a busy hotel. 'Any occupation can be interesting,' our teacher said.","The hotel cleaner explained how the staff work together. A scientist showed how to earn money by solving a problem. 'How do you choose a job?' I asked. 'Think about what you enjoy,' she said. 'A special talent is helpful, but kindness matters among colleagues too.'","At the next table, an actor wore a silver crown and pretended to be a queen. 'Dear visitors, I rule this classroom!' she announced. We laughed. The actor showed us a fantastic costume and asked for our first name. I gave mine and took a short break.","My friend thought the careers looked too difficult. 'Don't be mad at yourself if you cannot decide at all today,' I told him. 'Of course we have years to learn.' We left with a list of jobs whose skills we wanted to explore together."],"questions":["Which workers answered questions at the fair?","What advice did the scientist give about choosing a career?","Why was there a queen at the fair?","What did the narrator tell a worried friend?"]}},{"id":"a2-set-31","title":"The Very Busy Hotel","subtitle":"A2 reading adventure 31","level":"A2","set":31,"emoji":"🌱","color":"#37BE9C","words":[{"term":"receptionist","meaning":"موظف استقبال","example":"A good hotel needs a team,' the receptionist said.","number":751,"id":"a2:751","level":"A2","lessonId":"a2-set-31"},{"term":"tour guide","meaning":"مرشد سياحي","example":"That cat is too comfortable to move!' said the tour guide.","number":752,"id":"a2:752","level":"A2","lessonId":"a2-set-31"},{"term":"police officer","meaning":"ضابط شرطة","example":"A police officer who was off duty offered to help.","number":753,"id":"a2:753","level":"A2","lessonId":"a2-set-31"},{"term":"work","meaning":"يعمل","example":"Her working hours began early, but she loved her work.","number":754,"id":"a2:754","level":"A2","lessonId":"a2-set-31"},{"term":"working hours","meaning":"ساعات العمل","example":"Her working hours began early, but she loved her work.","number":755,"id":"a2:755","level":"A2","lessonId":"a2-set-31"},{"term":"guide","meaning":"مرشد","example":"That cat is too comfortable to move!' said the tour guide.","number":756,"id":"a2:756","level":"A2","lessonId":"a2-set-31"},{"term":"visitor","meaning":"زائر","example":"The hotel staff had to make every visitor feel welcome.","number":757,"id":"a2:757","level":"A2","lessonId":"a2-set-31"},{"term":"king","meaning":"ملك","example":"The technician soon fixed the light, and the king arrived on time.","number":758,"id":"a2:758","level":"A2","lessonId":"a2-set-31"},{"term":"straight","meaning":"مستقيم","example":"The receptionist checked the list and pointed straight along the hall.","number":759,"id":"a2:759","level":"A2","lessonId":"a2-set-31"},{"term":"way","meaning":"طريقة أو طريق","example":"She had found the way to turn a difficult morning into a success.","number":760,"id":"a2:760","level":"A2","lessonId":"a2-set-31"},{"term":"police","meaning":"شرطة","example":"A police officer who was off duty offered to help.","number":761,"id":"a2:761","level":"A2","lessonId":"a2-set-31"},{"term":"light","meaning":"ضوء أو خفيف","example":"The technician soon fixed the light, and the king arrived on time.","number":762,"id":"a2:762","level":"A2","lessonId":"a2-set-31"},{"term":"page","meaning":"صفحة","example":"One guest asked, 'Is another room available?' A second guest needed a folder and a stamp for his travel page.","number":763,"id":"a2:763","level":"A2","lessonId":"a2-set-31"},{"term":"another","meaning":"آخر","example":"One guest asked, 'Is another room available?' A second guest needed a folder and a stamp for his travel page.","number":764,"id":"a2:764","level":"A2","lessonId":"a2-set-31"},{"term":"available","meaning":"متاح","example":"One guest asked, 'Is another room available?' A second guest needed a folder and a stamp for his travel page.","number":765,"id":"a2:765","level":"A2","lessonId":"a2-set-31"},{"term":"deep","meaning":"عميق","example":"The corridor seemed deep and narrow, and a fat cat sat in the way.","number":766,"id":"a2:766","level":"A2","lessonId":"a2-set-31"},{"term":"fat","meaning":"سمين","example":"The corridor seemed deep and narrow, and a fat cat sat in the way.","number":767,"id":"a2:767","level":"A2","lessonId":"a2-set-31"},{"term":"folder","meaning":"مجلد","example":"One guest asked, 'Is another room available?' A second guest needed a folder and a stamp for his travel page.","number":768,"id":"a2:768","level":"A2","lessonId":"a2-set-31"},{"term":"hurry","meaning":"يستعجل","example":"'Don't hurry through the dark.' A porter opened a door and shone a light on the steps.","number":769,"id":"a2:769","level":"A2","lessonId":"a2-set-31"},{"term":"make","meaning":"يصنع","example":"The hotel staff had to make every visitor feel welcome.","number":770,"id":"a2:770","level":"A2","lessonId":"a2-set-31"},{"term":"off","meaning":"مطفأ أو بعيد","example":"Suddenly the lights went off.","number":771,"id":"a2:771","level":"A2","lessonId":"a2-set-31"},{"term":"quite","meaning":"إلى حد ما","example":"The power problem is quite small,' he said.","number":772,"id":"a2:772","level":"A2","lessonId":"a2-set-31"},{"term":"stamp","meaning":"طابع بريدي","example":"One guest asked, 'Is another room available?' A second guest needed a folder and a stamp for his travel page.","number":773,"id":"a2:773","level":"A2","lessonId":"a2-set-31"},{"term":"too","meaning":"أيضا أو جدا","example":"That cat is too comfortable to move!' said the tour guide.","number":774,"id":"a2:774","level":"A2","lessonId":"a2-set-31"},{"term":"why","meaning":"لماذا","example":"Why is everyone here today?' she laughed.","number":775,"id":"a2:775","level":"A2","lessonId":"a2-set-31"}],"story":{"title":"The Very Busy Hotel","paragraphs":["The receptionist at the Grand Hotel was having a busy morning. A tour guide needed a map for her visitors, a police officer wanted to speak to the manager, and the king of a nearby country was arriving for a meeting. 'Why is everyone here today?' she laughed.","Her working hours began early, but she loved her work. The hotel staff had to make every visitor feel welcome. One guest asked, 'Is another room available?' A second guest needed a folder and a stamp for his travel page. The receptionist checked the list and pointed straight along the hall.","Suddenly the lights went off. A police officer who was off duty offered to help. 'The power problem is quite small,' he said. 'Don't hurry through the dark.' A porter opened a door and shone a light on the steps. The corridor seemed deep and narrow, and a fat cat sat in the way.","'That cat is too comfortable to move!' said the tour guide. Everyone laughed. The technician soon fixed the light, and the king arrived on time. 'A good hotel needs a team,' the receptionist said. She had found the way to turn a difficult morning into a success."],"questions":["Which important visitor was arriving?","What unexpected problem happened?","Why did the officer ask guests not to hurry?","What does the receptionist believe makes a good hotel?"]}},{"id":"a2-set-32","title":"The Fair Decision","subtitle":"A2 reading adventure 32","level":"A2","set":32,"emoji":"🌱","color":"#37BE9C","words":[{"term":"opinion","meaning":"رأي","example":"'Both are excellent.' Each pupil had a different opinion about what would be fair.","number":776,"id":"a2:776","level":"A2","lessonId":"a2-set-32"},{"term":"reason","meaning":"سبب","example":"'But your reason must be more than a feeling.' The class discussed the same problem from similar points of view.","number":777,"id":"a2:777","level":"A2","lessonId":"a2-set-32"},{"term":"fair","meaning":"عادل","example":"It is pretty easy to be fair when you believe everyone deserves a chance.","number":778,"id":"a2:778","level":"A2","lessonId":"a2-set-32"},{"term":"hate","meaning":"يكره","example":"Some students said, \"I hate competition,\" because a bad result made them unhappy or upset.","number":779,"id":"a2:779","level":"A2","lessonId":"a2-set-32"},{"term":"upset","meaning":"منزعج","example":"Because a bad result made them unhappy or upset.","number":780,"id":"a2:780","level":"A2","lessonId":"a2-set-32"},{"term":"unhappy","meaning":"غير سعيد","example":"Because a bad result made them unhappy or upset.","number":781,"id":"a2:781","level":"A2","lessonId":"a2-set-32"},{"term":"believe","meaning":"يصدق أو يعتقد","example":"It is pretty easy to be fair when you believe everyone deserves a chance.","number":782,"id":"a2:782","level":"A2","lessonId":"a2-set-32"},{"term":"different","meaning":"مختلف","example":"'Both are excellent.' Each pupil had a different opinion about what would be fair.","number":783,"id":"a2:783","level":"A2","lessonId":"a2-set-32"},{"term":"same","meaning":"نفس الشيء","example":"'But your reason must be more than a feeling.' The class discussed the same problem from similar points of view.","number":784,"id":"a2:784","level":"A2","lessonId":"a2-set-32"},{"term":"similar","meaning":"مشابه","example":"'But your reason must be more than a feeling.' The class discussed the same problem from similar points of view.","number":785,"id":"a2:785","level":"A2","lessonId":"a2-set-32"},{"term":"possible","meaning":"ممكن","example":"It is possible that you are both right about some things.","number":786,"id":"a2:786","level":"A2","lessonId":"a2-set-32"},{"term":"impossible","meaning":"مستحيل","example":"It is impossible to choose,' said the teacher.","number":787,"id":"a2:787","level":"A2","lessonId":"a2-set-32"},{"term":"able","meaning":"قادر","example":"Sam was able to organise games, and Lina was interested in helping new players.","number":788,"id":"a2:788","level":"A2","lessonId":"a2-set-32"},{"term":"alone","meaning":"وحيدا","example":"One boy joked, 'I want to be captain alone so I can have a free afternoon!' The teacher laughed.","number":789,"id":"a2:789","level":"A2","lessonId":"a2-set-32"},{"term":"bad","meaning":"سيئ","example":"Because a bad result made them unhappy or upset.","number":790,"id":"a2:790","level":"A2","lessonId":"a2-set-32"},{"term":"boring","meaning":"ممل","example":"This is not a boring discussion,\" joked the teacher.","number":791,"id":"a2:791","level":"A2","lessonId":"a2-set-32"},{"term":"busy","meaning":"مشغول","example":"Lina thought Sam was sometimes too busy to listen.","number":792,"id":"a2:792","level":"A2","lessonId":"a2-set-32"},{"term":"excellent","meaning":"ممتاز","example":"'Both are excellent.' Each pupil had a different opinion about what would be fair.","number":793,"id":"a2:793","level":"A2","lessonId":"a2-set-32"},{"term":"favourite","meaning":"مفضل","example":"Others said it was their favourite part of sport.","number":794,"id":"a2:794","level":"A2","lessonId":"a2-set-32"},{"term":"free","meaning":"مجاني","example":"One boy joked, 'I want to be captain alone so I can have a free afternoon!' The teacher laughed.","number":795,"id":"a2:795","level":"A2","lessonId":"a2-set-32"},{"term":"hard","meaning":"صعب أو صلب","example":"A hard decision can have a nice ending,' said the teacher.","number":796,"id":"a2:796","level":"A2","lessonId":"a2-set-32"},{"term":"interested","meaning":"مهتم","example":"And Lina was interested in helping new players.","number":797,"id":"a2:797","level":"A2","lessonId":"a2-set-32"},{"term":"nice","meaning":"لطيف","example":"A hard decision can have a nice ending,' said the teacher.","number":798,"id":"a2:798","level":"A2","lessonId":"a2-set-32"},{"term":"pretty","meaning":"جميل","example":"It is pretty easy to be fair when you believe everyone deserves a chance.","number":799,"id":"a2:799","level":"A2","lessonId":"a2-set-32"},{"term":"real","meaning":"حقيقي","example":"That is not a real plan.' They agreed to share the work.","number":800,"id":"a2:800","level":"A2","lessonId":"a2-set-32"}],"story":{"title":"The Fair Decision","paragraphs":["Two pupils wanted to be captain of the school team, but there was only one position. 'It is impossible to choose,' said the teacher. 'Both are excellent.' Each pupil had a different opinion about what would be fair.","Sam was able to organise games, and Lina was interested in helping new players. Sam thought Lina was too quiet; Lina thought Sam was sometimes too busy to listen. 'It is possible that you are both right about some things,' said the teacher. 'But your reason must be more than a feeling.'","The class discussed the same problem from similar points of view. Some students said, \"I hate competition,\" because a bad result made them unhappy or upset. Others said it was their favourite part of sport. \"This is not a boring discussion,\" joked the teacher. One boy joked, 'I want to be captain alone so I can have a free afternoon!' The teacher laughed. 'That is not a real plan.'","They agreed to share the work. Sam led the games, while Lina welcomed new children. 'A hard decision can have a nice ending,' said the teacher. 'It is pretty easy to be fair when you believe everyone deserves a chance.'"],"questions":["Why was choosing a captain difficult?","What different strengths did Sam and Lina have?","How did the class solve the disagreement?","What does the story suggest about fairness?"]}},{"id":"a2-set-33","title":"The Great Timetable Puzzle","subtitle":"A2 reading adventure 33","level":"A2","set":33,"emoji":"🌱","color":"#37BE9C","words":[{"term":"daily","meaning":"يوميا","example":"Our school made a daily timetable for its hundredth birthday.","number":801,"id":"a2:801","level":"A2","lessonId":"a2-set-33"},{"term":"monthly","meaning":"شهريا","example":"There would be a weekly history quiz and a monthly exhibition.","number":802,"id":"a2:802","level":"A2","lessonId":"a2-set-33"},{"term":"weekly","meaning":"أسبوعيا","example":"There would be a weekly history quiz and a monthly exhibition.","number":803,"id":"a2:803","level":"A2","lessonId":"a2-set-33"},{"term":"noon","meaning":"الظهيرة","example":"At noon on Friday, each class would open a time capsule containing a message from the past.","number":804,"id":"a2:804","level":"A2","lessonId":"a2-set-33"},{"term":"tonight","meaning":"الليلة","example":"Tonight, however, we discovered a strange problem: someone tried to steal our model!","number":805,"id":"a2:805","level":"A2","lessonId":"a2-set-33"},{"term":"moment","meaning":"لحظة","example":"They remembered the moment the first class opened.","number":806,"id":"a2:806","level":"A2","lessonId":"a2-set-33"},{"term":"past","meaning":"الماضي","example":"Each class would open a time capsule containing a message from the past.","number":807,"id":"a2:807","level":"A2","lessonId":"a2-set-33"},{"term":"ago","meaning":"منذ","example":"It was built a hundred years ago,' said the teacher.","number":808,"id":"a2:808","level":"A2","lessonId":"a2-set-33"},{"term":"aged","meaning":"يبلغ من العمر","example":"Some former pupils were now aged ninety.","number":809,"id":"a2:809","level":"A2","lessonId":"a2-set-33"},{"term":"age","meaning":"عمر","example":"What is the age of our school exactly?' asked Mia.","number":810,"id":"a2:810","level":"A2","lessonId":"a2-set-33"},{"term":"century","meaning":"قرن","example":"We learned that a century means one hundred years.","number":811,"id":"a2:811","level":"A2","lessonId":"a2-set-33"},{"term":"degree","meaning":"درجة","example":"And every degree mattered to our weather chart.","number":812,"id":"a2:812","level":"A2","lessonId":"a2-set-33"},{"term":"litre","meaning":"لتر","example":"We used a metre rule for the path and a litre jug for the fountain.","number":813,"id":"a2:813","level":"A2","lessonId":"a2-set-33"},{"term":"metre","meaning":"متر","example":"We used a metre rule for the path and a litre jug for the fountain.","number":814,"id":"a2:814","level":"A2","lessonId":"a2-set-33"},{"term":"awesome","meaning":"رائع جدا","example":"Our group had an awesome idea.","number":815,"id":"a2:815","level":"A2","lessonId":"a2-set-33"},{"term":"deliver","meaning":"يوصل","example":"Measure the old garden and deliver a model of it.","number":816,"id":"a2:816","level":"A2","lessonId":"a2-set-33"},{"term":"feelings","meaning":"مشاعر","example":"We recorded our feelings in a diary.","number":817,"id":"a2:817","level":"A2","lessonId":"a2-set-33"},{"term":"forget","meaning":"ينسى","example":"Do not forget to look carefully before deciding what the matter is.","number":818,"id":"a2:818","level":"A2","lessonId":"a2-set-33"},{"term":"idea","meaning":"فكرة","example":"Our best idea became a favourite memory.","number":819,"id":"a2:819","level":"A2","lessonId":"a2-set-33"},{"term":"matter","meaning":"أمر أو مشكلة","example":"Do not forget to look carefully before deciding what the matter is.","number":820,"id":"a2:820","level":"A2","lessonId":"a2-set-33"},{"term":"oh","meaning":"أوه","example":"Oh, really?' Mia cried.","number":821,"id":"a2:821","level":"A2","lessonId":"a2-set-33"},{"term":"really","meaning":"حقا","example":"Oh, really?' Mia cried.","number":822,"id":"a2:822","level":"A2","lessonId":"a2-set-33"},{"term":"steal","meaning":"يسرق","example":"Someone tried to steal our model.","number":823,"id":"a2:823","level":"A2","lessonId":"a2-set-33"},{"term":"top","meaning":"أعلى","example":"The headteacher checked the security camera and found a wild squirrel sitting on top of it.","number":824,"id":"a2:824","level":"A2","lessonId":"a2-set-33"},{"term":"wild","meaning":"بري","example":"The headteacher checked the security camera and found a wild squirrel sitting on top of it.","number":825,"id":"a2:825","level":"A2","lessonId":"a2-set-33"}],"story":{"title":"The Great Timetable Puzzle","paragraphs":["Our school made a daily timetable for its hundredth birthday. There would be a weekly history quiz and a monthly exhibition. At noon on Friday, each class would open a time capsule containing a message from the past.","We learned that a century means one hundred years. 'What is the age of our school exactly?' asked Mia. 'It was built a hundred years ago,' said the teacher. Some former pupils were now aged ninety. They remembered the moment the first class opened.","Our group had an awesome idea: measure the old garden and deliver a model of it. We used a metre rule for the path and a litre jug for the fountain. The temperature was twenty degrees, and every degree mattered to our weather chart, which was perfect for working outside. We recorded our feelings in a diary.","Tonight, however, we discovered a strange problem: someone tried to steal our model! 'Oh, really?' Mia cried. The headteacher checked the security camera and found a wild squirrel sitting on top of it. The animal had knocked over a sign, not taken the model at all.","'Do not forget to look carefully before deciding what the matter is,' said our teacher. We laughed and finished our project. Our best idea became a favourite memory."],"questions":["Why did the school prepare special activities?","How did the pupils measure the garden model?","What really disturbed the model?","What lesson did the mystery teach?"]}},{"id":"a2-set-34","title":"The Mountain Challenge","subtitle":"A2 reading adventure 34","level":"A2","set":34,"emoji":"🌱","color":"#37BE9C","words":[{"term":"sports centre","meaning":"مركز رياضي","example":"The sports centre organised a mountain challenge for every member of our outdoor club.","number":826,"id":"a2:826","level":"A2","lessonId":"a2-set-34"},{"term":"lucky","meaning":"محظوظ","example":"You are lucky you noticed it,' she told him.","number":827,"id":"a2:827","level":"A2","lessonId":"a2-set-34"},{"term":"luck","meaning":"حظ","example":"'Luck is helpful, but careful action matters too.' We decided to record our observations.","number":828,"id":"a2:828","level":"A2","lessonId":"a2-set-34"},{"term":"catch","meaning":"يمسك أو يلحق","example":"He was frightened, but he did not throw a stone or try to catch it.","number":829,"id":"a2:829","level":"A2","lessonId":"a2-set-34"},{"term":"fishing","meaning":"صيد السمك","example":"There would be cycling, climbing and a short fishing lesson.","number":830,"id":"a2:830","level":"A2","lessonId":"a2-set-34"},{"term":"path","meaning":"ممر","example":"We had to practise first because the narrow path was difficult in places.","number":831,"id":"a2:831","level":"A2","lessonId":"a2-set-34"},{"term":"riding","meaning":"ركوب","example":"One girl suggested riding a bike across.","number":832,"id":"a2:832","level":"A2","lessonId":"a2-set-34"},{"term":"table","meaning":"طاولة","example":"At lunchtime, a bird with a damaged wing landed beside our table.","number":833,"id":"a2:833","level":"A2","lessonId":"a2-set-34"},{"term":"throw","meaning":"يرمي","example":"He was frightened, but he did not throw a stone or try to catch it.","number":834,"id":"a2:834","level":"A2","lessonId":"a2-set-34"},{"term":"cycling","meaning":"ركوب الدراجة","example":"There would be cycling, climbing and a short fishing lesson.","number":835,"id":"a2:835","level":"A2","lessonId":"a2-set-34"},{"term":"member","meaning":"عضو","example":"The sports centre organised a mountain challenge for every member of our outdoor club.","number":836,"id":"a2:836","level":"A2","lessonId":"a2-set-34"},{"term":"suit","meaning":"بدلة رسمية","example":"Our guide wore a waterproof suit.","number":837,"id":"a2:837","level":"A2","lessonId":"a2-set-34"},{"term":"practise","meaning":"يتدرب","example":"We had to practise first because the","number":838,"id":"a2:838","level":"A2","lessonId":"a2-set-34"},{"term":"anybody","meaning":"أي شخص","example":"She asked, 'Can anybody describe the safest way to cross the bridge?' We began to discuss it.","number":839,"id":"a2:839","level":"A2","lessonId":"a2-set-34"},{"term":"awful","meaning":"فظيع","example":"But the guide said it was an awful idea.","number":840,"id":"a2:840","level":"A2","lessonId":"a2-set-34"},{"term":"describe","meaning":"يصف","example":"She asked, 'Can anybody describe the safest way to cross the bridge?' We began to discuss it.","number":841,"id":"a2:841","level":"A2","lessonId":"a2-set-34"},{"term":"discuss","meaning":"يناقش","example":"She asked, 'Can anybody describe the safest way to cross the bridge?' We began to discuss it.","number":842,"id":"a2:842","level":"A2","lessonId":"a2-set-34"},{"term":"frightened","meaning":"خائف","example":"He was frightened, but he did not throw a stone or try to catch it.","number":843,"id":"a2:843","level":"A2","lessonId":"a2-set-34"},{"term":"immediately","meaning":"فورا","example":"Instead, he immediately called the wildlife officer.","number":844,"id":"a2:844","level":"A2","lessonId":"a2-set-34"},{"term":"maybe","meaning":"ربما","example":"Maybe it needs help,' said Jay.","number":845,"id":"a2:845","level":"A2","lessonId":"a2-set-34"},{"term":"once","meaning":"مرة واحدة","example":"Once we were home, each pupil chose a topic for a short report.","number":846,"id":"a2:846","level":"A2","lessonId":"a2-set-34"},{"term":"record","meaning":"يسجل أو تسجيل","example":"But careful action matters too.' We decided to record our observations.","number":847,"id":"a2:847","level":"A2","lessonId":"a2-set-34"},{"term":"strange","meaning":"غريب","example":"Jay wrote about the strange bird.","number":848,"id":"a2:848","level":"A2","lessonId":"a2-set-34"},{"term":"topic","meaning":"موضوع","example":"Once we were home, each pupil chose a topic for a short report.","number":849,"id":"a2:849","level":"A2","lessonId":"a2-set-34"},{"term":"wing","meaning":"جناح","example":"At lunchtime, a bird with a damaged wing landed beside our table.","number":850,"id":"a2:850","level":"A2","lessonId":"a2-set-34"}],"story":{"title":"The Mountain Challenge","paragraphs":["The sports centre organised a mountain challenge for every member of our outdoor club. There would be cycling, climbing and a short fishing lesson. We had to practise first because the narrow path was difficult in places.","Our guide wore a waterproof suit. She asked, 'Can anybody describe the safest way to cross the bridge?' We began to discuss it. One girl suggested riding a bike across, but the guide said it was an awful idea. 'You might slip and fall. Walk and carry the bike instead.' Everyone agreed.","At lunchtime, a bird with a damaged wing landed beside our table. 'Maybe it needs help,' said Jay. He was frightened, but he did not throw a stone or try to catch it. Instead, he immediately called the wildlife officer. The officer arrived and put the bird in a safe box.","'You are lucky you noticed it,' she told him. 'Luck is helpful, but careful action matters too.' We decided to record our observations. Once we were home, each pupil chose a topic for a short report. Jay wrote about the strange bird. The challenge taught us to protect nature while enjoying our sport."],"questions":["What activities were included in the challenge?","Why did the guide stop someone riding across the bridge?","What did Jay do when he saw an injured bird?","What was the most important lesson?"]}},{"id":"a2-set-35","title":"The Letter That Came Back","subtitle":"A2 reading adventure 35","level":"A2","set":35,"emoji":"🌱","color":"#37BE9C","words":[{"term":"comic","meaning":"قصة مصورة","example":"A funny guy in the comic beside it wore a bright trainer and dreamed of becoming an explorer.","number":851,"id":"a2:851","level":"A2","lessonId":"a2-set-35"},{"term":"form","meaning":"استمارة","example":"He filled in a form with his first name and surname.","number":852,"id":"a2:852","level":"A2","lessonId":"a2-set-35"},{"term":"penfriend","meaning":"صديق بالمراسلة","example":"A teenager called Adam wanted a penfriend in another country.","number":853,"id":"a2:853","level":"A2","lessonId":"a2-set-35"},{"term":"surname","meaning":"اسم العائلة","example":"He filled in a form with his first name and surname.","number":854,"id":"a2:854","level":"A2","lessonId":"a2-set-35"},{"term":"text","meaning":"نص أو رسالة","example":"That gave Adam an idea for his text: 'My dream is to travel.","number":855,"id":"a2:855","level":"A2","lessonId":"a2-set-35"},{"term":"postcard","meaning":"بطاقة بريدية","example":"He filled in a form with his first name and surname, then wrote a postcard.","number":856,"id":"a2:856","level":"A2","lessonId":"a2-set-35"},{"term":"envelope","meaning":"ظرف رسالة","example":"The envelope said the club had moved.","number":857,"id":"a2:857","level":"A2","lessonId":"a2-set-35"},{"term":"guy","meaning":"شاب","example":"A funny guy in the comic beside it wore a bright trainer and dreamed of becoming an explorer.","number":858,"id":"a2:858","level":"A2","lessonId":"a2-set-35"},{"term":"teenager","meaning":"مراهق","example":"A teenager called Adam wanted a penfriend in another country.","number":859,"id":"a2:859","level":"A2","lessonId":"a2-set-35"},{"term":"group","meaning":"مجموعة","example":"'Just improve the form.' The group helped him check the advert from the penfriend club.","number":860,"id":"a2:860","level":"A2","lessonId":"a2-set-35"},{"term":"above","meaning":"فوق","example":"He put it in an envelope and drew stripes above the address to make it look cheerful.","number":861,"id":"a2:861","level":"A2","lessonId":"a2-set-35"},{"term":"action","meaning":"فعل أو حركة","example":"His English teacher read the details and said, 'This is a lovely action, but the address is missing a number.' Adam felt badly about the mistake.","number":862,"id":"a2:862","level":"A2","lessonId":"a2-set-35"},{"term":"advert","meaning":"إعلان","example":"'Just improve the form.' The group helped him check the advert from the penfriend club.","number":863,"id":"a2:863","level":"A2","lessonId":"a2-set-35"},{"term":"anymore","meaning":"بعد الآن","example":"Does it mean I cannot send it anymore?' he asked.","number":864,"id":"a2:864","level":"A2","lessonId":"a2-set-35"},{"term":"badly","meaning":"بشكل سيئ","example":"But the address is missing a number.' Adam felt badly about the mistake.","number":865,"id":"a2:865","level":"A2","lessonId":"a2-set-35"},{"term":"details","meaning":"تفاصيل","example":"His English teacher read the details and said.","number":866,"id":"a2:866","level":"A2","lessonId":"a2-set-35"},{"term":"dream","meaning":"حلم","example":"That gave Adam an idea for his text: 'My dream is to travel.","number":867,"id":"a2:867","level":"A2","lessonId":"a2-set-35"},{"term":"from","meaning":"من","example":"'Just improve the form.' The group helped him check the advert from the penfriend club.","number":868,"id":"a2:868","level":"A2","lessonId":"a2-set-35"},{"term":"improve","meaning":"يحسن","example":"'Just improve the form.' The group helped him check the advert from the penfriend club.","number":869,"id":"a2:869","level":"A2","lessonId":"a2-set-35"},{"term":"mean","meaning":"يعني","example":"Does it mean I cannot send it anymore?' he asked.","number":870,"id":"a2:870","level":"A2","lessonId":"a2-set-35"},{"term":"only","meaning":"فقط","example":"I only need a friend to share stories with.' After school.","number":871,"id":"a2:871","level":"A2","lessonId":"a2-set-35"},{"term":"relaxing","meaning":"مريح للأعصاب","example":"The next letter reached his penfriend, and their relaxing exchange began.","number":872,"id":"a2:872","level":"A2","lessonId":"a2-set-35"},{"term":"stripes","meaning":"خطوط","example":"He put it in an envelope and drew stripes above the address to make it look cheerful.","number":873,"id":"a2:873","level":"A2","lessonId":"a2-set-35"},{"term":"trainer","meaning":"حذاء رياضي","example":"A funny guy in the comic beside it wore a bright trainer and dreamed of becoming an explorer.","number":874,"id":"a2:874","level":"A2","lessonId":"a2-set-35"},{"term":"wish","meaning":"أمنية أو يتمنى","example":"I wish I had checked the new address,' he laughed.","number":875,"id":"a2:875","level":"A2","lessonId":"a2-set-35"}],"story":{"title":"The Letter That Came Back","paragraphs":["A teenager called Adam wanted a penfriend in another country. He filled in a form with his first name and surname, then wrote a postcard. He put it in an envelope and drew stripes above the address to make it look cheerful.","His English teacher read the details and said, 'This is a lovely action, but the address is missing a number.' Adam felt badly about the mistake. 'Does it mean I cannot send it anymore?' he asked. 'Of course you can,' she said. 'Just improve the form.'","The group helped him check the advert from the penfriend club. A funny guy in the comic beside it wore a bright trainer and dreamed of becoming an explorer. That gave Adam an idea for his text: 'My dream is to travel. I only need a friend to share stories with.'","After school, Adam took the letter to the post office. A week later it came back again. The envelope said the club had moved. 'I wish I had checked the new address,' he laughed. The teacher reminded him that making mistakes was part of learning. The next letter reached his penfriend, and their relaxing exchange began."],"questions":["Why did Adam’s first postcard need changing?","Where did Adam find information about the club?","Why was the letter returned a second time?","What does Adam learn about language learning?"]}},{"id":"a2-set-36","title":"The Final Quest","subtitle":"A2 reading adventure 36","level":"A2","set":36,"emoji":"🌱","color":"#37BE9C","words":[{"term":"afraid","meaning":"خائف","example":"I was afraid to open the small door, but my friends helped.","number":876,"id":"a2:876","level":"A2","lessonId":"a2-set-36"},{"term":"amazed","meaning":"مندهش","example":"The picture was amazing, and we were amazed to find that the farmer was holding the most important clue.","number":877,"id":"a2:877","level":"A2","lessonId":"a2-set-36"},{"term":"amazing","meaning":"مذهل","example":"The picture was amazing, and we were amazed to find that the farmer was holding the most important clue.","number":878,"id":"a2:878","level":"A2","lessonId":"a2-set-36"},{"term":"careful","meaning":"حذر","example":"Tom wanted to run fast, but Sara said, 'Be careful.","number":879,"id":"a2:879","level":"A2","lessonId":"a2-set-36"},{"term":"difficult","meaning":"صعب","example":"This adventure may be difficult.","number":880,"id":"a2:880","level":"A2","lessonId":"a2-set-36"},{"term":"fast","meaning":"سريع","example":"Tom wanted to run fast, but Sara said, 'Be careful.","number":881,"id":"a2:881","level":"A2","lessonId":"a2-set-36"},{"term":"fine","meaning":"بخير","example":"We reached the next room feeling fine.","number":882,"id":"a2:882","level":"A2","lessonId":"a2-set-36"},{"term":"funny","meaning":"مضحك","example":"Inside was a funny painting of a rich king and a poor farmer.","number":883,"id":"a2:883","level":"A2","lessonId":"a2-set-36"},{"term":"great","meaning":"عظيم","example":"A great wooden door stood beside a lovely garden.","number":884,"id":"a2:884","level":"A2","lessonId":"a2-set-36"},{"term":"heavy","meaning":"ثقيل","example":"'This adventure may be difficult, but it will be interesting.' Our first task was to carry a heavy box across a soft carpet without making any noise.","number":885,"id":"a2:885","level":"A2","lessonId":"a2-set-36"},{"term":"important","meaning":"مهم","example":"The picture was amazing, and we were amazed to find that the farmer was holding the most important clue.","number":886,"id":"a2:886","level":"A2","lessonId":"a2-set-36"},{"term":"interesting","meaning":"مثير للاهتمام","example":"'This adventure may be difficult, but it will be interesting.' Our first task was to carry a heavy box across a soft carpet without making any noise.","number":887,"id":"a2:887","level":"A2","lessonId":"a2-set-36"},{"term":"noisy","meaning":"صاخب","example":"A sign said, 'Look high and low, but listen to the quietest voice.' We heard a noisy clock, then a pleasant little bell behind the wall.","number":888,"id":"a2:888","level":"A2","lessonId":"a2-set-36"},{"term":"old","meaning":"قديم","example":"The final quest began at an old castle on a quiet hill.","number":889,"id":"a2:889","level":"A2","lessonId":"a2-set-36"},{"term":"poor","meaning":"فقير","example":"Inside was a funny painting of a rich king and a poor farmer.","number":890,"id":"a2:890","level":"A2","lessonId":"a2-set-36"},{"term":"quick","meaning":"سريع","example":"It was not quick work.","number":891,"id":"a2:891","level":"A2","lessonId":"a2-set-36"},{"term":"ready","meaning":"مستعد","example":"Are you ready?' asked our guide.","number":892,"id":"a2:892","level":"A2","lessonId":"a2-set-36"},{"term":"rich","meaning":"غني","example":"Inside was a funny painting of a rich king and a poor farmer.","number":893,"id":"a2:893","level":"A2","lessonId":"a2-set-36"},{"term":"soft","meaning":"ناعم","example":"'This adventure may be difficult, but it will be interesting.' Our first task was to carry a heavy box across a soft carpet without making any noise.","number":894,"id":"a2:894","level":"A2","lessonId":"a2-set-36"},{"term":"good","meaning":"جيد","example":"Good work!","number":895,"id":"a2:895","level":"A2","lessonId":"a2-set-36"},{"term":"high","meaning":"عال","example":"A sign said, 'Look high and low, but listen to the quietest voice.' We heard a noisy clock, then a pleasant little bell behind the wall.","number":896,"id":"a2:896","level":"A2","lessonId":"a2-set-36"},{"term":"lovely","meaning":"جميل جدا","example":"A great wooden door stood beside a lovely garden.","number":897,"id":"a2:897","level":"A2","lessonId":"a2-set-36"},{"term":"pleasant","meaning":"لطيف","example":"Then a pleasant little bell behind the wall.","number":898,"id":"a2:898","level":"A2","lessonId":"a2-set-36"},{"term":"quiet","meaning":"هادئ","example":"The final quest began at an old castle on a quiet hill.","number":899,"id":"a2:899","level":"A2","lessonId":"a2-set-36"},{"term":"slow","meaning":"بطيء","example":"Going slow is safer.' She was right.","number":900,"id":"a2:900","level":"A2","lessonId":"a2-set-36"}],"story":{"title":"The Final Quest","paragraphs":["The final quest began at an old castle on a quiet hill. A great wooden door stood beside a lovely garden. 'Are you ready?' asked our guide. 'This adventure may be difficult, but it will be interesting.'","Our first task was to carry a heavy box across a soft carpet without making any noise. It was not quick work. Tom wanted to run fast, but Sara said, 'Be careful. Going slow is safer.' She was right. We reached the next room feeling fine.","Inside was a funny painting of a rich king and a poor farmer. The picture was amazing, and we were amazed to find that the farmer was holding the most important clue. A sign said, 'Look high and low, but listen to the quietest voice.'","We heard a noisy clock, then a pleasant little bell behind the wall. I was afraid to open the small door, but my friends helped. Beyond it was a bright room full of books. The guide smiled. 'Good work! You did not need to be the fastest to finish. You needed to work together.'","We celebrated our success. The quest had been hard at times, but our friendship made it a wonderful day."],"questions":["Where did the final quest begin?","Why did Sara advise Tom to move slowly?","What helped the group find the final room?","What is the main message of the story?"]}}]);
